    let inner = UiBounds { x: own.x + layout.padding[3], y: own.y + layout.padding[0], width: (own.width - layout.padding[1] - layout.padding[3]).max(0.0), height: (own.height - layout.padding[0] - layout.padding[2]).max(0.0) };
