    }
    fn require_revision(&self, expected: Revision) -> Result<(), UiTextRegistryError> { if expected == self.revision { Ok(()) } else { Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_STALE_REVISION, message: "text registry revision is stale" }) } }
    fn validate_text(&self, text: &str) -> Result<(), UiTextRegistryError> { if text.len() > self.max_bytes_per_record as usize { Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_TOO_LONG, message: "text exceeds the registry record byte limit" }) } else { Ok(()) } }
}

