#[derive(Clone, Debug, PartialEq)]
pub struct UiSurfaceTransition {
    pub snapshot: UiSurfaceSnapshot,
    pub effects: Vec<UiEffect>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct UiSurfaceMachine { surface_id: UiSurfaceId, revision: Revision, state: UiSurfaceState }

impl UiSurfaceMachine {
    fn new(surface_id: UiSurfaceId) -> Self {
        Self { surface_id, revision: Revision(0), state: UiSurfaceState { diagnostics: UiDiagnosticsState::Collapsed, inspector: UiInspectorState { tab: UiInspectorTab::Overview } } }
    }

    fn snapshot(&self) -> UiSurfaceSnapshot {
        UiSurfaceSnapshot { schema_version: UI_SURFACE_SCHEMA_VERSION, surface_id: self.surface_id.clone(), revision: self.revision, value: self.state.clone(), available_events: vec![UiSurfaceEventKind::DiagnosticsToggle, UiSurfaceEventKind::InspectorTabSelect] }
    }

    fn transition(&mut self, event: UiSurfaceEvent) -> Result<UiSurfaceTransition, (&'static str, &'static str)> {
        match event {
            UiSurfaceEvent::DiagnosticsToggle => {
                self.state.diagnostics = match self.state.diagnostics { UiDiagnosticsState::Collapsed => UiDiagnosticsState::Expanded, UiDiagnosticsState::Expanded => UiDiagnosticsState::Collapsed };
            }
            UiSurfaceEvent::InspectorTabSelect { tab } => {
                if self.state.inspector.tab == tab { return Err(("ui_guard_rejected", "inspector tab is already selected")); }
                self.state.inspector.tab = tab;
            }
        }
        self.revision = Revision(self.revision.0 + 1);
        Ok(UiSurfaceTransition { snapshot: self.snapshot(), effects: Vec::new() })
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)] pub enum UiInputWriter { External, LocalPresentation }
#[derive(Clone, Debug, PartialEq)] pub struct UiInputApplyResult { pub input_revision: Revision, pub changed_slots: Vec<String>, pub snapshot: UiResolvedInputs }
#[derive(Clone, Debug, PartialEq, Eq)] pub struct UiInputStoreError { pub code: &'static str, pub message: &'static str }
impl UiInputStoreError { fn schema(error: UiSchemaError) -> Self { match error { UiSchemaError::DuplicateInputKey => Self { code: "ui_program_duplicate_input_key", message: "input schema contains a duplicate slot key" }, UiSchemaError::InvalidInputDefault => Self { code: "ui_program_invalid_default", message: "input slot default does not match its declared kind" }, _ => Self { code: "ui_program_invalid_input_schema", message: "input schema is invalid" } } } }
/// CPU-only transactional input state. Defaults are installed at activation;
/// WGPU is deliberately absent from this supported headless API.
#[derive(Clone, Debug)] pub struct UiInputStore { schema: UiInputSchema, resolved_inputs: UiResolvedInputs, dirty_slots: HashSet<String>, idempotent_results: HashMap<String, UiInputApplyResult> }
impl UiInputStore {
    pub fn activate(program_revision: UiProgramRevision, schema: UiInputSchema) -> Result<Self, UiInputStoreError> { program_revision.validate_baseline().map_err(UiInputStoreError::schema)?; schema.validate().map_err(UiInputStoreError::schema)?; let values = schema.slots.iter().map(|slot| (slot.key.clone(), UiResolvedInputValue { value: slot.default_value.clone(), source: UiInputValueSource::Default, last_update_revision: Revision(0) })).collect::<BTreeMap<_, _>>(); Ok(Self { schema, resolved_inputs: UiResolvedInputs { program_revision, input_revision: Revision(0), values, changed_slots: Vec::new() }, dirty_slots: HashSet::new(), idempotent_results: HashMap::new() }) }
    /// Activates a text-registry-enabled program only when every default text
    /// handle resolves. This guarantees default-first rendering cannot select
    /// stale or unrelated text.
    pub fn activate_with_text_registry(program_revision: UiProgramRevision, schema: UiInputSchema, registry: &UiTextRegistry) -> Result<Self, UiInputStoreError> {
        for slot in &schema.slots {
            if let UiInputValue::TextHandle { value } = &slot.default_value {
                registry.validate_handle(*value).map_err(UiInputStoreError::text)?;
            }
        }
        Self::activate(program_revision, schema)
    }
    pub fn schema(&self) -> &UiInputSchema { &self.schema }
    pub fn snapshot(&self) -> UiResolvedInputs { self.resolved_inputs.clone() }
    pub fn dirty_slots(&self) -> Vec<String> { let mut slots = self.dirty_slots.iter().cloned().collect::<Vec<_>>(); slots.sort(); slots }
    pub fn take_dirty_slots(&mut self) -> Vec<String> { let slots = self.dirty_slots(); self.dirty_slots.clear(); slots }
    pub fn apply(&mut self, writer: UiInputWriter, frame: UiInputFrame) -> Result<UiInputApplyResult, UiInputStoreError> {
        if let Some(result) = self.idempotent_results.get(&frame.idempotency_key) { return Ok(result.clone()); }
        if frame.idempotency_key.trim().is_empty() || frame.request_id.trim().is_empty() { return Err(UiInputStoreError { code: "invalid_request", message: "request_id and idempotency_key are required" }); }
        if frame.program_revision != self.resolved_inputs.program_revision || frame.expected_input_revision != self.resolved_inputs.input_revision { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_STALE_INPUT_REVISION, message: "program or input revision is stale" }); }
        let mut seen = HashSet::new();
        for UiInputChange { key, value } in &frame.changes { if !seen.insert(key.as_str()) { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_DUPLICATE_INPUT_CHANGE, message: "input frame changes a slot more than once" }); } let Some(slot) = self.schema.slots.iter().find(|slot| slot.key == *key) else { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_UNKNOWN_INPUT_KEY, message: "input frame references an unknown slot" }); }; if !slot.kind.accepts(value) { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_INPUT_TYPE_MISMATCH, message: "input frame value does not match the declared slot kind" }); } if !Self::writer_is_allowed(writer, slot.update_class) { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_INPUT_UPDATE_FORBIDDEN, message: "writer is not authorized for this input slot" }); } }
        let next_revision = Revision(self.resolved_inputs.input_revision.0 + 1); let mut changed_slots = Vec::new(); let mut values = self.resolved_inputs.values.clone();
        for UiInputChange { key, value } in frame.changes { let slot = self.schema.slots.iter().find(|slot| slot.key == key).expect("validated slot exists"); let source = match slot.update_class { UiInputUpdateClass::ReliableExternal => UiInputValueSource::ReliableExternal, UiInputUpdateClass::LocalPresentation => UiInputValueSource::LocalPresentation, UiInputUpdateClass::TextRegistryReference => UiInputValueSource::TextRegistryReference, UiInputUpdateClass::StaticAtProgramActivation => unreachable!("static slots are not writable") }; if values.get(&key).is_none_or(|current| current.value != value) { changed_slots.push(key.clone()); self.dirty_slots.insert(key.clone()); } values.insert(key, UiResolvedInputValue { value, source, last_update_revision: next_revision }); }
        let snapshot = UiResolvedInputs { program_revision: self.resolved_inputs.program_revision.clone(), input_revision: next_revision, values, changed_slots: changed_slots.clone() }; self.resolved_inputs = snapshot.clone(); let result = UiInputApplyResult { input_revision: next_revision, changed_slots, snapshot }; self.idempotent_results.insert(frame.idempotency_key, result.clone()); Ok(result)
    }
    /// Applies a frame only after every text-handle value resolves in the supplied
    /// registry. This is the capability-enabled path; raw text never enters frames.
    pub fn apply_with_text_registry(&mut self, writer: UiInputWriter, frame: UiInputFrame, registry: &UiTextRegistry) -> Result<UiInputApplyResult, UiInputStoreError> {
        for change in &frame.changes {
            if let UiInputValue::TextHandle { value } = &change.value {
                registry.validate_handle(*value).map_err(UiInputStoreError::text)?;
            }
        }
        self.apply(writer, frame)
    }
    fn writer_is_allowed(writer: UiInputWriter, update_class: UiInputUpdateClass) -> bool { matches!((writer, update_class), (UiInputWriter::External, UiInputUpdateClass::ReliableExternal | UiInputUpdateClass::TextRegistryReference) | (UiInputWriter::LocalPresentation, UiInputUpdateClass::LocalPresentation)) }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UiTextRegistryError { pub code: &'static str, pub message: &'static str }

#[derive(Clone, Debug)]
struct UiTextRegistryEntry { record: UiTextRecord, reference_count: u32 }

/// CPU-owned bounded text registry. WGPU may mirror resident text, but only the
/// renderer creates glyph resources; this type holds no renderer state.
#[derive(Clone, Debug)]
pub struct UiTextRegistry {
    registry_id: String,
    revision: Revision,
    capacity: u32,
    max_bytes_per_record: u32,
    next_id: u64,
    entries: BTreeMap<u64, UiTextRegistryEntry>,
    released_generations: HashMap<u64, u32>,
    free_ids: Vec<u64>,
}

impl UiTextRegistry {
    pub fn new(registry_id: impl Into<String>, capacity: u32, max_bytes_per_record: u32) -> Result<Self, UiTextRegistryError> {
        let registry_id = registry_id.into();
        if registry_id.trim().is_empty() || capacity == 0 || max_bytes_per_record == 0 { return Err(UiTextRegistryError { code: "ui_program_invalid_text_registry", message: "registry id, capacity, and record byte limit must be nonzero" }); }
        Ok(Self { registry_id, revision: Revision(0), capacity, max_bytes_per_record, next_id: 1, entries: BTreeMap::new(), released_generations: HashMap::new(), free_ids: Vec::new() })
    }
    pub fn revision(&self) -> Revision { self.revision }
    pub fn snapshot(&self, include_text: bool) -> UiTextRegistrySnapshot {
        let records = self.entries.values().map(|entry| { let mut record = entry.record.clone(); if !include_text { record.text.clear(); } record }).collect();
        UiTextRegistrySnapshot { registry_id: self.registry_id.clone(), revision: self.revision, capacity: self.capacity, used: self.entries.len() as u32, records }
    }
    /// Returns handle metadata without textual content. WGPU residency remains
    /// false here because this CPU registry never owns glyph resources.
    pub fn debug_snapshot(&self) -> UiTextRegistryDebugSnapshot {
        UiTextRegistryDebugSnapshot {
            registry_id: self.registry_id.clone(),
            revision: self.revision,
            capacity: self.capacity,
            used: self.entries.len() as u32,
            records: self.entries.values().map(|entry| UiTextRegistryEntryMetadata {
                handle: entry.record.handle,
                category: entry.record.category,
                revision: entry.record.revision,
                byte_length: entry.record.byte_length,
                reference_count: entry.reference_count,
                resident: false,
            }).collect(),
        }
    }
    pub fn insert_dynamic(&mut self, expected_revision: Revision, text: String) -> Result<UiTextHandle, UiTextRegistryError> { self.insert(expected_revision, text, UiTextSourceCategory::Dynamic) }
    pub fn register_literal(&mut self, expected_revision: Revision, text: String) -> Result<UiTextHandle, UiTextRegistryError> {
        self.require_revision(expected_revision)?;
        self.validate_text(&text)?;
        if let Some(entry) = self.entries.values().find(|entry| entry.record.category == UiTextSourceCategory::Literal && entry.record.text == text) { return Ok(entry.record.handle); }
        self.insert(expected_revision, text, UiTextSourceCategory::Literal)
    }
    pub fn replace_dynamic(&mut self, expected_revision: Revision, handle: UiTextHandle, text: String) -> Result<(), UiTextRegistryError> {
        self.require_revision(expected_revision)?; self.validate_text(&text)?;
        if self.resolve(handle)?.category != UiTextSourceCategory::Dynamic { return Err(UiTextRegistryError { code: "ui_program_text_literal_immutable", message: "literal program text cannot be replaced" }); }
        self.revision = Revision(self.revision.0 + 1); let revision = self.revision;
        let entry = self.entries.get_mut(&handle.id).expect("validated text entry exists"); entry.record.text = text; entry.record.byte_length = entry.record.text.len() as u32; entry.record.revision = revision; Ok(())
    }
    pub fn retain(&mut self, expected_revision: Revision, handle: UiTextHandle) -> Result<(), UiTextRegistryError> { self.require_revision(expected_revision)?; self.validate_handle(handle)?; let entry = self.entries.get_mut(&handle.id).expect("validated text entry exists"); entry.reference_count = entry.reference_count.saturating_add(1); self.revision = Revision(self.revision.0 + 1); Ok(()) }
    pub fn release(&mut self, expected_revision: Revision, handle: UiTextHandle) -> Result<(), UiTextRegistryError> {
        self.require_revision(expected_revision)?;
        self.validate_handle(handle)?;
        let remove = { let entry = self.entries.get_mut(&handle.id).expect("validated text entry exists"); if entry.record.category == UiTextSourceCategory::Literal { return Err(UiTextRegistryError { code: "ui_program_text_literal_immutable", message: "literal program text is released with its program, not individually" }); } entry.reference_count = entry.reference_count.saturating_sub(1); entry.reference_count == 0 };
        if remove { self.entries.remove(&handle.id); self.released_generations.insert(handle.id, handle.generation); self.free_ids.push(handle.id); }
        self.revision = Revision(self.revision.0 + 1); Ok(())
    }
    pub fn resolve(&self, handle: UiTextHandle) -> Result<&UiTextRecord, UiTextRegistryError> { self.validate_handle(handle)?; Ok(&self.entries[&handle.id].record) }
    pub fn validate_handle(&self, handle: UiTextHandle) -> Result<(), UiTextRegistryError> {
        match self.entries.get(&handle.id) { Some(entry) if entry.record.handle.generation == handle.generation => Ok(()), Some(_) => Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_GENERATION_MISMATCH, message: "text handle generation does not match the active record" }), None if self.released_generations.contains_key(&handle.id) => Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_GENERATION_MISMATCH, message: "text handle refers to a released or reused record" }), None => Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_UNKNOWN_TEXT_HANDLE, message: "text handle is not present in this registry" }) }
    }
    pub fn diagnostic(&self, handle: UiTextHandle) -> UiTextHandleDiagnostic {
        match self.entries.get(&handle.id) { Some(entry) if entry.record.handle.generation == handle.generation => UiTextHandleDiagnostic { handle, status: UiTextHandleStatus::Ready, reference_count: entry.reference_count, resident: false, message: "text record is available; renderer residency is reported by WGPU".into() }, Some(_) => UiTextHandleDiagnostic { handle, status: UiTextHandleStatus::GenerationMismatch, reference_count: 0, resident: false, message: "text handle generation does not match the active record".into() }, None if self.released_generations.contains_key(&handle.id) => UiTextHandleDiagnostic { handle, status: UiTextHandleStatus::Released, reference_count: 0, resident: false, message: "text record was released".into() }, None => UiTextHandleDiagnostic { handle, status: UiTextHandleStatus::Missing, reference_count: 0, resident: false, message: "text record is absent".into() } }
    }
    fn insert(&mut self, expected_revision: Revision, text: String, category: UiTextSourceCategory) -> Result<UiTextHandle, UiTextRegistryError> {
        self.require_revision(expected_revision)?; self.validate_text(&text)?;
        if self.entries.len() >= self.capacity as usize { return Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_CAPACITY_OVERFLOW, message: "text registry capacity is exhausted" }); }
        let id = self.free_ids.pop().unwrap_or_else(|| { let id = self.next_id; self.next_id += 1; id }); let generation = self.released_generations.get(&id).copied().unwrap_or(0).saturating_add(1); let handle = UiTextHandle { id, generation };
        self.revision = Revision(self.revision.0 + 1); self.entries.insert(id, UiTextRegistryEntry { record: UiTextRecord { handle, byte_length: text.len() as u32, text, category, revision: self.revision }, reference_count: 1 }); Ok(handle)
    }
    fn require_revision(&self, expected: Revision) -> Result<(), UiTextRegistryError> { if expected == self.revision { Ok(()) } else { Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_STALE_REVISION, message: "text registry revision is stale" }) } }
    fn validate_text(&self, text: &str) -> Result<(), UiTextRegistryError> { if text.len() > self.max_bytes_per_record as usize { Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_TOO_LONG, message: "text exceeds the registry record byte limit" }) } else { Ok(()) } }
}

impl UiInputStoreError { fn text(error: UiTextRegistryError) -> Self { Self { code: error.code, message: error.message } } }

pub struct UiRuntime {
    epoch: u64,
    client: ClientIdentity,
    cached_fragment: Option<UiFragment>,
    journal: CommandJournal,
    receipts: HashMap<RequestId, CommandReceipt>,
    last_input_sequence: HashMap<u64, u64>,
    idempotent_responses: HashMap<String, RpcResponse>,
    surface: UiSurfaceMachine,
    ai_terrain: AiTerrainPanelState,
    showcase_text: String,
}

impl UiRuntime {
    pub fn new(epoch: u64, instance_id: impl Into<String>) -> Self {
        Self {
            epoch,
            client: ClientIdentity {
                kind: ClientKind::UiRuntime,
                instance_id: instance_id.into(),
                pid: std::process::id(),
                origin: "neon-ui-runtime".into(),
            },
            cached_fragment: None,
            journal: CommandJournal::new(ServiceName(SERVICE_NAME.into()), epoch, 128),
            receipts: HashMap::new(),
            last_input_sequence: HashMap::new(),
            idempotent_responses: HashMap::new(),
            surface: UiSurfaceMachine::new(UiSurfaceId(WORKBENCH_SURFACE_ID.into())),
            ai_terrain: AiTerrainPanelState::default(),
            showcase_text: String::new(),
        }
    }

    pub fn service_health(&self) -> ServiceHealth {
        ServiceHealth {
            service: ServiceName(SERVICE_NAME.into()),
            status: HealthStatus::Healthy,
            epoch: self.epoch,
        }
    }

    pub fn service_description(&self) -> ServiceDescription {
        ServiceDescription {
            service: ServiceName(SERVICE_NAME.into()),
            protocol_version: PROTOCOL_VERSION,
            endpoint: "headless://ui-runtime".into(),
            epoch: self.epoch,
            capabilities: vec![
                "ui.static_fragment.submit.v1".into(),
                "ui.fragment.submit.v1".into(),
                "ui.semantic_input.v1".into(),
                "ui.intent_dispatch.v1".into(),
                "ui.surface.machine.v1".into(),
                "ui.ai.terrain.panel.v1".into(),
                "ui.text_input.commit.v1".into(),
                "ui.program.input.v1".into(),
            ],
        }
    }

    pub fn debug_snapshot(&self) -> DebugSnapshot {
        DebugSnapshot {
            service: ServiceName(SERVICE_NAME.into()),
            epoch: self.epoch,
            revision: self
                .cached_fragment
                .as_ref()
                .map_or(Revision(0), |fragment| fragment.revision),
            health: HealthStatus::Healthy,
            capabilities: self.service_description().capabilities,
            active_jobs: Vec::new(),
        }
    }

    pub fn handle_service_request(&mut self, request: RpcRequest) -> RpcResponse {
        let result = match request.method.as_str() {
            "service.health" => Some(json!(self.service_health())),
            "service.describe" => Some(json!(self.service_description())),
            "service.shutdown" => Some(json!({"state": "accepted"})),
            "debug.snapshot.get" => Some(json!(self.debug_snapshot())),
            "debug.command.get" => return self.handle_debug_command(request),
            "debug.trace.query" => return self.handle_debug_trace(request),
            "ui.fragment.submit" => return self.handle_fragment_submit(request),
            "ui.surface.snapshot.get" => Some(self.surface_value()),
            "ui.ai.terrain.snapshot.get" => Some(self.ai_terrain.snapshot()),
            "ui.surface.event" => return self.handle_surface_event(request),
            "ui.input.event" => return self.handle_input_event(request),
            "ui.intent.dispatch" => return self.handle_intent_dispatch(request),
            _ => None,
        };
        match result {
            Some(result) => RpcResponse {
                request_id: request.request_id,
                status: RpcStatus::Accepted,
                revision: Some(
                    self.cached_fragment
                        .as_ref()
                        .map_or(Revision(0), |fragment| fragment.revision),
                ),
                result: Some(result),
                snapshot: None,
                error: None,
            },
            None => RpcResponse {
                request_id: request.request_id,
                status: RpcStatus::Rejected,
                revision: None,
                result: None,
                snapshot: None,
                error: Some(neon_protocol::RpcError {
                    code: "unsupported_method".into(),
                    message: "method is not supported".into(),
                    current_revision: None,
                    object_id: None,
                }),
            },
        }
    }

    fn handle_surface_event(&mut self, request: RpcRequest) -> RpcResponse {
        let Some(key) = request.idempotency_key.clone() else { return self.rejected(request.request_id, "invalid_request", "idempotency_key is required"); };
        if let Some(response) = self.idempotent_responses.get(&key) { let mut response = response.clone(); response.request_id = request.request_id; return response; }
        if request.expected_revision != Some(self.surface.revision) { return self.rejected(request.request_id, "revision_conflict", "UI surface revision is stale"); }
        let event = match self.parse_surface_event(&request.params) { Ok(event) => event, Err((code, message)) => return self.rejected(request.request_id, code, message) };
        let transition = match self.surface.transition(event) { Ok(transition) => transition, Err((code, message)) => return self.rejected(request.request_id, code, message) };
        self.record_receipt(&request.request_id, CommandState::Accepted, None);
        let response = RpcResponse { request_id: request.request_id, status: RpcStatus::Accepted, revision: Some(transition.snapshot.revision), result: Some(json!(transition.snapshot)), snapshot: None, error: None };
        self.idempotent_responses.insert(key, response.clone());
        response
    }

    fn parse_surface_event(&self, params: &Value) -> Result<UiSurfaceEvent, (&'static str, &'static str)> {
        let request = serde_json::from_value::<UiSurfaceEventRequest>(params.clone())
            .map_err(|_| ("invalid_request", "a supported UI surface event is required"))?;
        if request.schema_version != UI_SURFACE_SCHEMA_VERSION { return Err(("unsupported_ui_surface_schema", "UI surface schema version is not supported")); }
        if request.surface_id != self.surface.surface_id { return Err(("surface_not_found", "UI surface is not available")); }
        Ok(request.event)
    }

    fn surface_value(&self) -> Value {
        json!(self.surface.snapshot())
    }

    fn handle_debug_command(&mut self, request: RpcRequest) -> RpcResponse {
        let Some(request_id) = request.params.get("request_id").and_then(Value::as_str) else {
            return self.rejected(request.request_id, "invalid_request", "request_id is required");
        };
        match self.command_receipt(&RequestId(request_id.into())).cloned() {
            Some(receipt) => self.accepted(request.request_id, json!(receipt)),
            None => self.rejected(request.request_id, "not_found", "command receipt was not found"),
        }
    }

    fn handle_debug_trace(&mut self, request: RpcRequest) -> RpcResponse {
        let filter = JournalFilter {
            request_id: request
                .params
                .get("request_id")
                .and_then(Value::as_str)
                .map(|value| RequestId(value.into())),
            event_id: request.params.get("event_id").and_then(Value::as_str).map(str::to_owned),
            ..JournalFilter::default()
        };
        self.accepted(request.request_id, json!(self.traces(&filter)))
    }

    fn apply_ai_terrain_intent(
        &mut self,
        action: &str,
        params: &Value,
    ) -> Result<Option<Value>, (&'static str, &'static str)> {
        match action {
            "ai.terrain.condition.set" => {
                let dimension = params.get("dimension").and_then(Value::as_str).ok_or(("invalid_request", "condition dimension is required"))?;
                let index = params.get("index").and_then(Value::as_u64).and_then(|value| u32::try_from(value).ok()).ok_or(("invalid_request", "condition index is required"))?;
                let slot = match dimension {
                    "sub" if index < 23 => &mut self.ai_terrain.condition.sub,
                    "parent" if index < 8 => &mut self.ai_terrain.condition.parent,
                    "relief" if index < 5 => &mut self.ai_terrain.condition.relief,
                    "texture" if index < 4 => &mut self.ai_terrain.condition.texture,
                    "water" if index < 3 => &mut self.ai_terrain.condition.water,
                    _ => return Err(("invalid_request", "condition index is out of range")),
                };
                *slot = Some(index);
            }
            "ai.terrain.condition.reset" => self.ai_terrain.condition = AiTerrainCondition::default(),
            "ai.terrain.settings.set" => {
                if let Some(steps) = params.get("steps").and_then(Value::as_u64).and_then(|value| u32::try_from(value).ok()) {
                    if !(1..=200).contains(&steps) { return Err(("invalid_request", "steps must be in 1..=200")); }
                    self.ai_terrain.steps = steps;
                }
                if let Some(guidance) = params.get("guidance").and_then(Value::as_f64) {
                    if !(0.0..=16.0).contains(&guidance) { return Err(("invalid_request", "guidance must be in 0..=16")); }
                    self.ai_terrain.guidance = guidance as f32;
                }
            }
            "ai.terrain.seed.next" => self.ai_terrain.seed = self.ai_terrain.seed.wrapping_add(1),
            _ => return Ok(None),
        }
        self.ai_terrain.state = "idle".into();
        self.ai_terrain.job_id = None;
        self.ai_terrain.elapsed_ms = None;
        self.ai_terrain.error_code = None;
        self.ai_terrain.advance();
        Ok(Some(self.ai_terrain.snapshot()))
    }

    /// Runs the UI declaration control plane. A React client can only submit to this
    /// service; the service forwards a validated declaration to the sole renderer.
    pub fn serve_forwarder(
        endpoint: SocketAddr,
        wgpu_endpoint: SocketAddr,
        epoch: u64,
    ) -> Result<(), TransportError> {
        let server = RpcServer::bind(endpoint)?;
        let mut runtime = Self::new(epoch, "ui-runtime-forwarder");
        server.serve_until(|request| {
            let shutdown = request.method == "service.shutdown";
            let request_id = request.request_id.clone();
            let response = if request.method == "ui.fragment.submit" {
                runtime.forward_fragment(wgpu_endpoint, request).unwrap_or_else(|error| {
                    runtime.rejected(request_id, "service_unavailable", &error.to_string())
                })
            } else if request.method == "ui.input.event" && renderer_event_targets_wgpu(&request) {
                runtime.forward_wgpu_event(wgpu_endpoint, request).unwrap_or_else(|error| {
                    runtime.rejected(request_id, "service_unavailable", &error.to_string())
                })
            } else {
                runtime.handle_service_request(request)
            };
            (response, !shutdown)
        })
    }

