#[derive(Clone, Debug, PartialEq, Eq)] pub struct UiInputStoreError { pub code: &'static str, pub message: &'static str }
impl UiInputStoreError { fn schema(error: UiSchemaError) -> Self { match error { UiSchemaError::DuplicateInputKey => Self { code: "ui_program_duplicate_input_key", message: "input schema contains a duplicate slot key" }, UiSchemaError::InvalidInputDefault => Self { code: "ui_program_invalid_default", message: "input slot default does not match its declared kind" }, _ => Self { code: "ui_program_invalid_input_schema", message: "input schema is invalid" } } } }
/// CPU-only transactional input state. Defaults are installed at activation;
/// WGPU is deliberately absent from this supported headless API.
#[derive(Clone, Debug)] pub struct UiInputStore { schema: UiInputSchema, resolved_inputs: UiResolvedInputs, dirty_slots: HashSet<String>, idempotent_results: HashMap<String, UiInputApplyResult> }
impl UiInputStore {
    pub fn activate(program_revision: UiProgramRevision, schema: UiInputSchema) -> Result<Self, UiInputStoreError> { program_revision.validate_baseline().map_err(UiInputStoreError::schema)?; schema.validate().map_err(UiInputStoreError::schema)?; let values = schema.slots.iter().map(|slot| (slot.key.clone(), UiResolvedInputValue { value: slot.default_value.clone(), source: UiInputValueSource::Default, last_update_revision: Revision(0) })).collect::<BTreeMap<_, _>>(); Ok(Self { schema, resolved_inputs: UiResolvedInputs { program_revision, input_revision: Revision(0), values, changed_slots: Vec::new() }, dirty_slots: HashSet::new(), idempotent_results: HashMap::new() }) }
    /// Activates a text-registry-enabled program only when every default text
    /// handle resolves. This guarantees default-first rendering cannot select
    /// stale or unrelated text.
    pub fn activate_with_text_registry(program_revision: UiProgramRevision, schema: UiInputSchema, registry: &UiTextRegistry) -> Result<Self, UiInputStoreError> {
        for slot in &schema.slots {
            if let UiInputValue::TextHandle { value } = &slot.default_value {
                registry.validate_handle(*value).map_err(UiInputStoreError::text)?;
            }
        }
        Self::activate(program_revision, schema)
    }
    pub fn schema(&self) -> &UiInputSchema { &self.schema }
    pub fn snapshot(&self) -> UiResolvedInputs { self.resolved_inputs.clone() }
    pub fn dirty_slots(&self) -> Vec<String> { let mut slots = self.dirty_slots.iter().cloned().collect::<Vec<_>>(); slots.sort(); slots }
    pub fn take_dirty_slots(&mut self) -> Vec<String> { let slots = self.dirty_slots(); self.dirty_slots.clear(); slots }
    pub fn apply(&mut self, writer: UiInputWriter, frame: UiInputFrame) -> Result<UiInputApplyResult, UiInputStoreError> {
        if let Some(result) = self.idempotent_results.get(&frame.idempotency_key) { return Ok(result.clone()); }
        if frame.idempotency_key.trim().is_empty() || frame.request_id.trim().is_empty() { return Err(UiInputStoreError { code: "invalid_request", message: "request_id and idempotency_key are required" }); }
        if frame.program_revision != self.resolved_inputs.program_revision || frame.expected_input_revision != self.resolved_inputs.input_revision { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_STALE_INPUT_REVISION, message: "program or input revision is stale" }); }
        let mut seen = HashSet::new();
        for UiInputChange { key, value } in &frame.changes { if !seen.insert(key.as_str()) { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_DUPLICATE_INPUT_CHANGE, message: "input frame changes a slot more than once" }); } let Some(slot) = self.schema.slots.iter().find(|slot| slot.key == *key) else { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_UNKNOWN_INPUT_KEY, message: "input frame references an unknown slot" }); }; if !slot.kind.accepts(value) { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_INPUT_TYPE_MISMATCH, message: "input frame value does not match the declared slot kind" }); } if !Self::writer_is_allowed(writer, slot.update_class) { return Err(UiInputStoreError { code: ERROR_UI_PROGRAM_INPUT_UPDATE_FORBIDDEN, message: "writer is not authorized for this input slot" }); } }
        let next_revision = Revision(self.resolved_inputs.input_revision.0 + 1); let mut changed_slots = Vec::new(); let mut values = self.resolved_inputs.values.clone();
        for UiInputChange { key, value } in frame.changes { let slot = self.schema.slots.iter().find(|slot| slot.key == key).expect("validated slot exists"); let source = match slot.update_class { UiInputUpdateClass::ReliableExternal => UiInputValueSource::ReliableExternal, UiInputUpdateClass::LocalPresentation => UiInputValueSource::LocalPresentation, UiInputUpdateClass::TextRegistryReference => UiInputValueSource::TextRegistryReference, UiInputUpdateClass::StaticAtProgramActivation => unreachable!("static slots are not writable") }; if values.get(&key).is_none_or(|current| current.value != value) { changed_slots.push(key.clone()); self.dirty_slots.insert(key.clone()); } values.insert(key, UiResolvedInputValue { value, source, last_update_revision: next_revision }); }
        let snapshot = UiResolvedInputs { program_revision: self.resolved_inputs.program_revision.clone(), input_revision: next_revision, values, changed_slots: changed_slots.clone() }; self.resolved_inputs = snapshot.clone(); let result = UiInputApplyResult { input_revision: next_revision, changed_slots, snapshot }; self.idempotent_results.insert(frame.idempotency_key, result.clone()); Ok(result)
    }
    /// Applies a frame only after every text-handle value resolves in the supplied
    /// registry. This is the capability-enabled path; raw text never enters frames.
    pub fn apply_with_text_registry(&mut self, writer: UiInputWriter, frame: UiInputFrame, registry: &UiTextRegistry) -> Result<UiInputApplyResult, UiInputStoreError> {
        for change in &frame.changes {
            if let UiInputValue::TextHandle { value } = &change.value {
                registry.validate_handle(*value).map_err(UiInputStoreError::text)?;
            }
        }
        self.apply(writer, frame)
    }
    fn writer_is_allowed(writer: UiInputWriter, update_class: UiInputUpdateClass) -> bool { matches!((writer, update_class), (UiInputWriter::External, UiInputUpdateClass::ReliableExternal | UiInputUpdateClass::TextRegistryReference) | (UiInputWriter::LocalPresentation, UiInputUpdateClass::LocalPresentation)) }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UiTextRegistryError { pub code: &'static str, pub message: &'static str }

#[derive(Clone, Debug)]
struct UiTextRegistryEntry { record: UiTextRecord, reference_count: u32 }

/// CPU-owned bounded text registry. WGPU may mirror resident text, but only the
/// renderer creates glyph resources; this type holds no renderer state.
#[derive(Clone, Debug)]
pub struct UiTextRegistry {
    registry_id: String,
    revision: Revision,
    capacity: u32,
    max_bytes_per_record: u32,
    next_id: u64,
    entries: BTreeMap<u64, UiTextRegistryEntry>,
    released_generations: HashMap<u64, u32>,
    free_ids: Vec<u64>,
}

impl UiTextRegistry {
    pub fn new(registry_id: impl Into<String>, capacity: u32, max_bytes_per_record: u32) -> Result<Self, UiTextRegistryError> {
        let registry_id = registry_id.into();
        if registry_id.trim().is_empty() || capacity == 0 || max_bytes_per_record == 0 { return Err(UiTextRegistryError { code: "ui_program_invalid_text_registry", message: "registry id, capacity, and record byte limit must be nonzero" }); }
        Ok(Self { registry_id, revision: Revision(0), capacity, max_bytes_per_record, next_id: 1, entries: BTreeMap::new(), released_generations: HashMap::new(), free_ids: Vec::new() })
    }
    pub fn revision(&self) -> Revision { self.revision }
    pub fn snapshot(&self, include_text: bool) -> UiTextRegistrySnapshot {
        let records = self.entries.values().map(|entry| { let mut record = entry.record.clone(); if !include_text { record.text.clear(); } record }).collect();
        UiTextRegistrySnapshot { registry_id: self.registry_id.clone(), revision: self.revision, capacity: self.capacity, used: self.entries.len() as u32, records }
    }
    /// Returns handle metadata without textual content. WGPU residency remains
    /// false here because this CPU registry never owns glyph resources.
    pub fn debug_snapshot(&self) -> UiTextRegistryDebugSnapshot {
        UiTextRegistryDebugSnapshot {
            registry_id: self.registry_id.clone(),
            revision: self.revision,
            capacity: self.capacity,
            used: self.entries.len() as u32,
            records: self.entries.values().map(|entry| UiTextRegistryEntryMetadata {
                handle: entry.record.handle,
                category: entry.record.category,
                revision: entry.record.revision,
                byte_length: entry.record.byte_length,
                reference_count: entry.reference_count,
                resident: false,
            }).collect(),
        }
    }
    pub fn insert_dynamic(&mut self, expected_revision: Revision, text: String) -> Result<UiTextHandle, UiTextRegistryError> { self.insert(expected_revision, text, UiTextSourceCategory::Dynamic) }
    pub fn register_literal(&mut self, expected_revision: Revision, text: String) -> Result<UiTextHandle, UiTextRegistryError> {
        self.require_revision(expected_revision)?;
        self.validate_text(&text)?;
        if let Some(entry) = self.entries.values().find(|entry| entry.record.category == UiTextSourceCategory::Literal && entry.record.text == text) { return Ok(entry.record.handle); }
        self.insert(expected_revision, text, UiTextSourceCategory::Literal)
    }
    pub fn replace_dynamic(&mut self, expected_revision: Revision, handle: UiTextHandle, text: String) -> Result<(), UiTextRegistryError> {
        self.require_revision(expected_revision)?; self.validate_text(&text)?;
        if self.resolve(handle)?.category != UiTextSourceCategory::Dynamic { return Err(UiTextRegistryError { code: "ui_program_text_literal_immutable", message: "literal program text cannot be replaced" }); }
        self.revision = Revision(self.revision.0 + 1); let revision = self.revision;
        let entry = self.entries.get_mut(&handle.id).expect("validated text entry exists"); entry.record.text = text; entry.record.byte_length = entry.record.text.len() as u32; entry.record.revision = revision; Ok(())
    }
    pub fn retain(&mut self, expected_revision: Revision, handle: UiTextHandle) -> Result<(), UiTextRegistryError> { self.require_revision(expected_revision)?; self.validate_handle(handle)?; let entry = self.entries.get_mut(&handle.id).expect("validated text entry exists"); entry.reference_count = entry.reference_count.saturating_add(1); self.revision = Revision(self.revision.0 + 1); Ok(()) }
    pub fn release(&mut self, expected_revision: Revision, handle: UiTextHandle) -> Result<(), UiTextRegistryError> {
        self.require_revision(expected_revision)?;
        self.validate_handle(handle)?;
        let remove = { let entry = self.entries.get_mut(&handle.id).expect("validated text entry exists"); if entry.record.category == UiTextSourceCategory::Literal { return Err(UiTextRegistryError { code: "ui_program_text_literal_immutable", message: "literal program text is released with its program, not individually" }); } entry.reference_count = entry.reference_count.saturating_sub(1); entry.reference_count == 0 };
        if remove { self.entries.remove(&handle.id); self.released_generations.insert(handle.id, handle.generation); self.free_ids.push(handle.id); }
        self.revision = Revision(self.revision.0 + 1); Ok(())
    }
    pub fn resolve(&self, handle: UiTextHandle) -> Result<&UiTextRecord, UiTextRegistryError> { self.validate_handle(handle)?; Ok(&self.entries[&handle.id].record) }
    pub fn validate_handle(&self, handle: UiTextHandle) -> Result<(), UiTextRegistryError> {
        match self.entries.get(&handle.id) { Some(entry) if entry.record.handle.generation == handle.generation => Ok(()), Some(_) => Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_GENERATION_MISMATCH, message: "text handle generation does not match the active record" }), None if self.released_generations.contains_key(&handle.id) => Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_GENERATION_MISMATCH, message: "text handle refers to a released or reused record" }), None => Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_UNKNOWN_TEXT_HANDLE, message: "text handle is not present in this registry" }) }
    }
    pub fn diagnostic(&self, handle: UiTextHandle) -> UiTextHandleDiagnostic {
        match self.entries.get(&handle.id) { Some(entry) if entry.record.handle.generation == handle.generation => UiTextHandleDiagnostic { handle, status: UiTextHandleStatus::Ready, reference_count: entry.reference_count, resident: false, message: "text record is available; renderer residency is reported by WGPU".into() }, Some(_) => UiTextHandleDiagnostic { handle, status: UiTextHandleStatus::GenerationMismatch, reference_count: 0, resident: false, message: "text handle generation does not match the active record".into() }, None if self.released_generations.contains_key(&handle.id) => UiTextHandleDiagnostic { handle, status: UiTextHandleStatus::Released, reference_count: 0, resident: false, message: "text record was released".into() }, None => UiTextHandleDiagnostic { handle, status: UiTextHandleStatus::Missing, reference_count: 0, resident: false, message: "text record is absent".into() } }
    }
    fn insert(&mut self, expected_revision: Revision, text: String, category: UiTextSourceCategory) -> Result<UiTextHandle, UiTextRegistryError> {
        self.require_revision(expected_revision)?; self.validate_text(&text)?;
        if self.entries.len() >= self.capacity as usize { return Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_CAPACITY_OVERFLOW, message: "text registry capacity is exhausted" }); }
        let id = self.free_ids.pop().unwrap_or_else(|| { let id = self.next_id; self.next_id += 1; id }); let generation = self.released_generations.get(&id).copied().unwrap_or(0).saturating_add(1); let handle = UiTextHandle { id, generation };
        self.revision = Revision(self.revision.0 + 1); self.entries.insert(id, UiTextRegistryEntry { record: UiTextRecord { handle, byte_length: text.len() as u32, text, category, revision: self.revision }, reference_count: 1 }); Ok(handle)
    }
    fn require_revision(&self, expected: Revision) -> Result<(), UiTextRegistryError> { if expected == self.revision { Ok(()) } else { Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_REGISTRY_STALE_REVISION, message: "text registry revision is stale" }) } }
    fn validate_text(&self, text: &str) -> Result<(), UiTextRegistryError> { if text.len() > self.max_bytes_per_record as usize { Err(UiTextRegistryError { code: ERROR_UI_PROGRAM_TEXT_TOO_LONG, message: "text exceeds the registry record byte limit" }) } else { Ok(()) } }
}

impl UiInputStoreError { fn text(error: UiTextRegistryError) -> Self { Self { code: error.code, message: error.message } } }

/// A renderer-free compiler error. The code is stable for RPC/debug adapters;
/// the message provides author-facing context without exposing renderer state.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UiProgramCompileError { pub code: &'static str, pub message: String }

/// Renderer-local presentation values are deliberately distinct from resolved
/// domain inputs. This first CPU backend has no local overrides yet, but the
/// type makes the ownership boundary explicit for future WGPU parity work.
#[derive(Clone, Debug, PartialEq)]
pub struct UiLocalPresentationState { pub revision: Revision }

/// Pure deterministic lowering from canonical IR plus a validated input schema.
/// It performs no I/O, text-registry mutation, GPU allocation, or domain lookup.
pub fn compile_ui_program(document: &UiIrDocument, revision: UiProgramRevision, schema: &UiInputSchema) -> Result<UiProgram, UiProgramCompileError> {
    revision.validate_baseline().map_err(schema_compile_error)?;
    schema.validate().map_err(schema_compile_error)?;
    document.validate().map_err(schema_compile_error)?;
    let mut templates = Vec::new(); let mut nodes = Vec::new(); let mut layouts = Vec::new(); let mut node_keys = HashSet::new();
    collect_program_nodes(&document.root, None, &mut templates, &mut nodes, &mut layouts, &mut node_keys)?;
    if nodes.len() as u32 > document.resource_budget.max_nodes || nodes.len() as u32 > document.resource_budget.max_instances { return Err(compile_error("ui_program_capacity_overflow", "node count exceeds the declared program budget")); }
    if document.bindings.len() as u32 > document.resource_budget.max_bindings || document.events.len() as u32 > document.resource_budget.max_events { return Err(compile_error("ui_program_capacity_overflow", "binding or event count exceeds the declared program budget")); }
    let clip_count = templates.iter().filter(|node| node.layout.as_ref().is_some_and(|layout| layout.clip)).count() as u32;
    if clip_count > document.resource_budget.max_clips { return Err(compile_error("ui_program_capacity_overflow", "clip count exceeds the declared program budget")); }
    let literal_texts = compile_literal_texts(&templates)?;
    let glyph_count = literal_texts.iter().map(|entry| entry.text.chars().count() as u32).sum::<u32>();
    if literal_texts.len() as u32 > document.resource_budget.max_text_records || glyph_count > document.resource_budget.max_glyph_instances { return Err(compile_error("ui_program_capacity_overflow", "literal text or glyph count exceeds the declared program budget")); }
    for node in &templates {
        if matches!(node.kind, UiNodeKind::Image | UiNodeKind::RenderSurface) {
            let kind = if node.kind == UiNodeKind::Image { UiProgramResourceKind::Image } else { UiProgramResourceKind::RenderSurface };
            if !document.resources.iter().any(|resource| resource.key == node.node_id.0 && (resource.kind == kind || resource.has_fallback)) { return Err(compile_error("ui_program_missing_resource", "node resource is not declared and has no fallback")); }
        }
    }
    let mut bindings = Vec::new(); let mut input_to_bindings = BTreeMap::new(); let mut node_to_dependents = BTreeMap::new();
    for (index, declaration) in document.bindings.iter().enumerate() {
        if declaration.node_key.trim().is_empty() || declaration.input_key.trim().is_empty() || !node_keys.contains(&declaration.node_key) { return Err(compile_error("ui_program_unknown_binding_target", "binding references an unknown semantic node key")); }
        let Some(slot) = schema.slots.iter().find(|slot| slot.key == declaration.input_key) else { return Err(compile_error("ui_program_unknown_input_key", "binding references an undeclared input slot")); };
        if !binding_accepts(&declaration.property, &slot.kind) { return Err(compile_error("ui_program_input_type_mismatch", "binding property is incompatible with the declared input kind")); }
        let id = index as u32; bindings.push(UiBinding { binding_id: id, input_key: declaration.input_key.clone(), node_key: declaration.node_key.clone(), property: declaration.property.clone(), expected_kind: slot.kind.clone(), default_resolved_value: slot.default_value.clone() });
        input_to_bindings.entry(declaration.input_key.clone()).or_insert_with(Vec::new).push(id);
        node_to_dependents.entry(declaration.node_key.clone()).or_insert_with(Vec::new).push(id);
    }
    for event in &document.events {
        if event.node_key.trim().is_empty() || event.intent.trim().is_empty() || !node_keys.contains(&event.node_key) || event.allowed_payload_keys.iter().any(|key| key.trim().is_empty()) { return Err(compile_error("ui_program_invalid_event", "event declaration must target a node and have a nonempty typed intent")); }
    }
    let node_to_source_span = nodes.iter().map(|node| (node.key.clone(), node.source_span.clone())).collect();
    let dependencies = UiDependencyIndex { input_to_bindings, node_to_source_span, node_to_dependents };
    let layout_hash = stable_program_hash(document, schema, &nodes, &bindings);
    Ok(UiProgram { revision, nodes, node_templates: templates, literal_texts, layout_records: layouts, binding_records: bindings, branch_records: Vec::new(), event_records: document.events.clone(), resource_budget: document.resource_budget.clone(), dependency_index: dependencies, layout_hash })
}

/// Supported CPU execution backend. It consumes the same program and resolved
/// input snapshot planned for the renderer backend and only emits logical data.
pub fn evaluate_ui_program(program: &UiProgram, inputs: &UiResolvedInputs, viewport: UiCpuViewport, _local: &UiLocalPresentationState) -> UiCpuFrameOutput {
    let mut diagnostics = Vec::new();
    if program.revision != inputs.program_revision { diagnostics.push(cpu_diagnostic("ui_program_stale_input_revision", "resolved inputs belong to another program revision", None, None, program.revision.revision)); }
    let mut states = BTreeMap::new();
    for template in &program.node_templates { let literal = program.literal_texts.iter().find(|entry| entry.node_key == template.node_id.0).map(|entry| entry.handle); states.insert(template.node_id.0.clone(), UiCpuNodeState { node_key: template.node_id.0.clone(), visible: template.visible, enabled: template.enabled, selected: false, active: false, text: literal, image: None, opacity: template.style.opacity, scroll_offset: template.layout.map_or([0.0; 2], |layout| layout.scroll_offset) }); }
    for binding in &program.binding_records {
        let Some(value) = inputs.values.get(&binding.input_key).map(|resolved| &resolved.value) else { diagnostics.push(cpu_diagnostic("ui_program_unknown_input_key", "resolved input is absent", Some(&binding.node_key), Some(&binding.input_key), program.revision.revision)); continue; };
        let state = states.get_mut(&binding.node_key).expect("compiled binding target exists");
        apply_binding(state, &binding.property, value, &mut diagnostics, program.revision.revision, &binding.node_key, &binding.input_key);
    }
    let mut clips = BTreeMap::new(); let mut primitives = Vec::new(); let mut semantic_targets = Vec::new();
    for record in &program.layout_records {
        let state = states.get(&record.node_key).expect("compiled state exists");
        let mut bounds = record.bounds; if record.node_key == program.nodes.first().map(|node| node.key.as_str()).unwrap_or("") { bounds.width = bounds.width.min(viewport.logical_bounds.width); bounds.height = bounds.height.min(viewport.logical_bounds.height); }
        if program.node_templates.iter().find(|node| node.node_id.0 == record.node_key).and_then(|node| node.layout).is_some_and(|layout| layout.clip) { clips.insert(record.node_key.clone(), bounds); }
        if state.visible { primitives.push(UiCpuRenderPrimitive { node_key: record.node_key.clone(), kind: program.nodes.iter().find(|node| node.key == record.node_key).expect("compiled node exists").kind.clone(), bounds, clip: clips.get(&record.node_key).copied() }); }
        let intents = program.event_records.iter().filter(|event| event.node_key == record.node_key).map(|event| event.intent.clone()).collect::<Vec<_>>();
        if !intents.is_empty() { semantic_targets.push(UiCpuSemanticTarget { node_key: record.node_key.clone(), intents, enabled: state.enabled, visible: state.visible }); }
    }
    UiCpuFrameOutput { program_revision: program.revision.clone(), input_revision: inputs.input_revision, nodes: states.into_values().collect(), logical_layout: program.layout_records.clone(), clips, render_primitives: primitives, semantic_targets, diagnostics }
}

fn collect_program_nodes(node: &UiNode, parent: Option<String>, templates: &mut Vec<UiNode>, nodes: &mut Vec<UiProgramNode>, layouts: &mut Vec<UiProgramLayoutRecord>, keys: &mut HashSet<String>) -> Result<(), UiProgramCompileError> {
    if node.node_id.0.trim().is_empty() || !keys.insert(node.node_id.0.clone()) { return Err(compile_error("ui_program_duplicate_node_key", "IR node keys must be unique across the document")); }
    nodes.push(UiProgramNode { key: node.node_id.0.clone(), parent_key: parent.clone(), kind: node.kind.clone(), source_span: None });
    templates.push(node.clone()); layouts.push(UiProgramLayoutRecord { node_key: node.node_id.0.clone(), bounds: node.bounds, layout: node.layout });
    for child in &node.children { collect_program_nodes(child, Some(node.node_id.0.clone()), templates, nodes, layouts, keys)?; }
    Ok(())
}
fn compile_literal_texts(templates: &[UiNode]) -> Result<Vec<UiProgramLiteralText>, UiProgramCompileError> { let mut handles = HashMap::new(); let mut entries = Vec::new(); for node in templates { if let Some(TextRef::Literal { value }) = &node.text { let id = stable_text_id(value); if let Some(existing) = handles.insert(id, value) { if existing != value { return Err(compile_error("ui_program_literal_text_collision", "literal text table hash collision requires an explicit registry entry")); } } entries.push(UiProgramLiteralText { node_key: node.node_id.0.clone(), handle: UiTextHandle { id, generation: 1 }, text: value.clone() }); } } Ok(entries) }
fn stable_text_id(value: &str) -> u64 { let mut hash: u64 = 0xcbf29ce484222325; for byte in value.bytes() { hash ^= u64::from(byte); hash = hash.wrapping_mul(0x100000001b3); } hash }
fn binding_accepts(property: &UiBoundProperty, kind: &neon_ui_schema::UiInputKind) -> bool { use neon_ui_schema::UiInputKind::*; match property { UiBoundProperty::TextValue => matches!(kind, TextHandle), UiBoundProperty::Visible | UiBoundProperty::Enabled | UiBoundProperty::Selected | UiBoundProperty::Active => matches!(kind, Bool), UiBoundProperty::NumericValue => matches!(kind, I32 | U32 | F32 | I32Range { .. } | U32Range { .. }), UiBoundProperty::ImageAsset => matches!(kind, AssetHandle), UiBoundProperty::Opacity => matches!(kind, F32), UiBoundProperty::StateToken => matches!(kind, Enum { .. }), UiBoundProperty::ScrollOffset => matches!(kind, Vec2) } }
fn apply_binding(state: &mut UiCpuNodeState, property: &UiBoundProperty, value: &UiInputValue, diagnostics: &mut Vec<UiDiagnostic>, revision: Revision, node_key: &str, input_key: &str) { match (property, value) { (UiBoundProperty::TextValue, UiInputValue::TextHandle { value }) => state.text = Some(*value), (UiBoundProperty::Visible, UiInputValue::Bool { value }) => state.visible = *value, (UiBoundProperty::Enabled, UiInputValue::Bool { value }) => state.enabled = *value, (UiBoundProperty::Selected, UiInputValue::Bool { value }) => state.selected = *value, (UiBoundProperty::Active, UiInputValue::Bool { value }) => state.active = *value, (UiBoundProperty::ImageAsset, value @ UiInputValue::AssetHandle { .. }) => state.image = Some(value.clone()), (UiBoundProperty::Opacity, UiInputValue::F32 { value }) => state.opacity = value.clamp(0.0, 1.0), (UiBoundProperty::ScrollOffset, UiInputValue::Vec2 { value }) => state.scroll_offset = *value, (UiBoundProperty::NumericValue | UiBoundProperty::StateToken, _) => {}, _ => diagnostics.push(cpu_diagnostic("ui_program_input_type_mismatch", "resolved value does not match its compiled binding", Some(node_key), Some(input_key), revision)) } }
fn cpu_diagnostic(code: &'static str, message: &'static str, node_key: Option<&str>, input_key: Option<&str>, revision: Revision) -> UiDiagnostic { UiDiagnostic { code: code.into(), severity: UiDiagnosticSeverity::Error, message: message.into(), node_key: node_key.map(str::to_owned), input_key: input_key.map(str::to_owned), source_span: None, revision } }
fn compile_error(code: &'static str, message: impl Into<String>) -> UiProgramCompileError { UiProgramCompileError { code, message: message.into() } }
fn schema_compile_error(error: UiSchemaError) -> UiProgramCompileError { compile_error("ui_program_invalid_schema", format!("program schema validation failed: {error:?}")) }
fn stable_program_hash(document: &UiIrDocument, schema: &UiInputSchema, nodes: &[UiProgramNode], bindings: &[UiBinding]) -> String { let source = serde_json::to_vec(&(document, schema, nodes, bindings)).expect("program schema serializes"); let mut hash: u64 = 0xcbf29ce484222325; for byte in source { hash ^= u64::from(byte); hash = hash.wrapping_mul(0x100000001b3); } format!("fnv1a64-{hash:016x}") }

pub struct UiRuntime {
    epoch: u64,
    client: ClientIdentity,
    cached_fragment: Option<UiFragment>,
    journal: CommandJournal,
    receipts: HashMap<RequestId, CommandReceipt>,
    last_input_sequence: HashMap<u64, u64>,
    idempotent_responses: HashMap<String, RpcResponse>,
    surface: UiSurfaceMachine,
    ai_terrain: AiTerrainPanelState,
    showcase_text: String,
}

impl UiRuntime {
    pub fn new(epoch: u64, instance_id: impl Into<String>) -> Self {
        Self {
            epoch,
            client: ClientIdentity {
                kind: ClientKind::UiRuntime,
                instance_id: instance_id.into(),
                pid: std::process::id(),
                origin: "neon-ui-runtime".into(),
            },
            cached_fragment: None,
            journal: CommandJournal::new(ServiceName(SERVICE_NAME.into()), epoch, 128),
            receipts: HashMap::new(),
            last_input_sequence: HashMap::new(),
            idempotent_responses: HashMap::new(),
            surface: UiSurfaceMachine::new(UiSurfaceId(WORKBENCH_SURFACE_ID.into())),
            ai_terrain: AiTerrainPanelState::default(),
            showcase_text: String::new(),
        }
    }

    pub fn service_health(&self) -> ServiceHealth {
        ServiceHealth {
            service: ServiceName(SERVICE_NAME.into()),
            status: HealthStatus::Healthy,
            epoch: self.epoch,
        }
    }

    pub fn service_description(&self) -> ServiceDescription {
        ServiceDescription {
            service: ServiceName(SERVICE_NAME.into()),
            protocol_version: PROTOCOL_VERSION,
            endpoint: "headless://ui-runtime".into(),
            epoch: self.epoch,
            capabilities: vec![
                "ui.static_fragment.submit.v1".into(),
                "ui.fragment.submit.v1".into(),
                "ui.semantic_input.v1".into(),
                "ui.intent_dispatch.v1".into(),
                "ui.surface.machine.v1".into(),
                "ui.ai.terrain.panel.v1".into(),
                "ui.text_input.commit.v1".into(),
                "ui.program.input.v1".into(),
            ],
        }
    }

    pub fn debug_snapshot(&self) -> DebugSnapshot {
        DebugSnapshot {
            service: ServiceName(SERVICE_NAME.into()),
            epoch: self.epoch,
            revision: self
                .cached_fragment
                .as_ref()
                .map_or(Revision(0), |fragment| fragment.revision),
            health: HealthStatus::Healthy,
            capabilities: self.service_description().capabilities,
            active_jobs: Vec::new(),
        }
    }

    pub fn handle_service_request(&mut self, request: RpcRequest) -> RpcResponse {
        let result = match request.method.as_str() {
            "service.health" => Some(json!(self.service_health())),
            "service.describe" => Some(json!(self.service_description())),
            "service.shutdown" => Some(json!({"state": "accepted"})),
            "debug.snapshot.get" => Some(json!(self.debug_snapshot())),
            "debug.command.get" => return self.handle_debug_command(request),
            "debug.trace.query" => return self.handle_debug_trace(request),
            "ui.fragment.submit" => return self.handle_fragment_submit(request),
            "ui.surface.snapshot.get" => Some(self.surface_value()),
            "ui.ai.terrain.snapshot.get" => Some(self.ai_terrain.snapshot()),
            "ui.surface.event" => return self.handle_surface_event(request),
            "ui.input.event" => return self.handle_input_event(request),
            "ui.intent.dispatch" => return self.handle_intent_dispatch(request),
            _ => None,
        };
        match result {
            Some(result) => RpcResponse {
                request_id: request.request_id,
                status: RpcStatus::Accepted,
                revision: Some(
                    self.cached_fragment
                        .as_ref()
                        .map_or(Revision(0), |fragment| fragment.revision),
                ),
                result: Some(result),
                snapshot: None,
                error: None,
            },
            None => RpcResponse {
                request_id: request.request_id,
                status: RpcStatus::Rejected,
                revision: None,
                result: None,
                snapshot: None,
                error: Some(neon_protocol::RpcError {
                    code: "unsupported_method".into(),
                    message: "method is not supported".into(),
                    current_revision: None,
                    object_id: None,
                }),
            },
        }
    }

    fn handle_surface_event(&mut self, request: RpcRequest) -> RpcResponse {
        let Some(key) = request.idempotency_key.clone() else { return self.rejected(request.request_id, "invalid_request", "idempotency_key is required"); };
        if let Some(response) = self.idempotent_responses.get(&key) { let mut response = response.clone(); response.request_id = request.request_id; return response; }
        if request.expected_revision != Some(self.surface.revision) { return self.rejected(request.request_id, "revision_conflict", "UI surface revision is stale"); }
        let event = match self.parse_surface_event(&request.params) { Ok(event) => event, Err((code, message)) => return self.rejected(request.request_id, code, message) };
        let transition = match self.surface.transition(event) { Ok(transition) => transition, Err((code, message)) => return self.rejected(request.request_id, code, message) };
        self.record_receipt(&request.request_id, CommandState::Accepted, None);
        let response = RpcResponse { request_id: request.request_id, status: RpcStatus::Accepted, revision: Some(transition.snapshot.revision), result: Some(json!(transition.snapshot)), snapshot: None, error: None };
        self.idempotent_responses.insert(key, response.clone());
        response
    }

    fn parse_surface_event(&self, params: &Value) -> Result<UiSurfaceEvent, (&'static str, &'static str)> {
        let request = serde_json::from_value::<UiSurfaceEventRequest>(params.clone())
            .map_err(|_| ("invalid_request", "a supported UI surface event is required"))?;
        if request.schema_version != UI_SURFACE_SCHEMA_VERSION { return Err(("unsupported_ui_surface_schema", "UI surface schema version is not supported")); }
        if request.surface_id != self.surface.surface_id { return Err(("surface_not_found", "UI surface is not available")); }
        Ok(request.event)
    }

    fn surface_value(&self) -> Value {
        json!(self.surface.snapshot())
    }

    fn handle_debug_command(&mut self, request: RpcRequest) -> RpcResponse {
        let Some(request_id) = request.params.get("request_id").and_then(Value::as_str) else {
            return self.rejected(request.request_id, "invalid_request", "request_id is required");
        };
        match self.command_receipt(&RequestId(request_id.into())).cloned() {
            Some(receipt) => self.accepted(request.request_id, json!(receipt)),
            None => self.rejected(request.request_id, "not_found", "command receipt was not found"),
        }
    }

    fn handle_debug_trace(&mut self, request: RpcRequest) -> RpcResponse {
        let filter = JournalFilter {
            request_id: request
                .params
                .get("request_id")
                .and_then(Value::as_str)
                .map(|value| RequestId(value.into())),
            event_id: request.params.get("event_id").and_then(Value::as_str).map(str::to_owned),
            ..JournalFilter::default()
        };
        self.accepted(request.request_id, json!(self.traces(&filter)))
    }

    fn apply_ai_terrain_intent(
        &mut self,
        action: &str,
        params: &Value,
    ) -> Result<Option<Value>, (&'static str, &'static str)> {
        match action {
            "ai.terrain.condition.set" => {
                let dimension = params.get("dimension").and_then(Value::as_str).ok_or(("invalid_request", "condition dimension is required"))?;
                let index = params.get("index").and_then(Value::as_u64).and_then(|value| u32::try_from(value).ok()).ok_or(("invalid_request", "condition index is required"))?;
                let slot = match dimension {
                    "sub" if index < 23 => &mut self.ai_terrain.condition.sub,
                    "parent" if index < 8 => &mut self.ai_terrain.condition.parent,
                    "relief" if index < 5 => &mut self.ai_terrain.condition.relief,
                    "texture" if index < 4 => &mut self.ai_terrain.condition.texture,
                    "water" if index < 3 => &mut self.ai_terrain.condition.water,
                    _ => return Err(("invalid_request", "condition index is out of range")),
                };
                *slot = Some(index);
            }
            "ai.terrain.condition.reset" => self.ai_terrain.condition = AiTerrainCondition::default(),
            "ai.terrain.settings.set" => {
                if let Some(steps) = params.get("steps").and_then(Value::as_u64).and_then(|value| u32::try_from(value).ok()) {
                    if !(1..=200).contains(&steps) { return Err(("invalid_request", "steps must be in 1..=200")); }
                    self.ai_terrain.steps = steps;
                }
                if let Some(guidance) = params.get("guidance").and_then(Value::as_f64) {
                    if !(0.0..=16.0).contains(&guidance) { return Err(("invalid_request", "guidance must be in 0..=16")); }
                    self.ai_terrain.guidance = guidance as f32;
                }
            }
            "ai.terrain.seed.next" => self.ai_terrain.seed = self.ai_terrain.seed.wrapping_add(1),
            _ => return Ok(None),
        }
        self.ai_terrain.state = "idle".into();
        self.ai_terrain.job_id = None;
        self.ai_terrain.elapsed_ms = None;
        self.ai_terrain.error_code = None;
        self.ai_terrain.advance();
        Ok(Some(self.ai_terrain.snapshot()))
    }

    /// Runs the UI declaration control plane. A React client can only submit to this
    /// service; the service forwards a validated declaration to the sole renderer.
    pub fn serve_forwarder(
        endpoint: SocketAddr,
        wgpu_endpoint: SocketAddr,
        epoch: u64,
    ) -> Result<(), TransportError> {
        let server = RpcServer::bind(endpoint)?;
        let mut runtime = Self::new(epoch, "ui-runtime-forwarder");
        server.serve_until(|request| {
            let shutdown = request.method == "service.shutdown";
            let request_id = request.request_id.clone();
            let response = if request.method == "ui.fragment.submit" {
                runtime.forward_fragment(wgpu_endpoint, request).unwrap_or_else(|error| {
                    runtime.rejected(request_id, "service_unavailable", &error.to_string())
                })
            } else if request.method == "ui.input.event" && renderer_event_targets_wgpu(&request) {
                runtime.forward_wgpu_event(wgpu_endpoint, request).unwrap_or_else(|error| {
                    runtime.rejected(request_id, "service_unavailable", &error.to_string())
                })
            } else {
                runtime.handle_service_request(request)
            };
            (response, !shutdown)
        })
    }

    /// The cache is published only after the renderer accepted the exact declaration.
    pub fn forward_fragment(
        &mut self,
        wgpu_endpoint: SocketAddr,
        request: RpcRequest,
    ) -> Result<RpcResponse, TransportError> {
        let request_id = request.request_id.clone();
        let Some(idempotency_key) = request.idempotency_key.clone() else {
            return Ok(self.rejected(request_id, "invalid_request", "idempotency_key is required"));
        };
        if let Some(cached) = self.idempotent_responses.get(&idempotency_key) {
            let mut response = cached.clone();
            response.request_id = request_id;
            return Ok(response);
        }
        let fragment = match self.validate_fragment_submission(&request) {
            Ok(fragment) => fragment,
            Err((code, message)) => return Ok(self.rejected(request_id, code, message)),
        };
        self.record_receipt(&request.request_id, CommandState::Received, None);
        self.journal.append(TraceLevel::Info, EVENT_COMMAND_RECEIVED, Some(request.request_id.clone()), None, None, None, Some(self.debug_snapshot().revision), None, json!({"method": "ui.fragment.submit", "fragment_id": fragment.fragment_id.0, "fragment_revision": fragment.revision.0}));
        let forwarded = RpcRequest {
            protocol: "neon3.rpc".into(), version: PROTOCOL_VERSION, request_id: request.request_id.clone(),
            client: self.client.clone(), target: ServiceName("wgpu-runtime".into()), method: "wgpu.ui.submit_fragment".into(),
            params: request.params, expected_revision: None, idempotency_key: Some(idempotency_key.clone()),
        };
        let response = RpcClient::connect(wgpu_endpoint)?.call(&forwarded)?;
        if response.status == RpcStatus::Accepted {
            self.cached_fragment = Some(fragment);
            self.record_receipt(&request.request_id, CommandState::Accepted, None);
            self.journal.append(TraceLevel::Info, EVENT_COMMAND_ACCEPTED, Some(request.request_id.clone()), None, None, None, response.revision, response.revision, json!({"target": "wgpu-runtime", "state": "accepted"}));
            self.idempotent_responses.insert(idempotency_key, response.clone());
        } else {
            self.record_receipt(&request.request_id, CommandState::Rejected, response.error.as_ref().map(|error| error.code.clone()));
            self.journal.append(TraceLevel::Warn, EVENT_COMMAND_REJECTED, Some(request.request_id.clone()), None, None, None, Some(self.debug_snapshot().revision), response.revision, json!({"target": "wgpu-runtime", "state": "rejected", "code": response.error.as_ref().map(|error| error.code.clone())}));
        }
        Ok(response)
    }

    fn handle_fragment_submit(&mut self, request: RpcRequest) -> RpcResponse {
        let fragment = match self.validate_fragment_submission(&request) {
            Ok(fragment) => fragment,
            Err((code, message)) => return self.rejected(request.request_id, code, message),
        };
        let revision = fragment.revision;
        self.cached_fragment = Some(fragment);
        self.accepted(request.request_id, json!({"fragment_revision": revision, "state": "accepted"}))
    }

    fn validate_fragment_submission(&self, request: &RpcRequest) -> Result<UiFragment, (&'static str, &'static str)> {
        let command: UiCommand = serde_json::from_value(request.params.clone())
            .map_err(|_| ("invalid_request", "invalid UI command"))?;
        let UiCommand::SubmitFragment { submission } = command else {
            return Err(("invalid_request", "expected submit_fragment command"));
        };
        if submission.validate().is_err() {
            return Err(("invalid_request", "invalid UI fragment submission"));
        }
        if request.expected_revision.is_some_and(|expected| expected != self.debug_snapshot().revision) {
            return Err(("revision_conflict", "UI fragment revision is stale"));
        }
        if self.cached_fragment.as_ref().is_some_and(|current| submission.fragment.revision <= current.revision) {
            return Err(("revision_conflict", "UI fragment revision is stale"));
        }
        Ok(submission.fragment)
    }

    /// Forwards a renderer-resolved semantic event as a typed domain RPC.
    /// Render IDs and fragment-local node IDs are not accepted or emitted here.
    pub fn dispatch_semantic_event(
        &mut self,
        terrain_endpoint: SocketAddr,
        event: UiSemanticEvent,
        request_id: RequestId,
        idempotency_key: String,
    ) -> Result<RpcResponse, TransportError> {
        self.validate_semantic_event(&event)
            .map_err(|code| TransportError::Io(std::io::Error::other(code)))?;
        let neon_ui_schema::UiIntent::Invoke { action, params } = event.intent.clone();
        let request = RpcRequest {
            protocol: "neon3.rpc".into(), version: PROTOCOL_VERSION, request_id: request_id.clone(),
            client: self.client.clone(), target: ServiceName("terrain-runtime".into()), method: action,
            params, expected_revision: Some(event.fragment.revision), idempotency_key: Some(idempotency_key),
        };
        self.record_receipt(&request_id, CommandState::Received, None);
        self.journal.append(TraceLevel::Info, EVENT_COMMAND_RECEIVED, Some(request_id.clone()), None, None, None, Some(event.fragment.revision), None, json!({"event_id": event.event_id, "target": "terrain-runtime", "method": request.method}));
        let response = RpcClient::connect(terrain_endpoint)?.call(&request)?;
        let accepted = response.status == RpcStatus::Accepted;
        self.record_receipt(&request_id, if accepted { CommandState::Accepted } else { CommandState::Rejected }, response.error.as_ref().map(|error| error.code.clone()));
        self.journal.append(if accepted { TraceLevel::Info } else { TraceLevel::Warn }, if accepted { EVENT_COMMAND_ACCEPTED } else { EVENT_COMMAND_REJECTED }, Some(request_id), None, None, None, Some(event.fragment.revision), response.revision, json!({"event_id": event.event_id, "renderer_epoch": event.renderer_epoch, "fragment_id": event.fragment.id.0, "target": "terrain-runtime", "method": request.method}));
        Ok(response)
    }

    pub fn forward_wgpu_event(
        &mut self,
        wgpu_endpoint: SocketAddr,
        request: RpcRequest,
    ) -> Result<RpcResponse, TransportError> {
        let event: UiSemanticEvent = serde_json::from_value(request.params.clone())
            .map_err(|_| TransportError::Io(std::io::Error::other("invalid UI semantic event")))?;
        self.validate_semantic_event(&event)
            .map_err(|code| TransportError::Io(std::io::Error::other(code)))?;
        let neon_ui_schema::UiIntent::Invoke { action, params } = event.intent.clone();
        if action != "ai.terrain.generate" {
            return Err(TransportError::Io(std::io::Error::other(
                "intent is not a WGPU AI command",
            )));
        }
        let request_id = request.request_id.clone();
        let forwarded = RpcRequest {
            protocol: "neon3.rpc".into(),
            version: PROTOCOL_VERSION,
            request_id: request_id.clone(),
            client: self.client.clone(),
            target: ServiceName("wgpu-runtime".into()),
            method: "wgpu.ai.terrain.generate".into(),
            params,
            expected_revision: Some(event.fragment.revision),
            idempotency_key: request.idempotency_key,
        };
        self.record_receipt(&request_id, CommandState::Received, None);
        self.journal.append(
            TraceLevel::Info,
            EVENT_COMMAND_RECEIVED,
            Some(request_id.clone()),
            None,
            None,
            None,
            Some(event.fragment.revision),
            None,
            json!({"event_id": event.event_id, "target": "wgpu-runtime", "method": forwarded.method}),
        );
        self.ai_terrain.state = "generating".into();
        self.ai_terrain.job_id = None;
        self.ai_terrain.elapsed_ms = None;
        self.ai_terrain.error_code = None;
        self.ai_terrain.advance();
        let response = match RpcClient::connect(wgpu_endpoint).and_then(|mut client| client.call(&forwarded)) {
            Ok(response) => response,
            Err(error) => {
                self.ai_terrain.state = "failed".into();
                self.ai_terrain.error_code = Some("service_unavailable".into());
                self.ai_terrain.advance();
                return Err(error);
            }
        };
        let accepted = response.status == RpcStatus::Accepted;
        if accepted {
            self.ai_terrain.state = "ready".into();
            self.ai_terrain.job_id = response
                .result
                .as_ref()
                .and_then(|result| result.get("job_id"))
                .and_then(Value::as_str)
                .map(str::to_owned);
            let rendered_seed = response
                .result
                .as_ref()
                .and_then(|result| result.get("seed"))
                .and_then(Value::as_u64)
                .unwrap_or(self.ai_terrain.seed);
            self.ai_terrain.last_seed = Some(rendered_seed);
            self.ai_terrain.seed = rendered_seed.wrapping_add(1);
            self.ai_terrain.elapsed_ms = response
                .result
                .as_ref()
                .and_then(|result| result.get("elapsed_ms"))
                .and_then(Value::as_f64);
        } else {
            self.ai_terrain.state = "failed".into();
            self.ai_terrain.error_code = response.error.as_ref().map(|error| error.code.clone());
        }
        self.ai_terrain.advance();
        self.record_receipt(
            &request_id,
            if accepted { CommandState::Accepted } else { CommandState::Rejected },
            response.error.as_ref().map(|error| error.code.clone()),
        );
        self.journal.append(
            if accepted { TraceLevel::Info } else { TraceLevel::Warn },
            if accepted { EVENT_COMMAND_ACCEPTED } else { EVENT_COMMAND_REJECTED },
            Some(request_id),
            None,
            None,
            None,
            Some(event.fragment.revision),
            response.revision,
            json!({"event_id": event.event_id, "target": "wgpu-runtime", "method": forwarded.method}),
        );
        Ok(response)
    }

    pub fn command_receipt(&self, request_id: &RequestId) -> Option<&CommandReceipt> { self.receipts.get(request_id) }

    fn handle_input_event(&mut self, mut request: RpcRequest) -> RpcResponse {
        let event: UiSemanticEvent = match serde_json::from_value(request.params.clone()) {
            Ok(event) => event,
            Err(_) => return self.rejected(request.request_id, "invalid_request", "invalid UI semantic event"),
        };
        match self.validate_semantic_event(&event) {
            Ok(()) => {
                let neon_ui_schema::UiIntent::Invoke { action, params } = event.intent.clone();
                if event.event == neon_ui_schema::UiSemanticEventType::TextInputCommit {
                    let Some(text) = event.text else { return self.rejected(request.request_id, "invalid_text_commit", "a committed text value is required"); };
                    if action != "ui.showcase.text.commit" || text.value.chars().count() > 256 {
                        return self.rejected(request.request_id, "invalid_text_commit", "text commit is not accepted by this surface");
                    }
                    self.showcase_text = text.value;
                    return self.accepted(request.request_id, json!({"surface_id": "surface.ui-platform-showcase", "value": self.showcase_text}));
                }
                if action == "ui.surface.event" {
                    request.method = "ui.surface.event".into();
                    request.params = params;
                    request.expected_revision = Some(event.fragment.revision);
                    return self.handle_surface_event(request);
                }
                match self.apply_ai_terrain_intent(&action, &params) {
                    Ok(Some(snapshot)) => return self.accepted(request.request_id, snapshot),
                    Ok(None) => {}
                    Err((code, message)) => return self.rejected(request.request_id, code, message),
                }
                self.accepted(request.request_id, json!({"event_id": event.event_id, "intent": event.intent}))
            }
            Err(code) => self.rejected(request.request_id, code, "UI semantic event was rejected"),
        }
    }

    fn handle_intent_dispatch(&mut self, mut request: RpcRequest) -> RpcResponse {
        let intent: neon_ui_schema::UiIntent = match serde_json::from_value(request.params.clone()) {
            Ok(intent) => intent,
            Err(_) => return self.rejected(request.request_id, "invalid_request", "invalid UI intent"),
        };
        if intent.validate().is_err() { return self.rejected(request.request_id, ERROR_INTENT_NOT_BOUND, "UI intent is not bound"); }
        let neon_ui_schema::UiIntent::Invoke { action, params } = intent.clone();
        if action == "ui.surface.event" {
            request.method = "ui.surface.event".into();
            request.params = params;
            return self.handle_surface_event(request);
        }
        match self.apply_ai_terrain_intent(&action, &params) {
            Ok(Some(snapshot)) => return self.accepted(request.request_id, snapshot),
            Ok(None) => {}
            Err((code, message)) => return self.rejected(request.request_id, code, message),
        }
        self.accepted(request.request_id, json!({"intent": intent}))
    }

    fn validate_semantic_event(&mut self, event: &UiSemanticEvent) -> Result<(), &'static str> {
        if event.renderer_epoch != self.epoch { return Err(ERROR_RENDERER_EPOCH_MISMATCH); }
        if event.event == neon_ui_schema::UiSemanticEventType::TextInputCommit && event.text.is_none() { return Err(ERROR_INTENT_NOT_BOUND); }
        let Some(fragment) = self.cached_fragment.as_ref() else { return Err(ERROR_INTENT_NOT_BOUND); };
        if fragment.fragment_id != event.fragment.id || fragment.revision != event.fragment.revision { return Err(ERROR_FRAGMENT_REVISION_STALE); }
        if !fragment.effects.iter().any(|effect| matches!(effect, UiEffect::SemanticIntent { intent } | UiEffect::BoundSemanticIntent { intent, .. } if intent == &event.intent)) {
            return Err(ERROR_INTENT_NOT_BOUND);
        }
        if let Some(pointer) = &event.pointer {
            if self.last_input_sequence.get(&pointer.id).is_some_and(|last| pointer.sequence <= *last) { return Err(ERROR_INPUT_SEQUENCE_STALE); }
            self.last_input_sequence.insert(pointer.id, pointer.sequence);
        }
        event.intent.validate().map_err(|_| ERROR_INTENT_NOT_BOUND)
    }

    fn accepted(&mut self, request_id: RequestId, result: Value) -> RpcResponse {
        self.record_receipt(&request_id, CommandState::Accepted, None);
        RpcResponse { request_id, status: RpcStatus::Accepted, revision: Some(self.debug_snapshot().revision), result: Some(result), snapshot: None, error: None }
    }

    fn rejected(&mut self, request_id: RequestId, code: &str, message: &str) -> RpcResponse {
        self.record_receipt(&request_id, CommandState::Rejected, Some(code.into()));
        RpcResponse { request_id, status: RpcStatus::Rejected, revision: Some(self.debug_snapshot().revision), result: None, snapshot: None, error: Some(RpcError { code: code.into(), message: message.into(), current_revision: Some(self.debug_snapshot().revision), object_id: None }) }
    }

    fn record_receipt(&mut self, request_id: &RequestId, state: CommandState, error_code: Option<String>) {
        let revision = self.debug_snapshot().revision;
        self.receipts.insert(request_id.clone(), CommandReceipt { request_id: request_id.clone(), state, revision_before: Some(revision), revision_after: Some(revision), error_code });
    }

    pub fn static_fragment(&self, revision: Revision) -> UiFragment {
        UiFragment {
            fragment_id: UiFragmentId("static-editor-shell".into()),
            revision,
            root: UiNode {
                node_id: UiNodeId("root-panel".into()),
                kind: UiNodeKind::Panel,
                bounds: UiBounds {
                    x: 0.0,
                    y: 0.0,
