                "ui_ir_duplicate_key",
                "node keys must be unique across the Flow document",
                line,
                1,
            ));
        }
        for (property, input_key) in &node.bindings {
            bindings.push(UiIrBinding {
                node_key: node.node.node_id.0.clone(),
                input_key: input_key.clone(),
                property: property.clone(),
