fn error(code: &str, message: &str, line: u32, column: u32) -> NuiFlowError {
    NuiFlowError {
        diagnostics: vec![NuiFlowParseDiagnostic {
            code: code.into(),
            severity: UiDiagnosticSeverity::Error,
