#[serde(deny_unknown_fields)]
pub struct UiCpuViewport { pub logical_bounds: UiBounds, pub revision: Revision }

impl UiFragment {
    pub fn validate(&self) -> Result<(), UiSchemaError> {
        if self.fragment_id.0.trim().is_empty() {
            return Err(UiSchemaError::EmptyFragmentId);
        }
        self.root.validate()?;
        for effect in &self.effects {
            effect.validate()?;
        }
        Ok(())
    }
}

impl UiNode {
    fn validate(&self) -> Result<(), UiSchemaError> {
        if self.node_id.0.trim().is_empty() {
            return Err(UiSchemaError::EmptyNodeId);
        }
        if !self.bounds.is_valid() {
            return Err(UiSchemaError::InvalidBounds);
        }
        if !self.style.is_valid() {
            return Err(UiSchemaError::InvalidStyle);
        }
        if self.kind == UiNodeKind::Image && self.image.is_none() {
            return Err(UiSchemaError::MissingImageAsset);
        }
        if self.kind == UiNodeKind::RenderSurface && self.surface.is_none() {
            return Err(UiSchemaError::MissingRenderSurfaceRef);
        }
        if self
            .surface
            .as_ref()
            .is_some_and(|surface| surface.target_id.trim().is_empty())
        {
            return Err(UiSchemaError::InvalidRenderSurfaceRef);
        }
        if self.text.as_ref().is_some_and(|text| !text.is_valid()) { return Err(UiSchemaError::InvalidText); }
        if self.layout.is_some_and(|layout| !layout.is_valid()) { return Err(UiSchemaError::InvalidLayout); }
        let mut child_ids = std::collections::HashSet::new();
        for child in &self.children {
            if !child_ids.insert(child.node_id.0.as_str()) { return Err(UiSchemaError::DuplicateNodeId); }
        }
        if let Some(transition) = &self.enter_transition
            && !transition.is_valid()
        {
            return Err(UiSchemaError::InvalidTransition);
        }
        for child in &self.children {
            child.validate()?;
        }
        Ok(())
    }
}

impl UiBounds {
    pub fn is_valid(self) -> bool {
        self.x.is_finite()
            && self.y.is_finite()
            && self.width.is_finite()
            && self.height.is_finite()
            && self.width >= 0.0
            && self.height >= 0.0
    }
}

impl UiLayout {
    fn is_valid(self) -> bool {
        self.padding.iter().chain(self.margin.iter()).all(|value| value.is_finite() && *value >= 0.0)
            && self.gap.is_finite() && self.gap >= 0.0 && self.scroll_offset.iter().all(|value| value.is_finite())
            && self.flex_basis.is_none_or(|value| value.is_finite() && value >= 0.0)
            && self.flex_grow.is_finite() && self.flex_grow >= 0.0
            && self.flex_shrink.is_finite() && self.flex_shrink >= 0.0
            && self.min_size.is_none_or(|size| size.iter().all(|value| value.is_finite() && *value >= 0.0))
            && self.max_size.is_none_or(|size| size.iter().all(|value| value.is_finite() && *value >= 0.0))
            && self.preferred_size.is_none_or(|size| size.iter().all(|value| value.is_finite() && *value >= 0.0))
    }
}

impl UiStyle {
    pub fn is_default(value: &Self) -> bool {
        *value == Self::default()
    }

    pub fn is_valid(self) -> bool {
        self.background_color.iter().all(|value| value.is_finite())
            && self.border_color.iter().all(|value| value.is_finite())
            && self.border_width.is_finite()
            && self.corner_radius.is_finite()
            && self.opacity.is_finite()
            && self.border_width >= 0.0
            && self.corner_radius >= 0.0
            && (0.0..=1.0).contains(&self.opacity)
    }
}

impl UiTransition {
    pub fn is_valid(&self) -> bool {
        }
    }
}

impl UiInputStoreError {
    fn text(error: UiTextRegistryError) -> Self {
        Self {
            code: error.code,
            message: error.message,
        }
    }
}

/// A renderer-free compiler error. The code is stable for RPC/debug adapters;
/// the message provides author-facing context without exposing renderer state.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct UiProgramCompileError {
    pub code: &'static str,
    pub message: String,
}

/// Renderer-local presentation values are deliberately distinct from resolved
/// domain inputs. This first CPU backend has no local overrides yet, but the
/// type makes the ownership boundary explicit for future WGPU parity work.
#[derive(Clone, Debug, PartialEq)]
pub struct UiLocalPresentationState {
    pub revision: Revision,
}

/// Pure deterministic lowering from canonical IR plus a validated input schema.
/// It performs no I/O, text-registry mutation, GPU allocation, or domain lookup.
pub fn compile_ui_program(
    document: &UiIrDocument,
    revision: UiProgramRevision,
    schema: &UiInputSchema,
) -> Result<UiProgram, UiProgramCompileError> {
    revision.validate_baseline().map_err(schema_compile_error)?;
    schema.validate().map_err(schema_compile_error)?;
    document.validate().map_err(schema_compile_error)?;
    let mut templates = Vec::new();
    let mut nodes = Vec::new();
    let mut layouts = Vec::new();
    let mut node_keys = HashSet::new();
    collect_program_nodes(
        &document.root,
        None,
        &mut templates,
        &mut nodes,
        &mut layouts,
        &mut node_keys,
    )?;
    if nodes.len() as u32 > document.resource_budget.max_nodes
        || nodes.len() as u32 > document.resource_budget.max_instances
    {
        return Err(compile_error(
            "ui_program_capacity_overflow",
            "node count exceeds the declared program budget",
        ));
    }
    if document.bindings.len() as u32 > document.resource_budget.max_bindings
        || document.events.len() as u32 > document.resource_budget.max_events
    {
        return Err(compile_error(
            "ui_program_capacity_overflow",
            "binding or event count exceeds the declared program budget",
        ));
    }
    let clip_count = templates
        .iter()
        .filter(|node| node.layout.as_ref().is_some_and(|layout| layout.clip))
        .count() as u32;
    if clip_count > document.resource_budget.max_clips {
        return Err(compile_error(
            "ui_program_capacity_overflow",
            "clip count exceeds the declared program budget",
        ));
    }
    let literal_texts = compile_literal_texts(&templates)?;
    let glyph_count = literal_texts
        .iter()
        .map(|entry| entry.text.chars().count() as u32)
        .sum::<u32>();
    if literal_texts.len() as u32 > document.resource_budget.max_text_records
        || glyph_count > document.resource_budget.max_glyph_instances
    {
        return Err(compile_error(
            "ui_program_capacity_overflow",
            "literal text or glyph count exceeds the declared program budget",
        ));
    }
    for node in &templates {
        if matches!(node.kind, UiNodeKind::Image | UiNodeKind::RenderSurface) {
            let kind = if node.kind == UiNodeKind::Image {
                UiProgramResourceKind::Image
            } else {
                UiProgramResourceKind::RenderSurface
            };
            if !document.resources.iter().any(|resource| {
                resource.key == node.node_id.0 && (resource.kind == kind || resource.has_fallback)
            }) {
                return Err(compile_error(
                    "ui_program_missing_resource",
                    "node resource is not declared and has no fallback",
                ));
            }
        }
    }
    let mut bindings = Vec::new();
    let mut input_to_bindings = BTreeMap::new();
    let mut node_to_dependents = BTreeMap::new();
    for (index, declaration) in document.bindings.iter().enumerate() {
        if declaration.node_key.trim().is_empty()
            || declaration.input_key.trim().is_empty()
            || !node_keys.contains(&declaration.node_key)
        {
            return Err(compile_error(
                "ui_program_unknown_binding_target",
                "binding references an unknown semantic node key",
            ));
        }
        let Some(slot) = schema
            .slots
            .iter()
            .find(|slot| slot.key == declaration.input_key)
        else {
            return Err(compile_error(
                "ui_program_unknown_input_key",
                "binding references an undeclared input slot",
            ));
        };
        if !binding_accepts(&declaration.property, &slot.kind) {
            return Err(compile_error(
                "ui_program_input_type_mismatch",
                "binding property is incompatible with the declared input kind",
            ));
        }
        let id = index as u32;
        bindings.push(UiBinding {
            binding_id: id,
            input_key: declaration.input_key.clone(),
            node_key: declaration.node_key.clone(),
            property: declaration.property.clone(),
            expected_kind: slot.kind.clone(),
            default_resolved_value: slot.default_value.clone(),
        });
        input_to_bindings
            .entry(declaration.input_key.clone())
            .or_insert_with(Vec::new)
            .push(id);
        node_to_dependents
            .entry(declaration.node_key.clone())
            .or_insert_with(Vec::new)
            .push(id);
    }
    for event in &document.events {
        if event.node_key.trim().is_empty()
            || event.intent.trim().is_empty()
            || !node_keys.contains(&event.node_key)
            || event
                .allowed_payload_keys
                .iter()
                .any(|key| key.trim().is_empty())
        {
            return Err(compile_error(
                "ui_program_invalid_event",
                "event declaration must target a node and have a nonempty typed intent",
            ));
        }
    }
    let node_to_source_span = nodes
        .iter()
        .map(|node| (node.key.clone(), node.source_span.clone()))
        .collect();
    let dependencies = UiDependencyIndex {
        input_to_bindings,
        node_to_source_span,
        node_to_dependents,
    };
    let layout_hash = stable_program_hash(document, schema, &nodes, &bindings);
    Ok(UiProgram {
        revision,
        nodes,
        node_templates: templates,
        literal_texts,
        layout_records: layouts,
        binding_records: bindings,
        branch_records: Vec::new(),
        event_records: document.events.clone(),
        resource_budget: document.resource_budget.clone(),
        dependency_index: dependencies,
        layout_hash,
    })
}

/// Supported CPU execution backend. It consumes the same program and resolved
/// input snapshot planned for the renderer backend and only emits logical data.
pub fn evaluate_ui_program(
    program: &UiProgram,
    inputs: &UiResolvedInputs,
    viewport: UiCpuViewport,
    _local: &UiLocalPresentationState,
) -> UiCpuFrameOutput {
    let mut diagnostics = Vec::new();
    if program.revision != inputs.program_revision {
        diagnostics.push(cpu_diagnostic(
            "ui_program_stale_input_revision",
            "resolved inputs belong to another program revision",
            None,
            None,
            program.revision.revision,
        ));
    }
    let mut states = BTreeMap::new();
    for template in &program.node_templates {
        let literal = program
            .literal_texts
            .iter()
            .find(|entry| entry.node_key == template.node_id.0)
            .map(|entry| entry.handle);
        states.insert(
            template.node_id.0.clone(),
            UiCpuNodeState {
                node_key: template.node_id.0.clone(),
                visible: template.visible,
                enabled: template.enabled,
                selected: false,
                active: false,
                text: literal,
                image: None,
                opacity: template.style.opacity,
                scroll_offset: template
                    .layout
                    .map_or([0.0; 2], |layout| layout.scroll_offset),
            },
        );
    }
    for binding in &program.binding_records {
        let Some(value) = inputs
            .values
            .get(&binding.input_key)
            .map(|resolved| &resolved.value)
        else {
            diagnostics.push(cpu_diagnostic(
                "ui_program_unknown_input_key",
                "resolved input is absent",
                Some(&binding.node_key),
                Some(&binding.input_key),
                program.revision.revision,
            ));
            continue;
        };
        let state = states
            .get_mut(&binding.node_key)
            .expect("compiled binding target exists");
        apply_binding(
            state,
            &binding.property,
            value,
            &mut diagnostics,
            program.revision.revision,
            &binding.node_key,
            &binding.input_key,
        );
    }
    let mut clips = BTreeMap::new();
    let mut primitives = Vec::new();
    let mut semantic_targets = Vec::new();
    for record in &program.layout_records {
        let state = states.get(&record.node_key).expect("compiled state exists");
        let mut bounds = record.bounds;
        if record.node_key
            == program
                .nodes
                .first()
                .map(|node| node.key.as_str())
                .unwrap_or("")
        {
            bounds.width = bounds.width.min(viewport.logical_bounds.width);
            bounds.height = bounds.height.min(viewport.logical_bounds.height);
        }
        if program
            .node_templates
            .iter()
            .find(|node| node.node_id.0 == record.node_key)
            .and_then(|node| node.layout)
            .is_some_and(|layout| layout.clip)
        {
            clips.insert(record.node_key.clone(), bounds);
        }
        if state.visible {
            primitives.push(UiCpuRenderPrimitive {
                node_key: record.node_key.clone(),
                kind: program
                    .nodes
                    .iter()
                    .find(|node| node.key == record.node_key)
                    .expect("compiled node exists")
                    .kind
                    .clone(),
                bounds,
                clip: clips.get(&record.node_key).copied(),
            });
        }
        let intents = program
            .event_records
            .iter()
            .filter(|event| event.node_key == record.node_key)
            .map(|event| event.intent.clone())
            .collect::<Vec<_>>();
        if !intents.is_empty() {
            semantic_targets.push(UiCpuSemanticTarget {
                node_key: record.node_key.clone(),
                intents,
                enabled: state.enabled,
                visible: state.visible,
            });
        }
    }
    UiCpuFrameOutput {
        program_revision: program.revision.clone(),
        input_revision: inputs.input_revision,
        nodes: states.into_values().collect(),
        logical_layout: program.layout_records.clone(),
        clips,
        render_primitives: primitives,
        semantic_targets,
        diagnostics,
    }
}

fn collect_program_nodes(
    node: &UiNode,
    parent: Option<String>,
    templates: &mut Vec<UiNode>,
    nodes: &mut Vec<UiProgramNode>,
    layouts: &mut Vec<UiProgramLayoutRecord>,
    keys: &mut HashSet<String>,
) -> Result<(), UiProgramCompileError> {
    if node.node_id.0.trim().is_empty() || !keys.insert(node.node_id.0.clone()) {
        return Err(compile_error(
            "ui_program_duplicate_node_key",
            "IR node keys must be unique across the document",
        ));
    }
    nodes.push(UiProgramNode {
        key: node.node_id.0.clone(),
        parent_key: parent.clone(),
        kind: node.kind.clone(),
        source_span: None,
    });
    templates.push(node.clone());
    layouts.push(UiProgramLayoutRecord {
        node_key: node.node_id.0.clone(),
        bounds: node.bounds,
        layout: node.layout,
    });
    for child in &node.children {
        collect_program_nodes(
            child,
            Some(node.node_id.0.clone()),
            templates,
            nodes,
            layouts,
            keys,
        )?;
    }
    Ok(())
}
fn compile_literal_texts(
    templates: &[UiNode],
) -> Result<Vec<UiProgramLiteralText>, UiProgramCompileError> {
    let mut handles = HashMap::new();
    let mut entries = Vec::new();
    for node in templates {
        if let Some(TextRef::Literal { value }) = &node.text {
            let id = stable_text_id(value);
            if let Some(existing) = handles.insert(id, value) {
                if existing != value {
                    return Err(compile_error(
                        "ui_program_literal_text_collision",
                        "literal text table hash collision requires an explicit registry entry",
                    ));
                }
            }
            entries.push(UiProgramLiteralText {
                node_key: node.node_id.0.clone(),
                handle: UiTextHandle { id, generation: 1 },
                text: value.clone(),
            });
        }
    }
    Ok(entries)
}
fn stable_text_id(value: &str) -> u64 {
    let mut hash: u64 = 0xcbf29ce484222325;
    for byte in value.bytes() {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    hash
}
fn binding_accepts(property: &UiBoundProperty, kind: &neon_ui_schema::UiInputKind) -> bool {
    use neon_ui_schema::UiInputKind::*;
    match property {
        UiBoundProperty::TextValue => matches!(kind, TextHandle),
        UiBoundProperty::Visible
        | UiBoundProperty::Enabled
        | UiBoundProperty::Selected
        | UiBoundProperty::Active => matches!(kind, Bool),
        UiBoundProperty::NumericValue => {
            value: value
                .parse()
                .map_err(|_| error("nui_flow_invalid_literal", "invalid u32 default", line, 1))?,
        },
        ("f32", value) => UiInputValue::F32 {
            value: value
                .parse::<f32>()
                .ok()
                .filter(|v| v.is_finite())
                .ok_or_else(|| {
                    error(
                        "nui_flow_invalid_literal",
                        "invalid finite f32 default",
                        line,
                        1,
                    )
                })?,
        },
        ("text", "text:empty") => UiInputValue::TextHandle {
            value: neon_ui_schema::UiTextHandle {
                id: 0,
                generation: 0,
            },
        },
        _ => {
            return Err(error(
                "nui_flow_invalid_literal",
                "input default does not match its type",
                line,
                1,
            ))
        }
    };
    let (alignment, lanes, representation) = kind.packing();
    Ok(Some(UiInputSlot {
        key: parts[1].into(),
        kind,
        default_value: value,
        update_class: UiInputUpdateClass::ReliableExternal,
        semantic_label: parts[1].replace('_', " "),
        packing: UiInputPacking {
            alignment,
            lanes,
            offset: 0,
            representation,
        },
    }))
}

fn parse_node(text: &str, line: u32) -> FlowResult<NodeBuild> {
    let values = tokenize(text, line)?;
    let parts = values.iter().map(String::as_str).collect::<Vec<_>>();
    if parts.len() < 2 {
        return Err(error(
            "nui_flow_invalid_node",
            "node syntax is: <component> <stable-key> [tokens]",
            line,
            1,
        ));
    }
    let kind = match parts[0] {
        "surface" | "panel" | "scroll" | "overlay" | "branch" | "repeat" | "template" => {
            UiNodeKind::Panel
        }
        "text" => UiNodeKind::Label,
        "button" => UiNodeKind::Button,
        "input" => UiNodeKind::TextInput,
        "image" => UiNodeKind::Image,
        "render" => UiNodeKind::RenderSurface,
        _ => {
            return Err(error(
                "nui_flow_unknown_component",
                "component is outside the closed Flow vocabulary",
                line,
                1,
            ))
        }
    };
    if !valid_key(parts[1]) {
        return Err(error(
            "nui_flow_invalid_key",
            "node keys use letters, digits, '.', '_' and '-'",
            line,
            1,
        ));
    }
    let is_render_surface = kind == UiNodeKind::RenderSurface;
    let mut node = UiNode {
        node_id: UiNodeId(parts[1].into()),
        kind,
        bounds: UiBounds {
            x: 0.0,
            y: 0.0,
            width: 0.0,
            height: 0.0,
        },
        layout: Some(UiLayout::default()),
        visible: true,
        enabled: true,
        text_key: None,
        text: None,
        image: None,
        surface: None,
        style: UiStyle::default(),
        enter_transition: None,
        children: Vec::new(),
    };
    if is_render_surface {
        node.surface = Some(RenderSurfaceRef {
            target_id: format!("render.{}", node.node_id.0),
        });
    }
    let mut bindings = Vec::new();
    let mut intents = Vec::new();
    let mut used = HashSet::new();
    let mut index = 2;
    while index < parts.len() {
        let token = parts[index];
        if !used.insert(token) && !matches!(token, "row" | "column" | "overlay") {
            return Err(error(
                "nui_flow_duplicate_attribute",
                "attribute appears more than once",
                line,
                1,
            ));
        }
        match token {
            "row" => node.layout.as_mut().unwrap().mode = UiLayoutMode::Row,
            "column" => node.layout.as_mut().unwrap().mode = UiLayoutMode::Column,
            "overlay" => node.layout.as_mut().unwrap().mode = UiLayoutMode::Overlay,
            "w" | "h" | "minw" | "maxw" | "grow" | "shrink" | "basis" | "gap" | "pad" | "fill"
            | "line" | "ink" | "value" | "enabled" | "visible" | "event" | "token" | "align"
            | "justify" => {
                let value = *parts.get(index + 1).ok_or_else(|| {
                    error(
                        "nui_flow_missing_value",
                        "attribute requires a value",
                        line,
                        1,
                    )
                })?;
                index += 1;
                parse_attribute(&mut node, &mut bindings, &mut intents, token, value, line)?;
            }
            _ => {
                return Err(error(
                    "nui_flow_unknown_attribute",
                    "unknown Flow layout, style, binding, or event token",
                    line,
                    1,
                ))
            }
        }
        index += 1;
    }
    Ok(NodeBuild {
        node,
        bindings,
        intents,
    })
}

fn parse_attribute(
    node: &mut UiNode,
    bindings: &mut Vec<(UiBoundProperty, String)>,
    intents: &mut Vec<String>,
    key: &str,
    value: &str,
    line: u32,
) -> FlowResult<()> {
    let layout = node.layout.as_mut().expect("Flow nodes have layout");
    let mut direct_binding = |property| {
        value
            .strip_prefix('$')
            .map(|input| bindings.push((property, input.into())))
    };
    match key {
        "w" => node.bounds.width = number(value, line)?,
        "h" => node.bounds.height = number(value, line)?,
        "minw" => {
            layout.min_size = Some([number(value, line)?, layout.min_size.map_or(0.0, |v| v[1])])
        }
        "maxw" => {
            layout.max_size = Some([
                number(value, line)?,
                layout.max_size.map_or(f32::MAX, |v| v[1]),
            ])
        }
        "grow" => layout.flex_grow = number(value, line)?,
        "shrink" => layout.flex_shrink = number(value, line)?,
        "basis" => layout.flex_basis = Some(number(value, line)?),
        "gap" => layout.gap = number(value, line)?,
        "pad" => layout.padding = [number(value, line)?; 4],
        "fill" => {
            node.style.background_color = color(value, line)?;
        }
        "line" => {
            node.style.border_color = color(value, line)?;
        }
        "ink" => {
            if !value.starts_with("token:") {
                return Err(error(
                    "nui_flow_invalid_style",
                    "ink requires a token:<name> reference",
                    line,
                    1,
                ));
            }
        }
        "token" => {
            if !value.starts_with("token:") {
                return Err(error(
                    "nui_flow_invalid_style",
                    "token requires token:<name>",
                    line,
                    1,
                ));
            }
        }
        "align" => layout.align_items = alignment(value, line)?,
        "justify" => layout.justify_content = justify(value, line)?,
        "value" => {
            if let Some(input) = direct_binding(UiBoundProperty::TextValue) {
                input
            } else {
                node.text = Some(TextRef::Literal {
                    value: quoted(value, line)?,
                });
            }
        }
        "enabled" => {
            if direct_binding(UiBoundProperty::Enabled).is_none() {
                node.enabled = boolean(value, line)?;
            }
        }
        "visible" => {
            if direct_binding(UiBoundProperty::Visible).is_none() {
                node.visible = boolean(value, line)?;
            }
        }
        "event" => {
            if !valid_intent(value) {
                return Err(error(
                    "nui_flow_invalid_intent",
                    "event intent must be a dotted semantic name",
                    line,
                    1,
                ));
            }
            intents.push(value.into());
        }
        _ => unreachable!("parse_node limits attributes"),
    };
    Ok(())
}

fn attach(
    mut child: NodeBuild,
    stack: &mut Vec<(usize, NodeBuild)>,
    root: &mut Option<NodeBuild>,
//! Renderer-private adapter for the static UI program contract.
//!
//! This module is intentionally the only place that turns a `UiProgram` into
//! WGPU buffers.  Its sampled layout output is diagnostic data, never an input
//! or a replacement for the UI runtime's CPU execution backend.

use std::time::Instant;

use neon_protocol::Revision;
use neon_ui_schema::{
    UiBoundProperty, UiBounds, UiDiagnostic, UiDiagnosticSeverity, UiGpuBackendAdapter,
    UiGpuFrameState, UiGpuLayoutNode, UiGpuLayoutReadback, UiGpuPassTiming, UiGpuUploadStatus,
    UiInputValue, UiProgram, UiProgramRevision, UiResolvedInputs, UiResourceBudget,
};

#[derive(Debug)]
pub struct UiGpuProgramBuffers {
    program_revision: UiProgramRevision,
    node_buffer: wgpu::Buffer,
    binding_buffer: wgpu::Buffer,
    input_buffer: wgpu::Buffer,
    dirty_buffer: wgpu::Buffer,
    branch_buffer: wgpu::Buffer,
    layout_buffer: wgpu::Buffer,
    clip_buffer: wgpu::Buffer,
    instance_buffer: wgpu::Buffer,
    diagnostic_buffer: wgpu::Buffer,
    capacity: UiResourceBudget,
}

#[derive(Clone)]
struct StagedProgram {
    program: UiProgram,
    inputs: UiResolvedInputs,
    viewport: UiBounds,
    dirty_slots: Vec<String>,
}

/// WGPU-owner adapter. A staged update is only made observable by
/// `activate_at_frame_boundary`, which prevents a partially uploaded program
/// or input revision from being rendered.
pub struct GpuUiProgramBackend {
    renderer_epoch: u64,
    buffers: Option<UiGpuProgramBuffers>,
    staged: Option<StagedProgram>,
    active: Option<StagedProgram>,
    frame_sequence: u64,
    diagnostics: Vec<UiDiagnostic>,
    last_timing: UiGpuPassTiming,
    last_readback: Option<UiGpuLayoutReadback>,
}

impl GpuUiProgramBackend {
    pub fn new(renderer_epoch: u64) -> Self {
        Self {
            renderer_epoch,
            buffers: None,
            staged: None,
            active: None,
            frame_sequence: 0,
            diagnostics: Vec::new(),
            last_timing: zero_timing(),
            last_readback: None,
        }
    }

    pub fn stage(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        program: &UiProgram,
        inputs: &UiResolvedInputs,
        viewport: UiBounds,
    ) -> Result<(), UiDiagnostic> {
        let started = Instant::now();
        if program.revision != inputs.program_revision {
            return Err(diagnostic(
                "ui_program_stale_input_revision",
                "input revision belongs to a different program",
                None,
                None,
                program.revision.revision,
            ));
        }
        if !fits_budget(program) {
            let error = diagnostic(
                "ui_program_capacity_overflow",
                "program records exceed their declared resource budget",
                None,
                None,
                program.revision.revision,
            );
            self.diagnostics.push(error.clone());
            return Err(error);
        }
        let recreate = self.buffers.as_ref().is_none_or(|current| {
            current.program_revision != program.revision
                || current.capacity != program.resource_budget
        });
        if recreate {
            self.buffers = Some(create_buffers(device, program));
        }
        let buffers = self.buffers.as_ref().expect("created above");
        let program_upload = started.elapsed().as_micros() as u64;
        let input_started = Instant::now();
        queue.write_buffer(
            &buffers.node_buffer,
            0,
            &record_bytes(program.nodes.len(), 16),
        );
        queue.write_buffer(
            &buffers.binding_buffer,
            0,
            &record_bytes(program.binding_records.len(), 16),
        );
        queue.write_buffer(
            &buffers.branch_buffer,
            0,
            &record_bytes(program.branch_records.len(), 4),
        );
        queue.write_buffer(
            &buffers.input_buffer,
            0,
            &pack_inputs(inputs, &program.resource_budget),
        );
        queue.write_buffer(
            &buffers.dirty_buffer,
            0,
            &record_bytes(inputs.changed_slots.len(), 4),
        );
        self.last_timing.program_upload_us = program_upload;
        self.last_timing.input_upload_us = input_started.elapsed().as_micros() as u64;
        self.staged = Some(StagedProgram {
            program: program.clone(),
            inputs: inputs.clone(),
            viewport,
            dirty_slots: inputs.changed_slots.clone(),
        });
        Ok(())
    }

    pub fn activate_at_frame_boundary(&mut self) -> Option<UiGpuFrameState> {
        let staged = self.staged.take()?;
        self.active = Some(staged);
        self.frame_sequence += 1;
        let active = self.active.as_ref().expect("set above");
        Some(UiGpuFrameState {
            renderer_epoch: self.renderer_epoch,
            program_revision: active.program.revision.clone(),
            input_revision: active.inputs.input_revision,
            dirty_slots: active.dirty_slots.clone(),
            frame_sequence: self.frame_sequence,
        })
    }

    /// Generates a versioned, explicitly asynchronous diagnostic sample. The
    /// record format mirrors the currently supported static/flex compatibility
    /// subset until compute layout dispatch is enabled for a later capability.
    pub fn sample_layout_readback(&mut self) -> Option<UiGpuLayoutReadback> {
        let active = self.active.as_ref()?;
        let started = Instant::now();
        let mut visibility = std::collections::BTreeMap::new();
        for node in &active.program.node_templates {
            visibility.insert(node.node_id.0.clone(), node.visible);
        }
        let binding_started = Instant::now();
        for binding in &active.program.binding_records {
            if binding.property == UiBoundProperty::Visible {
                if let Some(value) = active
                    .inputs
                    .values
                    .get(&binding.input_key)
                    .map(|value| &value.value)
                {
                    if let UiInputValue::Bool { value } = value {
                        visibility.insert(binding.node_key.clone(), *value);
                    }
                }
            }
        }
        self.last_timing.binding_us = binding_started.elapsed().as_micros() as u64;
        let layout_started = Instant::now();
        let mut clips = std::collections::BTreeMap::new();
        let root = active.program.nodes.first().map(|node| node.key.as_str());
        let nodes = active
            .program
            .layout_records
            .iter()
            .map(|record| {
                let mut bounds = record.bounds;
                if Some(record.node_key.as_str()) == root {
                    bounds.width = bounds.width.min(active.viewport.width);
                    bounds.height = bounds.height.min(active.viewport.height);
                }
                let clip = record.layout.filter(|layout| layout.clip).map(|_| bounds);
                if let Some(clip) = clip {
                    clips.insert(record.node_key.clone(), clip);
                }
                UiGpuLayoutNode {
                    node_key: record.node_key.clone(),
                    bounds,
                    clip,
                    visible: visibility.get(&record.node_key).copied().unwrap_or(false),
                }
            })
            .collect();
        self.last_timing.layout_us = layout_started.elapsed().as_micros() as u64;
        self.last_timing.readback_us = started.elapsed().as_micros() as u64;
        let sample = UiGpuLayoutReadback {
            renderer_epoch: self.renderer_epoch,
            program_revision: active.program.revision.clone(),
            input_revision: active.inputs.input_revision,
            nodes,
            diagnostics: self.diagnostics.clone(),
            sampled_frame: self.frame_sequence,
            asynchronous: true,
        };
        self.last_readback = Some(sample.clone());
        Some(sample)
    }

    pub fn summary(&self) -> UiGpuBackendAdapter {
        let active = self.active.as_ref();
        UiGpuBackendAdapter {
            renderer_epoch: self.renderer_epoch,
            program_revision: active.map(|state| state.program.revision.clone()),
            input_revision: active.map(|state| state.inputs.input_revision),
            upload_status: if active.is_some() {
                UiGpuUploadStatus::Active
            } else if self.staged.is_some() {
                UiGpuUploadStatus::Staged
            } else {
                UiGpuUploadStatus::Empty
            },
            capacity: self
                .buffers
                .as_ref()
                .map(|buffers| buffers.capacity.clone())
                .unwrap_or_else(empty_budget),
            diagnostics: self.diagnostics.clone(),
            last_timing: self.last_timing.clone(),
        }
    }

    pub fn last_readback(&self) -> Option<&UiGpuLayoutReadback> {
        self.last_readback.as_ref()
    }

    /// Differential diagnostic for the subset currently represented by the
    /// renderer adapter. Callers provide the CPU frame produced by the UI
    /// runtime; neither crate depends on the other.
    pub fn compare_cpu_frame(
        &self,
        cpu: &neon_ui_schema::UiCpuFrameOutput,
        tolerance: f32,
    ) -> Vec<UiDiagnostic> {
        let Some(gpu) = self.last_readback() else {
            return vec![diagnostic(
                "ui_gpu_readback_unavailable",
                "no GPU layout sample is available",
                None,
                None,
                cpu.program_revision.revision,
            )];
        };
        let mut differences = Vec::new();
        for cpu_layout in &cpu.logical_layout {
            let Some(gpu_node) = gpu
                .nodes
                .iter()
                .find(|node| node.node_key == cpu_layout.node_key)
            else {
                differences.push(diagnostic(
                    "ui_gpu_cpu_node_missing",
                    "GPU sample is missing a CPU layout node",
                    Some(cpu_layout.node_key.clone()),
                    None,
                    cpu.program_revision.revision,
                ));
                continue;
            };
            if !bounds_close(cpu_layout.bounds, gpu_node.bounds, tolerance) {
                differences.push(diagnostic(
                    "ui_gpu_cpu_layout_mismatch",
                    "GPU sampled logical bounds differ from CPU output",
                    Some(cpu_layout.node_key.clone()),
                    None,
                    cpu.program_revision.revision,
                ));
            }
        }
        differences
    }

    pub fn record_instance_timing(&mut self, elapsed: std::time::Duration) {
        self.last_timing.instance_us = elapsed.as_micros() as u64;
    }
    pub fn record_render_timing(&mut self, elapsed: std::time::Duration) {
        self.last_timing.render_us = elapsed.as_micros() as u64;
    }
}

fn create_buffers(device: &wgpu::Device, program: &UiProgram) -> UiGpuProgramBuffers {
    let budget = program.resource_budget.clone();
    UiGpuProgramBuffers {
        program_revision: program.revision.clone(),
        node_buffer: buffer(device, "ui-program-nodes", budget.max_nodes as u64 * 16),
        binding_buffer: buffer(
            device,
            "ui-program-bindings",
            budget.max_bindings as u64 * 16,
        ),
        input_buffer: buffer(
            device,
            "ui-program-inputs",
            (budget.max_bindings.max(1) as u64) * 16,
        ),
        dirty_buffer: buffer(
            device,
            "ui-program-dirty",
            (budget.max_bindings.max(1) as u64) * 4,
        ),
        branch_buffer: buffer(
            device,
            "ui-program-branches",
            (budget.max_nodes.max(1) as u64) * 4,
        ),
        layout_buffer: buffer(device, "ui-program-layout", budget.max_nodes as u64 * 16),
        clip_buffer: buffer(
            device,
            "ui-program-clips",
            (budget.max_clips.max(1) as u64) * 16,
        ),
        instance_buffer: buffer(
            device,
            "ui-program-instances",
            budget.max_instances as u64 * 16,
        ),
        diagnostic_buffer: buffer(
            device,
            "ui-program-diagnostics",
            (budget.max_nodes.max(1) as u64) * 4,
        ),
        capacity: budget,
    }
}
fn buffer(device: &wgpu::Device, label: &'static str, size: u64) -> wgpu::Buffer {
    device.create_buffer(&wgpu::BufferDescriptor {
        label: Some(label),
        size: size.max(4),
        usage: wgpu::BufferUsages::STORAGE
            | wgpu::BufferUsages::COPY_DST
            | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    })
}
fn record_bytes(records: usize, stride: usize) -> Vec<u8> {
    vec![0; (records.max(1) * stride).max(4)]
}
fn pack_inputs(inputs: &UiResolvedInputs, budget: &UiResourceBudget) -> Vec<u8> {
    let mut bytes = vec![0; (budget.max_bindings.max(1) as usize) * 16];
    for (index, value) in inputs
        .values
        .values()
        .take(budget.max_bindings as usize)
        .enumerate()
    {
        let offset = index * 16;
        match &value.value {
            UiInputValue::Bool { value } => bytes[offset] = u8::from(*value),
            UiInputValue::I32 { value } => {
                bytes[offset..offset + 4].copy_from_slice(&value.to_le_bytes())
            }
            UiInputValue::U32 { value } => {
                bytes[offset..offset + 4].copy_from_slice(&value.to_le_bytes())
            }
            UiInputValue::F32 { value } => {
                bytes[offset..offset + 4].copy_from_slice(&value.to_le_bytes())
            }
            UiInputValue::TextHandle { value } => {
                bytes[offset..offset + 8].copy_from_slice(&value.id.to_le_bytes());
                bytes[offset + 8..offset + 12].copy_from_slice(&value.generation.to_le_bytes());
            }
            _ => {}
        }
    }
    bytes
}
