+#[derive(Clone, Debug, Default)]
+pub struct UiRepeatStore {
+    frames: BTreeMap<String, UiRepeatFrame>,
+}
+
+#[derive(Clone, Debug, PartialEq)]
+pub struct UiRepeatApplyResult {
+    pub accepted_rows: u32,
+    pub overflow_rows: u32,
