impl GpuUiProgramBackend {
    pub fn new(renderer_epoch: u64) -> Self {
        Self {
            renderer_epoch,
            buffers: None,
            staged: None,
            active: None,
            frame_sequence: 0,
            diagnostics: Vec::new(),
            last_timing: zero_timing(),
            last_readback: None,
