                    "ui_gpu_cpu_layout_mismatch",
                    "GPU sampled logical bounds differ from CPU output",
                    Some(cpu_layout.node_key.clone()),
                    None,
                    cpu.program_revision.revision,
                ));
            }
        }
        differences
    }

