impl StablePath {
    fn parse(value: &str, source_span: &NuiSourceSpan) -> FlowResult<Self> {
        let segments = value
            .trim_matches('/')
            .split('/')
            .filter(|segment| !segment.is_empty())
            .map(str::to_owned)
            .collect::<Vec<_>>();
        if segments.is_empty()
            || segments.iter().any(|segment| !valid_key(segment) || segment.bytes().all(|b| b.is_ascii_digit()))
