    pub fn dirty_slots(&self) -> Vec<String> {
        let mut slots = self.dirty_slots.iter().cloned().collect::<Vec<_>>();
        slots.sort();
        slots
    }
    pub fn take_dirty_slots(&mut self) -> Vec<String> {
        let slots = self.dirty_slots();
        self.dirty_slots.clear();
        slots
    }
    pub fn apply(
