    #[test]
    fn drag_boundary_offsets_clamp_to_parent_or_surface_and_allow_free_motion() {
        let source = UiBounds { x: 20.0, y: 30.0, width: 40.0, height: 20.0 };
        let parent = UiBounds { x: 10.0, y: 20.0, width: 100.0, height: 80.0 };
        let surface = UiBounds { x: 0.0, y: 0.0, width: 128.0, height: 96.0 };
