        ];
        renderer.sampled = vec![source, target_a, target_b];
        let fragment_id = neon_ui_schema::UiFragmentId("fixture".into());
        let intent = UiIntent::Invoke { action: "test.drop".into(), params: serde_json::json!({}) };
        let fragments = HashMap::from([(fragment_id.clone(), UiFragment {
            fragment_id: fragment_id.clone(),
            revision: Revision(1),
            root: node(),
            effects: vec![
                neon_ui_schema::UiEffect::DragBinding { binding: UiDragBinding {
                    key: "card-drag".into(), source_node_id: UiNodeId("source".into()), axis: UiDragAxis::Both, snap: 0.0, threshold: 1.0, boundary: UiDragBoundary::Free,
                } },
                neon_ui_schema::UiEffect::DropBinding { binding: neon_ui_schema::UiDropBinding {
                    key: "drop-a".into(), target_node_id: UiNodeId("target-a".into()), accepts_drag_key: "card-drag".into(), placement: UiDropPlacement::Into, presentation_template_key: None, intent: intent.clone(),
