    fn resolve_drop_target(&self, fragments: &HashMap<neon_ui_schema::UiFragmentId, UiFragment>, active: &RendererDrag, pointer: [f32; 2]) -> Option<UiResolvedDragDrop> {
        self.plan.iter().enumerate().rev().find_map(|(index, node)| {
            if node.id == active.source_path || node.id.starts_with(&(active.source_path.clone() + "/")) || !contains(self.sampled[index].bounds, pointer) || !contains(self.sampled[index].clip, pointer) { return None; }
            let (fragment_id, node_id) = fragments.iter().find_map(|(id, _)| {
                node.id.strip_prefix(&(id.0.clone() + "/")).map(|node_id| (id, node_id))
            })?;
            let fragment = fragments.get(fragment_id)?;
            fragment.effects.iter().rev().find_map(|effect| {
                let neon_ui_schema::UiEffect::DropBinding { binding } = effect else { return None; };
                (binding.target_node_id.0 == node_id && binding.accepts_drag_key == active.binding.key).then(|| UiResolvedDragDrop { fragment: active.fragment.clone(), intent: binding.intent.clone(), source_key: active.binding.source_node_id.0.clone(), target_key: binding.target_node_id.0.clone(), placement: binding.placement, presentation_template_key: binding.presentation_template_key.clone() })
            })
        })
    }

    fn drag_offset_for_node(
        &self,
        index: usize,
        plan_index: &HashMap<&str, usize>,
    ) -> Option<[f32; 2]> {
        let mut current = Some(index);
        while let Some(node_index) = current {
            let node = &self.plan[node_index];
            if let Some(offset) = self.drag_offsets.get(&node.id) {
                return Some(*offset);
            }
            current = node
                .parent_id
                .as_deref()
                .and_then(|parent| plan_index.get(parent).copied());
        }
        None
    }

