}

fn attach(
    mut child: NodeBuild,
    stack: &mut Vec<(usize, NodeBuild)>,
    root: &mut Option<NodeBuild>,
    line: u32,
) -> FlowResult<()> {
    if let Some((_, parent)) = stack.last_mut() {
        parent.node.children.push(child.node);
        Ok(())
    } else if root.is_none() {
        *root = Some(child);
        Ok(())
    } else {
        Err(error(
            "nui_flow_multiple_roots",
            "Flow permits one root surface",
            line,
            1,
        ))
    }
