pub fn lower_nui_flow(document: &NuiFlowDocument) -> UiIrDocument {
    document.ir.clone()
}

/// Lowers Flow's declarative interaction vocabulary into the renderer-neutral
/// fragment effect contract. Pointer capture and preview remain WGPU-local.
pub fn lower_nui_flow_effects(document: &NuiFlowDocument) -> Vec<UiEffect> {
    let mut effects = document.ir.events.iter().map(|event| UiEffect::BoundSemanticIntent {
        node_id: UiNodeId(event.node_key.clone()),
        intent: UiIntent::Invoke { action: event.intent.clone(), params: json!({}) },
    }).collect::<Vec<_>>();
    effects.extend(document.drags.iter().map(|drag| UiEffect::DragBinding {
        binding: UiDragBinding {
            key: drag.key.clone(), source_node_id: UiNodeId(drag.source_node_key.clone()),
            axis: match drag.axis { NuiFlowDragAxis::Horizontal => UiDragAxis::Horizontal, NuiFlowDragAxis::Vertical => UiDragAxis::Vertical, NuiFlowDragAxis::Both => UiDragAxis::Both },
            snap: drag.snap, threshold: drag.threshold, boundary: drag.boundary,
        },
    }));
    effects.extend(document.drops.iter().map(|drop| UiEffect::DropBinding {
        binding: UiDropBinding {
            key: drop.key.clone(), target_node_id: UiNodeId(drop.target_node_key.clone()),
            accepts_drag_key: drop.accepts_drag_key.clone(),
            placement: drop.placement,
            presentation_template_key: drop.presentation_template_key.clone(),
            intent: UiIntent::Invoke { action: drop.emit_intent.clone(), params: json!({}) },
        },
    }));
    effects
}

/// Compiles Flow through the same portable IR compiler and restores the exact
/// authoring spans on program/debug records. No Flow-specific evaluator exists.
pub fn compile_nui_flow_program(
    document: &NuiFlowDocument,
    revision: UiProgramRevision,
) -> Result<UiProgram, crate::UiProgramCompileError> {
    let mut program = crate::compile_ui_program(&document.ir, revision, &document.input_schema)?;
    for node in &mut program.nodes {
        if let Some(span) = document.source_map.get(&node.key) {
            let source_span = UiSourceSpan {
            resident_font: None,
            last_panel_instance_count: 0,
            pointer_visual_dirty: false,
            editing: UiTextEditingState::default(),
            drag: None,
            drag_offsets: HashMap::new(),
        }
    }

    pub(crate) fn draw_hit_id<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        pass: &mut wgpu::RenderPass<'a>,
        fragments: &HashMap<neon_ui_schema::UiFragmentId, UiFragment>,
        viewport_size: [u32; 2],
        _time_seconds: f32,
    ) {
        pass.set_pipeline(&self.hit_clear_pipeline);
        pass.draw(0..3, 0..1);
        let declarations = collect_hit_declarations(fragments);
        self.hit_bindings.clear();
        let mut instances = Vec::new();
        for (node_path, _, visual, _) in flatten_fragments(fragments, self.resident_font.as_ref()) {
            if !matches!(visual.kind, UiNodeKind::Button | UiNodeKind::TextInput)
                || !visual.enabled
                || visual.style.opacity <= 0.0
            {
                continue;
            }
            let hit_id = instances.len() as u32 + 1;
            if let Some(mut binding) = declarations.get(&node_path).cloned() {
                if visual.kind == UiNodeKind::TextInput {
                    binding.text_input = Some(UiTextInputBinding {
                        node_path: node_path.clone(),
                        max_length: 256,
                        bounds: visual.bounds,
                    });
                }
                self.hit_bindings.insert(hit_id, binding);
            }
            instances.push(UiHitInstance {
                rect: [
                    visual.bounds.x,
                    visual.bounds.y,
                    visual.bounds.width,
                    visual.bounds.height,
                ],
                params: [
                    visual.style.border_width,
                    visual.style.corner_radius,
                    visual.style.opacity,
                    visual.clip_radius,
                ],
                hit_id,
                _pad: [0; 3],
                clip: [
                    visual.clip.x,
                    visual.clip.y,
                    visual.clip.x + visual.clip.width,
                    visual.clip.y + visual.clip.height,
                ],
            });
        }
        if instances.is_empty() {
            return;
        }
        if instances.len() > self.hit_capacity {
            self.hit_capacity = instances.len().next_power_of_two();
            self.hit_buffer = create_hit_buffer(device, self.hit_capacity);
        }
        queue.write_buffer(&self.hit_buffer, 0, bytemuck::cast_slice(&instances));
        queue.write_buffer(
            &self.view_buffer,
            0,
            bytemuck::bytes_of(&UiView {
                viewport: [
                    viewport_size[0].max(1) as f32,
                    viewport_size[1].max(1) as f32,
                ],
                _pad: [0.0; 2],
            }),
        );
        pass.set_pipeline(&self.hit_pipeline);
        pass.set_bind_group(0, &self.view_bind_group, &[]);
        pass.set_vertex_buffer(0, self.hit_buffer.slice(..));
        pass.draw(0..6, 0..instances.len() as u32);
    }

    pub(crate) fn enqueue_hit_readback(
        &mut self,
        encoder: &mut wgpu::CommandEncoder,
        target: &wgpu::Texture,
        pixel: [u32; 2],
    ) -> Option<usize> {
        self.hit_readbacks.enqueue(encoder, target, pixel)
    }

    pub(crate) fn try_complete_hit_readback(
        &mut self,
        slot: usize,
    ) -> Option<Result<u32, wgpu::BufferAsyncError>> {
        self.hit_readbacks.try_complete(slot)
    }

    pub(crate) fn begin_hit_readback_mapping(&mut self, slot: usize) -> bool {
        self.hit_readbacks.begin_mapping(slot)
    }

    pub(crate) fn hit_binding(&self, hit_id: u32) -> Option<UiHitBinding> {
        self.hit_bindings.get(&hit_id).cloned()
    }

    /// Text inputs must focus on the first pointer press, before asynchronous GPU hit readback.
    pub(crate) fn text_input_at_pointer(&self) -> Option<UiTextInputBinding> {
        let pointer = self.pointer_position?;
        self.hit_bindings
            .values()
            .filter_map(|binding| binding.text_input.as_ref())
            .find(|input| contains(input.bounds, pointer))
            .cloned()
    }

    pub fn set_pointer_position(&mut self, position: [f32; 2]) {
        self.pointer_position = Some(position);
        self.pointer_visual_dirty = true;
    }

    pub(crate) fn pointer_position(&self) -> Option<[f32; 2]> {
        self.pointer_position
    }
}

fn flatten_fragments(
    fragments: &HashMap<neon_ui_schema::UiFragmentId, UiFragment>,
    font: Option<&ResidentFont>,
) -> Vec<(String, Option<String>, UiVisual, Option<UiTransition>)> {
    let mut ordered = fragments.values().collect::<Vec<_>>();
    ordered.sort_by(|left, right| left.fragment_id.0.cmp(&right.fragment_id.0));
    let mut result = Vec::new();
    for fragment in ordered {
        flatten_node(
            &mut result,
            &fragment.fragment_id.0,
            &fragment.root,
            [0.0, 0.0],
            None,
            None,
            None,
            font,
            None,
        );
    }
    result
}

fn collect_hit_declarations(
    fragments: &HashMap<neon_ui_schema::UiFragmentId, UiFragment>,
) -> HashMap<String, UiHitBinding> {
    let mut declarations = HashMap::new();
    for fragment in fragments.values() {
        for effect in &fragment.effects {
            if let neon_ui_schema::UiEffect::BoundSemanticIntent { node_id, intent } = effect {
                declarations.insert(
                    format!("{}/{}", fragment.fragment_id.0, node_id.0),
                    UiHitBinding {
                        fragment: UiFragmentRevision {
                            id: fragment.fragment_id.clone(),
                            revision: fragment.revision,
                        },
                        intent: Some(intent.clone()),
                        text_input: None,
                    },
                );
            }
        }
    }
    declarations
}

