impl UiFragment {
    pub fn validate(&self) -> Result<(), UiSchemaError> {
        if self.fragment_id.0.trim().is_empty() {
            return Err(UiSchemaError::EmptyFragmentId);
        }
        self.root.validate()?;
        for effect in &self.effects {
            effect.validate()?;
        }
        let mut nodes = std::collections::HashSet::new();
        fn collect(node: &UiNode, nodes: &mut std::collections::HashSet<String>) {
            nodes.insert(node.node_id.0.clone());
            for child in &node.children { collect(child, nodes); }
        }
        collect(&self.root, &mut nodes);
        let drags = self.effects.iter().filter_map(|effect| match effect { UiEffect::DragBinding { binding } => Some(binding), _ => None }).collect::<Vec<_>>();
        for effect in &self.effects {
            match effect {
                UiEffect::DragBinding { binding } if !nodes.contains(&binding.source_node_id.0) => return Err(UiSchemaError::InvalidProgramEvent),
                UiEffect::DropBinding { binding } if !nodes.contains(&binding.target_node_id.0) || !drags.iter().any(|drag| drag.key == binding.accepts_drag_key) => return Err(UiSchemaError::InvalidProgramEvent),
                _ => {}
            }
        }
        Ok(())
    }
}

impl UiNode {
    fn validate(&self) -> Result<(), UiSchemaError> {
        if self.node_id.0.trim().is_empty() {
            return Err(UiSchemaError::EmptyNodeId);
        }
        if !self.bounds.is_valid() {
            return Err(UiSchemaError::InvalidBounds);
        }
        if !self.style.is_valid() {
            return Err(UiSchemaError::InvalidStyle);
        }
        if self.kind == UiNodeKind::Image && self.image.is_none() {
            return Err(UiSchemaError::MissingImageAsset);
        }
        if self.kind == UiNodeKind::RenderSurface && self.surface.is_none() {
            return Err(UiSchemaError::MissingRenderSurfaceRef);
        }
        if self
            .surface
            .as_ref()
            .is_some_and(|surface| surface.target_id.trim().is_empty())
        {
            return Err(UiSchemaError::InvalidRenderSurfaceRef);
        }
        if self.text.as_ref().is_some_and(|text| !text.is_valid()) { return Err(UiSchemaError::InvalidText); }
        if self.layout.is_some_and(|layout| !layout.is_valid()) { return Err(UiSchemaError::InvalidLayout); }
        let mut child_ids = std::collections::HashSet::new();
        for child in &self.children {
            if !child_ids.insert(child.node_id.0.as_str()) { return Err(UiSchemaError::DuplicateNodeId); }
        }
        if let Some(transition) = &self.enter_transition
            && !transition.is_valid()
        {
            return Err(UiSchemaError::InvalidTransition);
        }
        for child in &self.children {
            child.validate()?;
        }
        Ok(())
    }
}

impl UiBounds {
    pub fn is_valid(self) -> bool {
        self.x.is_finite()
            && self.y.is_finite()
            && self.width.is_finite()
            && self.height.is_finite()
            && self.width >= 0.0
            && self.height >= 0.0
    }
}

impl UiLayout {
    fn is_valid(self) -> bool {
        self.padding.iter().chain(self.margin.iter()).all(|value| value.is_finite() && *value >= 0.0)
            && self.gap.is_finite() && self.gap >= 0.0 && self.scroll_offset.iter().all(|value| value.is_finite())
            && self.flex_basis.is_none_or(|value| value.is_finite() && value >= 0.0)
            && self.flex_grow.is_finite() && self.flex_grow >= 0.0
            && self.flex_shrink.is_finite() && self.flex_shrink >= 0.0
            && self.min_size.is_none_or(|size| size.iter().all(|value| value.is_finite() && *value >= 0.0))
            && self.max_size.is_none_or(|size| size.iter().all(|value| value.is_finite() && *value >= 0.0))
            && self.preferred_size.is_none_or(|size| size.iter().all(|value| value.is_finite() && *value >= 0.0))
    }
}

impl UiStyle {
    pub fn is_default(value: &Self) -> bool {
        *value == Self::default()
    }

    pub fn is_valid(self) -> bool {
        self.background_color.iter().all(|value| value.is_finite())
            && self.border_color.iter().all(|value| value.is_finite())
            && self.border_width.is_finite()
            && self.corner_radius.is_finite()
            && self.opacity.is_finite()
            && self.border_width >= 0.0
            && self.corner_radius >= 0.0
            && (0.0..=1.0).contains(&self.opacity)
    }
}

impl UiTransition {
    pub fn is_valid(&self) -> bool {
        self.duration_ms > 0 && self.from.is_valid()
    }
}

impl UiTransitionState {
    fn is_valid(self) -> bool {
        self.bounds.is_none_or(UiBounds::is_valid)
            && self
    let values = tokenize(text, line)?;
    let parts = values.iter().map(String::as_str).collect::<Vec<_>>();
    if parts.len() < 2 {
        return Err(error(
            "nui_flow_invalid_node",
            "node syntax is: <component> <stable-key> [tokens]",
            line,
            1,
        ));
    }
    let kind = match parts[0] {
        "surface" | "panel" | "scroll" | "overlay" | "branch" | "repeat" | "template" => {
            UiNodeKind::Panel
        }
        "text" => UiNodeKind::Label,
        "button" => UiNodeKind::Button,
        "input" => UiNodeKind::TextInput,
        "image" => UiNodeKind::Image,
        "render" => UiNodeKind::RenderSurface,
        _ => {
            return Err(error(
                "nui_flow_unknown_component",
                "component is outside the closed Flow vocabulary",
                line,
                1,
            ))
        }
    };
    if !valid_key(parts[1]) {
        return Err(error(
            "nui_flow_invalid_key",
            "node keys use letters, digits, '.', '_' and '-'",
            line,
            1,
        ));
    }
    let is_render_surface = kind == UiNodeKind::RenderSurface;
    let mut node = UiNode {
        node_id: UiNodeId(parts[1].into()),
        kind,
        bounds: UiBounds {
            x: 0.0,
            y: 0.0,
            width: 0.0,
            height: 0.0,
        },
        layout: Some(UiLayout::default()),
        visible: true,
        enabled: true,
        text_key: None,
        text: None,
        image: None,
        surface: None,
        style: UiStyle::default(),
        enter_transition: None,
        children: Vec::new(),
    };
    if is_render_surface {
        node.surface = Some(RenderSurfaceRef {
            target_id: format!("render.{}", node.node_id.0),
        });
    }
    if parts[0] == "scroll" {
        node.layout.as_mut().expect("Flow nodes have layout").clip = UiClipPolicy::Scroll;
    }
    let mut bindings = Vec::new();
    let mut intents = Vec::new();
    let mut branch_predicate = None;
    let mut template = None;
    let mut used = HashSet::new();
    let mut index = 2;
    while index < parts.len() {
        let token = parts[index];
        if !used.insert(token) && !matches!(token, "row" | "column" | "overlay") {
            return Err(error(
                "nui_flow_duplicate_attribute",
                "attribute appears more than once",
                line,
                1,
            ));
        }
        match token {
            "row" => node.layout.as_mut().unwrap().mode = UiLayoutMode::Row,
            "column" => node.layout.as_mut().unwrap().mode = UiLayoutMode::Column,
            "overlay" => node.layout.as_mut().unwrap().mode = UiLayoutMode::Overlay,
            "w" | "h" | "minw" | "maxw" | "grow" | "shrink" | "basis" | "gap" | "pad" | "fill"
            | "line" | "ink" | "value" | "enabled" | "visible" | "event" | "token" | "align" | "clip"
            | "justify" => {
                let value = *parts.get(index + 1).ok_or_else(|| {
                    error(
                        "nui_flow_missing_value",
                        "attribute requires a value",
                        line,
                        1,
                    )
                })?;
                index += 1;
                parse_attribute(&mut node, &mut bindings, &mut intents, token, value, line)?;
            }
            "when" if parts[0] == "branch" => {
                let value = *parts.get(index + 1).ok_or_else(|| error("nui_flow_missing_value", "when requires a direct input predicate", line, 1))?;
                index += 1;
                branch_predicate = Some(parse_branch_predicate(value, line)?);
            }
            "in" if parts[0] == "branch" => {
                let value = *parts.get(index + 1).ok_or_else(|| error("nui_flow_missing_value", "in requires machine.state", line, 1))?;
                index += 1;
                branch_predicate = Some(parse_machine_state_predicate(value, line)?);
            }
            "capacity" if matches!(parts[0], "repeat" | "template") => {
                let value = *parts.get(index + 1).ok_or_else(|| error("nui_flow_missing_value", "capacity requires a positive bound", line, 1))?;
                index += 1;
                let capacity = parse_u64(value, line, "capacity")? as u32;
                if capacity == 0 { return Err(error("ui_program_invalid_branch_template", "template capacity must be positive", line, 1)); }
                template = Some((capacity, BTreeMap::from([("row_key".into(), UiInputKind::U32)]), "row_key".into(), false));
            }
            "key" if matches!(parts[0], "repeat" | "template") => {
                let value = *parts.get(index + 1).ok_or_else(|| error("nui_flow_missing_value", "key requires a row key field", line, 1))?;
                index += 1;
                let current = template.get_or_insert((1, BTreeMap::from([("row_key".into(), UiInputKind::U32)]), String::new(), false));
                let prior_key = current.2.clone();
                current.1.remove(&prior_key);
                current.1.insert(value.into(), UiInputKind::U32);
                current.2 = value.into();
            }
            "overflow_summary" if matches!(parts[0], "repeat" | "template") => {
                let current = template.get_or_insert((1, BTreeMap::from([("row_key".into(), UiInputKind::U32)]), "row_key".into(), false));
                current.3 = true;
            }
            _ => {
                return Err(error(
                    "nui_flow_unknown_attribute",
                    "unknown Flow layout, style, binding, or event token",
                    line,
                    1,
                ))
            }
        }
        index += 1;
    }
    if parts[0] == "branch" && branch_predicate.is_none() { return Err(error("ui_program_invalid_branch_template", "branch requires `when` or `in machine.state`", line, 1)); }
    if matches!(parts[0], "repeat" | "template") {
        let Some(spec) = &template else { return Err(error("ui_program_invalid_branch_template", "repeat/template requires a finite capacity", line, 1)); };
        if spec.2.trim().is_empty() { return Err(error("ui_program_invalid_branch_template", "repeat/template requires a stable key field", line, 1)); }
    }
    Ok(NodeBuild { node, bindings, intents, branch_predicate, template })
}

fn parse_branch_predicate(value: &str, line: u32) -> FlowResult<UiBranchPredicate> {
    let value = value.strip_prefix('$').ok_or_else(|| error("ui_program_invalid_branch_template", "branch predicate must reference one direct input", line, 1))?;
    if let Some(input_key) = value.strip_prefix('!') {
        return Ok(UiBranchPredicate::Bool { input_key: input_key.into(), expected: false });
    }
    if let Some((input_key, variant)) = value.split_once('=') {
        if input_key.is_empty() || variant.is_empty() { return Err(error("ui_program_invalid_branch_template", "enum branch predicate requires input and variant", line, 1)); }
        return Ok(UiBranchPredicate::EnumEquals { input_key: input_key.into(), variant: variant.into() });
    }
    Ok(UiBranchPredicate::Bool { input_key: value.into(), expected: true })
}

fn parse_machine_state_predicate(value: &str, line: u32) -> FlowResult<UiBranchPredicate> {
    let Some((machine_key, state)) = value.rsplit_once('.') else {
        return Err(error("nui_flow_invalid_state_machine", "branch in requires machine.state", line, 1));
    };
    if !valid_key(machine_key) || !valid_key(state) {
        return Err(error("nui_flow_invalid_state_machine", "machine and state keys are invalid", line, 1));
    }
    Ok(UiBranchPredicate::MachineState { machine_key: machine_key.into(), state: state.into() })
}

fn parse_attribute(
    node: &mut UiNode,
    bindings: &mut Vec<(UiBoundProperty, String)>,
    intents: &mut Vec<String>,
    key: &str,
    value: &str,
    line: u32,
) -> FlowResult<()> {
    let layout = node.layout.as_mut().expect("Flow nodes have layout");
    let mut direct_binding = |property| {
        value
            .strip_prefix('$')
            .map(|input| bindings.push((property, input.into())))
    };
    match key {
        "w" => node.bounds.width = number(value, line)?,
        "h" => node.bounds.height = number(value, line)?,
        "minw" => {
            layout.min_size = Some([number(value, line)?, layout.min_size.map_or(0.0, |v| v[1])])
        }
        "maxw" => {
            layout.max_size = Some([
                number(value, line)?,
                layout.max_size.map_or(f32::MAX, |v| v[1]),
            ])
        }
        "grow" => layout.flex_grow = number(value, line)?,
        "shrink" => layout.flex_shrink = number(value, line)?,
        "basis" => layout.flex_basis = Some(number(value, line)?),
        "gap" => layout.gap = number(value, line)?,
        "pad" => layout.padding = [number(value, line)?; 4],
        "fill" => {
            node.style.background_color = color(value, line)?;
        }
        "line" => {
            node.style.border_color = color(value, line)?;
        }
        "ink" => {
            if !value.starts_with("token:") {
                return Err(error(
                    "nui_flow_invalid_style",
                    "ink requires a token:<name> reference",
                    line,
                    1,
                ));
            }
        }
        "token" => {
            if !value.starts_with("token:") {
                return Err(error(
                    "nui_flow_invalid_style",
                    "token requires token:<name>",
                    line,
                    1,
                ));
            }
        }
        "align" => layout.align_items = alignment(value, line)?,
        "clip" => layout.clip = match value {
            "none" => UiClipPolicy::None,
                compilation_options: Default::default(),
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview_mask: None,
            cache: None,
        });
        Self {
            pipeline,
            view_buffer,
            view_bind_group,
            instance_buffer: create_instance_buffer(device, 1),
            instance_capacity: 1,
            plan_revisions: HashMap::new(),
            plan: Vec::new(),
            sampled: Vec::new(),
            instances: Vec::new(),
            dirty_instances: Vec::new(),
            viewport_size: [0, 0],
            current: HashMap::new(),
            active: HashMap::new(),
            pointer_position: None,
            pressed_until_seconds: 0.0,
            hit_pipeline,
            hit_clear_pipeline,
            hit_buffer: create_hit_buffer(device, 1),
            hit_capacity: 1,
            hit_readbacks: HitReadbackRing::new(device, 3),
            hit_bindings: HashMap::new(),
            image_pipeline,
            image_buffer: create_image_buffer(device, 1),
            image_capacity: 1,
            resident_images: HashMap::new(),
            resident_render_surfaces: HashMap::new(),
            image_texture_layout,
            text_pipeline,
            text_buffer: create_text_buffer(device, 1),
            text_capacity: 1,
            _text_texture_layout: text_texture_layout,
            resident_font: None,
            last_panel_instance_count: 0,
            pointer_visual_dirty: false,
            editing: UiTextEditingState::default(),
            drag: None,
            drag_offsets: HashMap::new(),
        }
    }

    pub(crate) fn draw_hit_id<'a>(
        &'a mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        pass: &mut wgpu::RenderPass<'a>,
        fragments: &HashMap<neon_ui_schema::UiFragmentId, UiFragment>,
        viewport_size: [u32; 2],
        _time_seconds: f32,
    ) {
        pass.set_pipeline(&self.hit_clear_pipeline);
        pass.draw(0..3, 0..1);
        let declarations = collect_hit_declarations(fragments);
        self.hit_bindings.clear();
        let mut instances = Vec::new();
        for (node_path, _, visual, _) in flatten_fragments(fragments, self.resident_font.as_ref()) {
            if !matches!(visual.kind, UiNodeKind::Button | UiNodeKind::TextInput)
                || !visual.enabled
                || visual.style.opacity <= 0.0
            {
                continue;
            }
            let hit_id = instances.len() as u32 + 1;
            if let Some(mut binding) = declarations.get(&node_path).cloned() {
                if visual.kind == UiNodeKind::TextInput {
                    binding.text_input = Some(UiTextInputBinding {
                        node_path: node_path.clone(),
                        max_length: 256,
                        bounds: visual.bounds,
                    });
                }
                self.hit_bindings.insert(hit_id, binding);
            }
            instances.push(UiHitInstance {
                rect: [
                    visual.bounds.x,
                    visual.bounds.y,
                    visual.bounds.width,
                    visual.bounds.height,
                ],
                params: [
                    visual.style.border_width,
                    visual.style.corner_radius,
                    visual.style.opacity,
                    visual.clip_radius,
                ],
                hit_id,
                _pad: [0; 3],
                clip: [
                    visual.clip.x,
                    visual.clip.y,
                    visual.clip.x + visual.clip.width,
                    visual.clip.y + visual.clip.height,
                ],
            });
        }
        if instances.is_empty() {
            return;
        }
        if instances.len() > self.hit_capacity {
            self.hit_capacity = instances.len().next_power_of_two();
            self.hit_buffer = create_hit_buffer(device, self.hit_capacity);
        }
        queue.write_buffer(&self.hit_buffer, 0, bytemuck::cast_slice(&instances));
        queue.write_buffer(
            &self.view_buffer,
            0,
            bytemuck::bytes_of(&UiView {
                viewport: [
                    viewport_size[0].max(1) as f32,
                    viewport_size[1].max(1) as f32,
                ],
                _pad: [0.0; 2],
            }),
        );
        pass.set_pipeline(&self.hit_pipeline);
        pass.set_bind_group(0, &self.view_bind_group, &[]);
        pass.set_vertex_buffer(0, self.hit_buffer.slice(..));
        pass.draw(0..6, 0..instances.len() as u32);
    }

    pub(crate) fn enqueue_hit_readback(
        &mut self,
        encoder: &mut wgpu::CommandEncoder,
        target: &wgpu::Texture,
        pixel: [u32; 2],
    ) -> Option<usize> {
        self.hit_readbacks.enqueue(encoder, target, pixel)
    }

    pub(crate) fn try_complete_hit_readback(
        &mut self,
        slot: usize,
    ) -> Option<Result<u32, wgpu::BufferAsyncError>> {
        self.hit_readbacks.try_complete(slot)
    }

    pub(crate) fn begin_hit_readback_mapping(&mut self, slot: usize) -> bool {
