    fn validate(&self) -> Result<(), UiSchemaError> {
        match self {
            Self::SemanticAction { action } if action.trim().is_empty() => {
                Err(UiSchemaError::EmptyAction)
            }
            Self::SemanticAction { .. } => Ok(()),
            Self::SemanticIntent { intent } => intent.validate(),
