                .register_literal(Revision(0), "Terrain".into())
                .unwrap_err()
                .code,
            ERROR_UI_PROGRAM_TEXT_REGISTRY_STALE_REVISION
        );
        assert_eq!(
            registry
                .register_literal(registry.revision(), "Terrain".into())
                .unwrap(),
            literal
        );

        let program = UiProgramRevision {
            program_id: "surface.editor".into(),
