    #[test]
    fn compiler_is_deterministic_and_cpu_evaluator_traces_direct_bindings() {
        let document = compiler_document();
        let schema = compiler_schema(false);
        let revision = compiler_program_revision();
        let first = compile_ui_program(&document, revision.clone(), &schema).unwrap();
        let second = compile_ui_program(&document, revision.clone(), &schema).unwrap();
        assert_eq!(first.layout_hash, second.layout_hash);
        assert_eq!(
            first.nodes.iter().map(|node| &node.key).collect::<Vec<_>>(),
            vec!["root", "commit"]
        );
        assert_eq!(first.dependency_index.input_to_bindings["visible"], vec![0]);
        let store = UiInputStore::activate(revision, schema).unwrap();
        let output = evaluate_ui_program(
            &first,
            &store.snapshot(),
            UiCpuViewport {
                logical_bounds: UiBounds {
                    x: 0.0,
                    y: 0.0,
                    width: 100.0,
                    height: 50.0,
                },
                revision: Revision(1),
            },
            &UiLocalPresentationState {
                revision: Revision(0),
                machine_states: BTreeMap::new(),
                drag_offsets: BTreeMap::new(),
            },
        );
        assert!(
            !output
                .nodes
                .iter()
                .find(|node| node.node_key == "commit")
                .unwrap()
                .visible
        );
        assert_eq!(output.semantic_targets[0].node_key, "commit");
    }

    #[test]
    fn program_semantic_events_require_current_enabled_declarations_and_are_idempotent() {
        use neon_ui_schema::{UiProgramSemanticEvent, UiProgramSemanticEventKind, UiSemanticInteractionMetadata};
        let mut document = compiler_document();
        document.events[0].literal_payload.insert("tool".into(), UiSemanticPayloadValue::Enum { value: "water".into() });
        let revision = compiler_program_revision();
        let program = compile_ui_program(&document, revision.clone(), &compiler_schema(true)).unwrap();
        let inputs = UiInputStore::activate(revision.clone(), compiler_schema(true)).unwrap().snapshot();
        let mut router = UiProgramSemanticEventRouter::new(program, inputs.clone(), 7);
        let event = UiProgramSemanticEvent {
            event_id: "event-1".into(), kind: UiProgramSemanticEventKind::Activate,
            intent: "terrain.commit".into(), source_node_key: "commit".into(),
            payload: BTreeMap::from([("tool".into(), UiSemanticPayloadValue::Enum { value: "water".into() })]),
            program_revision: revision, input_revision: inputs.input_revision,
            request_id: "request-1".into(), idempotency_key: "key-1".into(),
            interaction: UiSemanticInteractionMetadata { interaction_id: "interaction-1".into(), sequence: 1, renderer_epoch: 7 },
        };
        assert_eq!(router.validate(&event).status, UiProgramSemanticEventStatus::Accepted);
        assert_eq!(router.validate(&event).status, UiProgramSemanticEventStatus::Duplicate);
        let mut stale = event;
        stale.idempotency_key = "key-2".into();
        stale.input_revision = Revision(99);
        assert_eq!(router.validate(&stale).code.as_deref(), Some(ERROR_UI_PROGRAM_EVENT_STALE_REVISION));
        assert_eq!(router.trace().len(), 3);
    }

    #[test]
    fn compiler_rejects_invalid_binding_and_budget_overflow() {
        let mut document = compiler_document();
        document.bindings[0].property = UiBoundProperty::Opacity;
        assert_eq!(
            compile_ui_program(
                &document,
                compiler_program_revision(),
                &compiler_schema(true)
            )
            .unwrap_err()
            .code,
            "ui_program_input_type_mismatch"
        );
        let mut document = compiler_document();
        document.resource_budget.max_nodes = 1;
        assert_eq!(
            compile_ui_program(
                &document,
                compiler_program_revision(),
                &compiler_schema(true)
            )
            .unwrap_err()
            .code,
            "ui_program_capacity_overflow"
        );
    }

    #[test]
    fn compiler_rejects_duplicate_keys_and_hashes_default_or_literal_changes() {
        let baseline = compile_ui_program(
            &compiler_document(),
            compiler_program_revision(),
            &compiler_schema(true),
        )
        .unwrap();
        let changed_default = compile_ui_program(
            &compiler_document(),
            compiler_program_revision(),
            &compiler_schema(false),
        )
        .unwrap();
        assert_ne!(baseline.layout_hash, changed_default.layout_hash);
        let mut changed_literal = compiler_document();
        changed_literal.root.text = Some(TextRef::Literal {
            value: "Resources".into(),
        });
        changed_literal.resource_budget.max_glyph_instances = 9;
        assert_ne!(
            baseline.layout_hash,
            compile_ui_program(
                &changed_literal,
                compiler_program_revision(),
                &compiler_schema(true)
            )
            .unwrap()
            .layout_hash
        );
        let mut duplicate = compiler_document();
        duplicate.root.children[0].children.push(UiNode {
            node_id: UiNodeId("root".into()),
            kind: UiNodeKind::Label,
            bounds: UiBounds {
                x: 0.0,
                y: 0.0,
                width: 1.0,
                height: 1.0,
            },
            layout: None,
            visible: true,
            enabled: true,
            text_key: None,
            text: None,
            image: None,
            surface: None,
            style: UiStyle::default(),
            enter_transition: None,
            children: Vec::new(),
        });
        assert_eq!(
            compile_ui_program(
                &duplicate,
                compiler_program_revision(),
                &compiler_schema(true)
            )
            .unwrap_err()
            .code,
            "ui_program_duplicate_node_key"
        );
        let mut invalid_schema = compiler_schema(true);
        invalid_schema.slots[0].default_value = UiInputValue::F32 { value: 1.0 };
        assert_eq!(
            compile_ui_program(
                &compiler_document(),
                compiler_program_revision(),
                &invalid_schema
            )
            .unwrap_err()
            .code,
            "ui_program_invalid_schema"
        );
    }
}

//! Canonical NUI Flow terrain-workbench fixture and headless scenario helpers.
//! Business values are supplied only through the typed input/repeat boundaries.

use std::collections::BTreeMap;

use neon_protocol::Revision;
use neon_ui_schema::{
    UiCpuViewport, UiInputChange, UiInputFrame, UiInputValue, UiProgramCapability,
    UiProgramCapabilityOwner, UiProgramCapabilityStatus, UiProgramRevision, UiRepeatFrame,
    UiRepeatRow, UiProgramResource, UiProgramResourceKind,
    UI_PROGRAM_BOUNDED_STRUCTURE_CAPABILITY_NAME, UI_PROGRAM_CAPABILITY_NAME,
    UI_PROGRAM_SCHEMA_VERSION, UI_PROGRAM_SEMANTIC_EVENT_CAPABILITY_NAME,
    UI_PROGRAM_TEXT_REGISTRY_CAPABILITY_NAME,
};

use crate::{compile_nui_flow_program, parse_nui_flow};

pub const TERRAIN_WORKBENCH_FLOW: &str = include_str!("../../../tests/fixtures/ui/terrain-workbench.nui");

pub fn terrain_workbench_program_revision() -> UiProgramRevision {
    UiProgramRevision {
        program_id: "surface.editor.terrain-workbench".into(), revision: Revision(1),
        schema_version: UI_PROGRAM_SCHEMA_VERSION,
        capabilities: [
            UI_PROGRAM_CAPABILITY_NAME,
            UI_PROGRAM_TEXT_REGISTRY_CAPABILITY_NAME,
            UI_PROGRAM_BOUNDED_STRUCTURE_CAPABILITY_NAME,
            UI_PROGRAM_SEMANTIC_EVENT_CAPABILITY_NAME,
        ].into_iter().map(|name| UiProgramCapability {
            name: name.into(), version: 1, owner: UiProgramCapabilityOwner::SharedContract,
            status: UiProgramCapabilityStatus::Supported,
        }).collect(),
    }
}

pub fn terrain_workbench_document() -> neon_ui_schema::NuiFlowDocument {
    let mut document = parse_nui_flow(TERRAIN_WORKBENCH_FLOW)
        .expect("checked-in terrain workbench Flow must validate");
    document.ir.resources.push(UiProgramResource {
        key: "terrain-render-surface".into(),
        kind: UiProgramResourceKind::RenderSurface,
        has_fallback: true,
    });
    document
}

pub fn terrain_workbench_program() -> neon_ui_schema::UiProgram {
    compile_nui_flow_program(&terrain_workbench_document(), terrain_workbench_program_revision())
        .expect("checked-in terrain workbench Flow must compile")
}

pub fn terrain_workbench_viewport(width: f32, height: f32, revision: u64) -> UiCpuViewport {
    UiCpuViewport {
        logical_bounds: neon_ui_schema::UiBounds { x: 0.0, y: 0.0, width, height },
        revision: Revision(revision),
    }
}

pub fn terrain_workbench_input_frame(expected_input_revision: Revision, request_id: &str, changes: Vec<UiInputChange>) -> UiInputFrame {
    UiInputFrame {
        program_revision: terrain_workbench_program_revision(), expected_input_revision,
        request_id: request_id.into(), idempotency_key: format!("workbench:{}", request_id), changes,
    }
}

pub fn terrain_workbench_material_rows(revision: u64, count: u32) -> UiRepeatFrame {
    UiRepeatFrame {
        template_key: "material-rows".into(), list_revision: Revision(revision),
        expected_program_revision: terrain_workbench_program_revision(),
        rows: (0..count).map(|index| UiRepeatRow {
            stable_row_key: format!("material-{}", index + 1),
            values: BTreeMap::from([("row_key".into(), UiInputValue::U32 { value: index + 1 })]),
            semantic_payload: BTreeMap::from([("material_ref".into(), format!("material:{}", index + 1))]),
        }).collect(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{apply_nui_ir_patch, evaluate_ui_program, parse_nui_flow_patch, UiInputStore, UiInputWriter, UiLocalPresentationState, UiRepeatStore, UiTextRegistry};
    use neon_ui_schema::{UiProgramSemanticEvent, UiProgramSemanticEventKind, UiProgramSemanticEventStatus, UiSemanticInteractionMetadata, UiTextSourceCategory};

    #[test]
    fn terrain_workbench_default_update_branch_repeat_and_patch_scenarios_are_headless() {
        let document = terrain_workbench_document();
        let program = terrain_workbench_program();
        let mut store = UiInputStore::activate(terrain_workbench_program_revision(), document.input_schema.clone()).unwrap();
        let defaults = evaluate_ui_program(&program, &store.snapshot(), terrain_workbench_viewport(1440.0, 900.0, 1), &UiLocalPresentationState::default());
        assert!(defaults.nodes.iter().any(|node| node.node_key == "terrain-render-surface"));
        assert!(defaults.nodes.iter().any(|node| node.node_key == "loading-state" && node.visible));

        let update = terrain_workbench_input_frame(Revision(0), "domain-ready", vec![
            UiInputChange { key: "workbench_state".into(), value: UiInputValue::Enum { value: "ready".into() } },
            UiInputChange { key: "can_commit".into(), value: UiInputValue::Bool { value: true } },
        ]);
        store.apply(UiInputWriter::External, update).unwrap();
        let ready = evaluate_ui_program(&program, &store.snapshot(), terrain_workbench_viewport(720.0, 900.0, 2), &UiLocalPresentationState::default());
        assert!(ready.nodes.iter().any(|node| node.node_key == "ready-state" && node.visible));
        assert!(ready.nodes.iter().any(|node| node.node_key == "loading-state" && !node.visible));

        let mut events = crate::UiProgramSemanticEventRouter::new(program.clone(), store.snapshot(), 7);
        let activate = UiProgramSemanticEvent {
            event_id: "tool-select".into(), kind: UiProgramSemanticEventKind::Activate,
            intent: "terrain.tool.select".into(), source_node_key: "tool-select".into(),
            payload: BTreeMap::new(), program_revision: terrain_workbench_program_revision(),
            input_revision: Revision(1), request_id: "tool-request".into(), idempotency_key: "tool-select-1".into(),
            interaction: UiSemanticInteractionMetadata { interaction_id: "pointer-capture-1".into(), sequence: 1, renderer_epoch: 7 },
        };
        assert_eq!(events.validate(&activate).status, UiProgramSemanticEventStatus::Accepted);
        let mut stale_event = activate;
        stale_event.event_id = "tool-select-stale".into();
        stale_event.idempotency_key = "tool-select-stale".into();
        stale_event.input_revision = Revision(0);
        assert_eq!(events.validate(&stale_event).status, UiProgramSemanticEventStatus::Rejected);

        let mut repeats = UiRepeatStore::default();
        let rows = repeats.apply(&program, terrain_workbench_material_rows(1, 9)).unwrap();
        assert_eq!((rows.accepted_rows, rows.overflow_rows), (8, 1));
        assert!(!rows.diagnostics.is_empty());

        let stale = terrain_workbench_input_frame(Revision(0), "stale", Vec::new());
        assert!(store.apply(UiInputWriter::External, stale).is_err());
        let patch = parse_nui_flow_patch("@ revision 1\n~ inspector visible false\n").unwrap();
        assert_eq!(apply_nui_ir_patch(&document.ir, &patch).unwrap().revision, Revision(2));
    }

    #[test]
    fn terrain_workbench_dynamic_text_uses_replacement_handles_not_frame_strings() {
        let document = terrain_workbench_document();
        let mut registry = UiTextRegistry::new("terrain-workbench", 8, 256).unwrap();
        let title = registry.insert_dynamic(Revision(0), "Terrain Alpha".into()).unwrap();
        let mut store = UiInputStore::activate(
            terrain_workbench_program_revision(), document.input_schema,
        ).unwrap();
        let update = terrain_workbench_input_frame(Revision(0), "title", vec![
            UiInputChange { key: "project_title".into(), value: UiInputValue::TextHandle { value: title } },
        ]);
        store.apply_with_text_registry(UiInputWriter::External, update, &registry).unwrap();
        registry.replace_dynamic(Revision(1), title, "Terrain Beta".into()).unwrap();
        assert_eq!(registry.handle_diagnostic(title).status, neon_ui_schema::UiTextHandleStatus::Ready);
        assert_eq!(registry.snapshot(true).records[0].category, UiTextSourceCategory::Dynamic);
    }
}

//! Headless authoring inspection, dry-run, and deterministic replay support.
//! It is intentionally built on the CPU program backend and never serializes
//! renderer handles, physical coordinates, or unapproved text contents.

use std::collections::BTreeMap;

use neon_protocol::Revision;
use neon_ui_schema::{
    UiCpuFrameOutput, UiCpuViewport, UiDebugBundle, UiDiagnostic, UiDiagnosticSeverity,
    UiInputFrame, UiInputSchema, UiIrDocument, UiIrOutlineEntry, UiIrOutlinePage, UiIrPatch,
    UiLayoutDiagnosticSnapshot, UiNodeInspection, UiPatchDryRun, UiProgram, UiProgramDescription,
    UiProgramRevision, UiResolvedInputs, UiTextHandle, UiTextHandleDiagnostic,
    UiTextHandleStatus, UiTextRegistryDebugSnapshot, UiProgramSemanticEvent,
};

use crate::{apply_nui_ir_patch, compile_ui_program, evaluate_ui_program, UiInputStore, UiInputWriter,
    UiLocalPresentationState, UiProgramSemanticEventRouter, UiRepeatStore, UiTextRegistry};

#[derive(Clone, Debug, PartialEq)]
pub struct UiReplayResult {
    pub frames: Vec<UiCpuFrameOutput>,
    pub diagnostics: Vec<UiDiagnostic>,
    pub matched_expected_frames: bool,
}

/// Runtime-owned state for the public debug methods. The domain is still
/// responsible for supplying frames; this facade only validates and explains.
pub struct UiDebugSession {
    document: UiIrDocument,
    program: UiProgram,
    inputs: UiInputStore,
    initial_inputs: UiResolvedInputs,
    text: UiTextRegistry,
    repeats: UiRepeatStore,
    events: UiProgramSemanticEventRouter,
    input_timeline: Vec<UiInputFrame>,
    repeat_timeline: Vec<neon_ui_schema::UiRepeatFrame>,
    event_timeline: Vec<UiProgramSemanticEvent>,
    viewport: UiCpuViewport,
    source_hash: String,
}

impl UiDebugSession {
    pub fn activate(document: UiIrDocument, revision: UiProgramRevision, schema: UiInputSchema,
        text: UiTextRegistry, viewport: UiCpuViewport, flow_source: &str, renderer_epoch: u64,
    ) -> Result<Self, String> {
        let program = compile_ui_program(&document, revision.clone(), &schema).map_err(|error| error.message)?;
        let inputs = UiInputStore::activate(revision, schema).map_err(|error| error.message.to_owned())?;
        let events = UiProgramSemanticEventRouter::new(program.clone(), inputs.snapshot(), renderer_epoch);
        let initial_inputs = inputs.snapshot();
        Ok(Self { document, program, inputs, initial_inputs, text, repeats: UiRepeatStore::default(), events,
            input_timeline: Vec::new(), repeat_timeline: Vec::new(), event_timeline: Vec::new(), viewport, source_hash: hash(flow_source) })
    }

    pub fn outline(&self, offset: u32, limit: u32) -> UiIrOutlinePage {
        let limit = limit.clamp(1, 256); let frame = self.frame();
        let entries = self.program.nodes.iter().skip(offset as usize).take(limit as usize).map(|node| {
            let template = self.program.node_templates.iter().find(|value| value.node_id.0 == node.key).expect("compiled template");
            let bindings = self.program.binding_records.iter().filter(|binding| binding.node_key == node.key)
                .map(|binding| format!("{}:{:?}", binding.input_key, binding.property)).collect();
            let branch_key = self.program.branch_records.iter().find(|branch| branch.node_range.contains(&node.key)).map(|branch| branch.branch_key.clone());
            let template_key = self.program.template_records.iter().find(|record| record.node_range.contains(&node.key)).map(|record| record.template_key.clone());
            UiIrOutlineEntry { node_key: node.key.clone(), parent_key: node.parent_key.clone(), kind: node.kind.clone(),
                static_properties: BTreeMap::from([("visible".into(), serde_json::json!(template.visible)), ("enabled".into(), serde_json::json!(template.enabled))]),
                binding_summary: bindings, branch_key, template_key, source_span: node.source_span.clone(), diagnostic_count: frame.diagnostics.iter().filter(|diagnostic| diagnostic.node_key.as_deref() == Some(&node.key)).count() as u32 }
        }).collect();
        let total = self.program.nodes.len() as u32; let next = offset.saturating_add(limit);
        UiIrOutlinePage { entries, offset, limit, total, next_offset: (next < total).then_some(next) }
    }

    pub fn node(&self, key: &str) -> Option<UiNodeInspection> {
        let node = self.program.nodes.iter().find(|node| node.key == key)?.clone(); let frame = self.frame();
        let state = frame.nodes.iter().find(|state| state.node_key == key)?;
        let template = self.program.node_templates.iter().find(|node| node.node_id.0 == key)?;
        let mut provenance = BTreeMap::new();
        for binding in self.program.binding_records.iter().filter(|binding| binding.node_key == key) { provenance.insert(format!("{:?}", binding.property), format!("input:{}", binding.input_key)); }
        let hidden = !state.visible;
        Some(UiNodeInspection { node: node.clone(), declared_properties: serde_json::json!(template), effective_properties: serde_json::json!(state), provenance,
            layout: frame.logical_layout.iter().find(|layout| layout.node_key == key).cloned(), clip: frame.clips.get(key).copied(),
            visibility_reason: if hidden { "branch predicate or visible binding resolved false".into() } else { "visible".into() },
            resources: self.program_resource_refs(key), events: self.program.event_records.iter().filter(|event| event.node_key == key).cloned().collect(), source_span: node.source_span,
            diagnostics: frame.diagnostics.into_iter().filter(|diagnostic| diagnostic.node_key.as_deref() == Some(key)).collect() })
    }

    pub fn validate_flow(&self, flow: &str) -> Vec<UiDiagnostic> {
        match crate::parse_nui_flow(flow) { Ok(_) => Vec::new(), Err(error) => error.diagnostics.into_iter().map(|item| diagnostic(&item.code, &item.message, None, self.program.revision.revision)).collect() }
    }
    pub fn dry_run_patch(&self, patch: &UiIrPatch) -> UiPatchDryRun {
        match apply_nui_ir_patch(&self.document, patch) {
            Ok(document) => match compile_ui_program(&document, next_revision(&self.program.revision), self.inputs.schema()) {
                Ok(program) => UiPatchDryRun { accepted: true, base_revision: self.document.revision, resulting_revision: document.revision,
