//!
//! It consumes declared semantic keys and returns a new fragment. It never
//! reaches into the renderer or uses renderer hit identifiers.

use std::net::SocketAddr;

use neon_ipc::{RpcServer, TransportError};
use neon_protocol::{Revision, RpcError, RpcRequest, RpcResponse, RpcStatus};
use neon_ui_schema::{
    TextRef, UiDropPlacement, UiEffect, UiFragment, UiNode, UiNodeId, UiSemanticEvent,
    UiSemanticEventType,
};
use serde_json::{json, Value};

pub struct DemoDragDropDomain {
    revision: Option<Revision>,
}

impl DemoDragDropDomain {
    pub fn new() -> Self {
        Self { revision: None }
    }

    pub fn serve(endpoint: SocketAddr) -> Result<(), TransportError> {
        let server = RpcServer::bind(endpoint)?;
        let mut domain = Self::new();
        server.serve_until(|request| {
            let shutdown = request.method == "service.shutdown";
            (domain.handle(request), !shutdown)
        })
    }

    pub fn handle(&mut self, request: RpcRequest) -> RpcResponse {
        if request.method == "service.shutdown" {
            return accepted(request, self.revision, json!({"state": "accepted"}));
        }
        if request.method != "ui.drag_drop.apply" {
            return rejected(
                request,
                self.revision,
                "unsupported_method",
                "method is not supported",
            );
        }
        let Some(event_value) = request.params.get("event") else {
            return rejected(
                request,
                self.revision,
                "invalid_request",
                "drag/drop event is required",
            );
        };
        let Some(fragment_value) = request.params.get("fragment") else {
            return rejected(
                request,
                self.revision,
                "invalid_request",
                "current fragment is required",
            );
        };
        let event: UiSemanticEvent =
            match serde_json::from_value::<UiSemanticEvent>(event_value.clone()) {
                Ok(event) if event.event == UiSemanticEventType::DragDrop => event,
                _ => {
                    return rejected(
                        request,
                        self.revision,
                        "invalid_drag_drop",
                        "a drag/drop semantic event is required",
                    );
                }
            };
        let mut fragment: UiFragment = match serde_json::from_value(fragment_value.clone()) {
            Ok(fragment) => fragment,
            Err(_) => {
                return rejected(
                    request,
                    self.revision,
                    "invalid_request",
                    "current fragment is invalid",
                );
            }
        };
        if request.expected_revision != Some(fragment.revision)
            || self
                .revision
                .is_some_and(|revision| revision != fragment.revision)
        {
            return rejected(
                request,
                self.revision,
                "revision_conflict",
                "drag/drop fragment revision is stale",
            );
        }
        let Some(drop) = event.drag_drop else {
            return rejected(
                request,
                self.revision,
                "invalid_drag_drop",
                "drag/drop payload is required",
            );
        };
        let Some(template_key) = drop.presentation_template_key else {
            return rejected(
                request,
                self.revision,
                "presentation_template_required",
                "accepted drops require a target-owned template",
            );
        };
        let source_drag_key = fragment.effects.iter().find_map(|effect| match effect {
            UiEffect::DragBinding { binding } if binding.source_node_id.0 == drop.source_key => {
                Some(binding.key.clone())
            }
            _ => None,
        });
        let declared = fragment.effects.iter().any(|effect| matches!(effect,
            UiEffect::DropBinding { binding }
                if binding.intent == event.intent
                    && binding.target_node_id.0 == drop.target_key
                    && source_drag_key.as_deref() == Some(binding.accepts_drag_key.as_str())
                    && binding.placement == drop.placement
                    && binding.presentation_template_key.as_deref() == Some(template_key.as_str())
        ));
        if !declared {
            return rejected(
                request,
                self.revision,
                "drag_drop_not_declared",
                "source, target, placement, or template is not declared",
            );
        }
        let Some(source) = find_node(&fragment.root, &drop.source_key).cloned() else {
            return rejected(
                request,
                self.revision,
                "source_not_found",
                "drag source is not present",
            );
        };
        let Some(target) = find_node(&fragment.root, &drop.target_key) else {
            return rejected(
                request,
                self.revision,
                "target_not_found",
                "drop target is not present",
            );
        };
        let Some(template) = target
            .children
            .iter()
            .find(|node| node.node_id.0 == template_key)
            .cloned()
        else {
            return rejected(
                request,
                self.revision,
                "template_not_owned",
                "presentation template is not owned by the drop target",
            );
        };
        if drop.placement != UiDropPlacement::Into
            && find_parent(&fragment.root, &drop.target_key).is_none()
        {
            return rejected(
                request,
                self.revision,
                "relative_target_has_no_parent",
                "before and after targets must have a parent",
            );
        }
        let label = first_literal(&source).unwrap_or_else(|| source.node_id.0.clone());
        let next_revision = Revision(fragment.revision.0 + 1);
        let mut representation = template;
        namespace_node(
            &mut representation,
            &format!("{}-{}-r{}", template_key, drop.source_key, next_revision.0),
        );
        set_first_literal(&mut representation, &label);
        remove_node(&mut fragment.root, &drop.source_key);
        fragment.effects.retain(|effect| match effect {
            UiEffect::DragBinding { binding } => binding.source_node_id.0 != drop.source_key,
            UiEffect::DropBinding { binding } => {
                source_drag_key.as_deref() != Some(binding.accepts_drag_key.as_str())
            }
            _ => true,
        });
        match drop.placement {
            UiDropPlacement::Into => find_node_mut(&mut fragment.root, &drop.target_key)
                .expect("validated target remains present")
                .children
                .push(representation),
            UiDropPlacement::Before | UiDropPlacement::After => {
                let parent = find_parent_mut(&mut fragment.root, &drop.target_key)
                    .expect("validated relative target retains its parent");
                let target_index = parent
                    .children
                    .iter()
                    .position(|child| child.node_id.0 == drop.target_key)
                    .expect("validated relative target remains present");
                let insertion_index = if drop.placement == UiDropPlacement::Before {
                    target_index
                } else {
                    target_index + 1
                };
                parent.children.insert(insertion_index, representation);
            }
        }
        fragment.revision = next_revision;
        if fragment.validate().is_err() {
            return rejected(
                request,
                self.revision,
                "invalid_fragment",
                "accepted domain revision is invalid",
            );
        }
        self.revision = Some(next_revision);
        accepted(
            request,
            self.revision,
            json!({"fragment": fragment, "state": "accepted"}),
        )
    }
}

fn find_node<'a>(node: &'a UiNode, key: &str) -> Option<&'a UiNode> {
    (node.node_id.0 == key)
        .then_some(node)
        .or_else(|| node.children.iter().find_map(|child| find_node(child, key)))
}

fn find_node_mut<'a>(node: &'a mut UiNode, key: &str) -> Option<&'a mut UiNode> {
    if node.node_id.0 == key {
        return Some(node);
    }
    node.children
        .iter_mut()
        .find_map(|child| find_node_mut(child, key))
}

fn find_parent<'a>(node: &'a UiNode, child_key: &str) -> Option<&'a UiNode> {
    node.children
        .iter()
        .any(|child| child.node_id.0 == child_key)
        .then_some(node)
        .or_else(|| {
            node.children
                .iter()
                .find_map(|child| find_parent(child, child_key))
        })
}

fn find_parent_mut<'a>(node: &'a mut UiNode, child_key: &str) -> Option<&'a mut UiNode> {
    if node
        .children
        .iter()
        .any(|child| child.node_id.0 == child_key)
    {
        return Some(node);
    }
    node.children
        .iter_mut()
        .find_map(|child| find_parent_mut(child, child_key))
}

fn remove_node(node: &mut UiNode, key: &str) -> bool {
    if let Some(index) = node
        .children
        .iter()
        .position(|child| child.node_id.0 == key)
    {
        node.children.remove(index);
        return true;
    }
    node.children
        .iter_mut()
        .any(|child| remove_node(child, key))
}

fn first_literal(node: &UiNode) -> Option<String> {
    match &node.text {
        Some(TextRef::Literal { value }) => Some(value.clone()),
        _ => node.children.iter().find_map(first_literal),
    }
}

fn set_first_literal(node: &mut UiNode, value: &str) -> bool {
    if matches!(node.text, Some(TextRef::Literal { .. })) {
        node.text = Some(TextRef::Literal {
            value: value.into(),
        });
        return true;
    }
    node.children
        .iter_mut()
        .any(|child| set_first_literal(child, value))
}

fn namespace_node(node: &mut UiNode, prefix: &str) {
    node.node_id = UiNodeId(format!("{prefix}-{}", node.node_id.0));
    for child in &mut node.children {
        namespace_node(child, prefix);
    }
}

fn accepted(request: RpcRequest, revision: Option<Revision>, result: Value) -> RpcResponse {
    RpcResponse {
        request_id: request.request_id,
        status: RpcStatus::Accepted,
        revision,
        result: Some(result),
        snapshot: None,
        error: None,
    }
}

fn rejected(
    request: RpcRequest,
    revision: Option<Revision>,
    code: &str,
    message: &str,
) -> RpcResponse {
    RpcResponse {
        request_id: request.request_id,
        status: RpcStatus::Rejected,
        revision,
        result: None,
        snapshot: None,
        error: Some(RpcError {
            code: code.into(),
            message: message.into(),
            current_revision: revision,
            object_id: None,
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{lower_nui_flow_effects, parse_nui_flow};
    use neon_protocol::{ClientIdentity, ClientKind, ProtocolVersion, RequestId, ServiceName};
    use neon_ui_schema::UiFragmentId;

    fn fragment() -> UiFragment {
        let document = parse_nui_flow(include_str!(
            "../../../tests/fixtures/ui/kanban-reparent-workbench.nui"
        ))
        .unwrap();
        let effects = lower_nui_flow_effects(&document);
        UiFragment {
            fragment_id: UiFragmentId("demo".into()),
            revision: Revision(1),
            root: document.ir.root,
            effects,
        }
    }
    fn request(
        fragment: UiFragment,
        drop_key: &str,
        source_key: &str,
        target_key: &str,
        placement: UiDropPlacement,
        template_key: &str,
    ) -> RpcRequest {
        let intent = fragment
            .effects
            .iter()
            .find_map(|effect| match effect {
                UiEffect::DropBinding { binding } if binding.key == drop_key => {
                    Some(binding.intent.clone())
                }
                _ => None,
            })
            .unwrap();
        let event = UiSemanticEvent {
            event: UiSemanticEventType::DragDrop,
            event_id: "drop-1".into(),
            renderer_epoch: 1,
            composition_revision: Revision(1),
            fragment: neon_ui_schema::UiFragmentRevision {
                id: fragment.fragment_id.clone(),
                revision: fragment.revision,
            },
            intent,
            pointer: None,
            focus: None,
            text: None,
            drag_drop: Some(neon_ui_schema::UiDragDropPayload {
                source_key: source_key.into(),
                target_key: target_key.into(),
                placement,
                presentation_template_key: Some(template_key.into()),
            }),
        };
        RpcRequest {
            protocol: "neon3.rpc".into(),
            version: ProtocolVersion { major: 1, minor: 0 },
            request_id: RequestId("drop-1".into()),
            client: ClientIdentity {
                kind: ClientKind::UiRuntime,
                instance_id: "test".into(),
                pid: 1,
                origin: "test".into(),
            },
            target: ServiceName("demo-domain".into()),
            method: "ui.drag_drop.apply".into(),
            params: json!({"event": event, "fragment": fragment}),
            expected_revision: Some(Revision(1)),
            idempotency_key: Some("drop-1".into()),
        }
    }
    #[test]
    fn accepted_drop_returns_a_revisioned_target_template_representation() {
        let mut domain = DemoDragDropDomain { revision: None };
        let response = domain.handle(request(
            fragment(),
            "progress-drop",
            "backlog-card-01",
            "in-progress-panel",
            UiDropPlacement::Into,
            "progress-template",
        ));
        assert_eq!(response.status, RpcStatus::Accepted, "{:?}", response.error);
        let updated: UiFragment =
            serde_json::from_value(response.result.unwrap()["fragment"].clone()).unwrap();
        assert_eq!(updated.revision, Revision(2));
        assert!(find_node(&updated.root, "backlog-card-01").is_none());
        assert!(find_node(
            &updated.root,
            "progress-template-backlog-card-01-r2-progress-template"
        )
        .is_some());
    }

    #[test]
    fn accepted_relative_drops_insert_target_template_representations_as_siblings() {
        let mut domain = DemoDragDropDomain::new();
        let before = domain.handle(request(
            fragment(),
            "progress-audit-drop",
            "backlog-card-02",
            "in-progress-panel",
            UiDropPlacement::Before,
            "progress-template",
        ));
        assert_eq!(before.status, RpcStatus::Accepted, "{:?}", before.error);
        let before_fragment: UiFragment =
            serde_json::from_value(before.result.unwrap()["fragment"].clone()).unwrap();
        let board_columns = find_node(&before_fragment.root, "board-columns").unwrap();
        let progress_index = board_columns
            .children
            .iter()
            .position(|node| node.node_id.0 == "in-progress-panel")
            .unwrap();
        assert_eq!(
            board_columns.children[progress_index - 1].node_id.0,
            "progress-template-backlog-card-02-r2-progress-template"
        );

        let after = DemoDragDropDomain::new().handle(request(
            fragment(),
            "done-bindings-drop",
            "backlog-card-03",
            "done-panel",
            UiDropPlacement::After,
            "accepted-template",
        ));
        assert_eq!(after.status, RpcStatus::Accepted, "{:?}", after.error);
        let after_fragment: UiFragment =
            serde_json::from_value(after.result.unwrap()["fragment"].clone()).unwrap();
        let board_columns = find_node(&after_fragment.root, "board-columns").unwrap();
        let done_index = board_columns
            .children
            .iter()
            .position(|node| node.node_id.0 == "done-panel")
            .unwrap();
        assert_eq!(
            board_columns.children[done_index + 1].node_id.0,
            "accepted-template-backlog-card-03-r2-accepted-template"
        );
    }
}

//! Submits an open NUI Flow fixture through the headless UI runtime.

use std::net::SocketAddr;
use std::time::Duration;

use neon_ipc::RpcClient;
use neon_protocol::{
    ClientIdentity, ClientKind, ProtocolVersion, RequestId, Revision, RpcRequest, ServiceName,
};
use neon_ui_runtime::{
    compile_nui_flow_program, evaluate_ui_program, lower_nui_flow_effects, parse_nui_flow,
    UiInputStore, UiLocalPresentationState,
};
use neon_ui_schema::{
    NuiFlowDocument, UiBounds, UiCommand, UiCpuViewport, UiFragment, UiFragmentId,
    UiFragmentSubmission, UiNode, UiNodeKind, UiProgramCapability, UiProgramCapabilityOwner,
    UiProgramCapabilityStatus, UiProgramResource, UiProgramResourceKind, UiProgramRevision,
    UI_PROGRAM_BOUNDED_STRUCTURE_CAPABILITY_NAME, UI_PROGRAM_CAPABILITY_NAME,
    UI_PROGRAM_SCHEMA_VERSION, UI_PROGRAM_SEMANTIC_EVENT_CAPABILITY_NAME,
    UI_PROGRAM_TEXT_REGISTRY_CAPABILITY_NAME,
};
use serde_json::json;

const ASSET_REVIEW_SOURCE: &str =
    include_str!("../../../../tests/fixtures/ui/asset-review-workbench.nui");
const KANBAN_REPARENT_SOURCE: &str =
    include_str!("../../../../tests/fixtures/ui/kanban-reparent-workbench.nui");

fn main() {
    let mut args = std::env::args().skip(1);
    let case = args.next().expect("case name is required");
    let endpoint = args
        .next()
        .unwrap_or_else(|| "127.0.0.1:40102".into())
        .parse::<SocketAddr>()
        .expect("UI runtime endpoint must be a socket address");
    let source = match case.as_str() {
        "asset-review" => ASSET_REVIEW_SOURCE,
        "kanban-reparent" => KANBAN_REPARENT_SOURCE,
        _ => panic!("unsupported NUI Flow case: {case}"),
    };
    let document = parse_nui_flow(source).expect("NUI Flow fixture must parse");
    let effects = lower_nui_flow_effects(&document);
    let fragment = UiFragment {
        fragment_id: UiFragmentId(format!("nui-flow-case-{case}")),
        revision: neon_protocol::Revision(1),
        root: initial_visible_root(&document),
        effects,
    };
    let request = RpcRequest {
        protocol: "neon3.rpc".into(),
        version: ProtocolVersion { major: 1, minor: 0 },
        request_id: RequestId(format!("nui-flow-case-{case}-submit")),
        client: ClientIdentity {
            kind: ClientKind::Cli,
            instance_id: "nui-flow-demo".into(),
            pid: std::process::id(),
            origin: "nui-flow-demo".into(),
        },
        target: ServiceName("ui-runtime".into()),
        method: "ui.fragment.submit".into(),
        params: json!(UiCommand::SubmitFragment {
            submission: UiFragmentSubmission::new(fragment)
        }),
        expected_revision: None,
        idempotency_key: Some(format!("nui-flow-case-{case}-submit-v1")),
    };
    for attempt in 1..=10 {
        match RpcClient::connect(endpoint).and_then(|mut client| client.call(&request)) {
            Ok(response) if matches!(response.status, neon_protocol::RpcStatus::Accepted) => return,
            Ok(response)
                if response.error.as_ref().is_some_and(|error| {
                    error.code == "window_compositor_stale"
                        && error.current_revision == Some(neon_protocol::Revision(1))
                }) =>
            {
                return;
            }
            Ok(response) if attempt == 10 => panic!("NUI Flow case rejected: {:?}", response.error),
            Err(error) if attempt == 10 => panic!("submit NUI Flow case: {error}"),
            _ => std::thread::sleep(Duration::from_millis(100)),
        }
    }
}

fn initial_visible_root(document: &NuiFlowDocument) -> UiNode {
    let mut compile_document = document.clone();
    declare_preview_fallbacks(
        &compile_document.ir.root,
        &mut compile_document.ir.resources,
    );
    let revision = demo_program_revision(&document.ir.surface_id.0);
    let program = compile_nui_flow_program(&compile_document, revision.clone())
        .expect("NUI Flow fixture must compile for initial visibility evaluation");
    let inputs = UiInputStore::activate(revision, document.input_schema.clone())
        .expect("NUI Flow defaults must activate");
    let frame = evaluate_ui_program(
        &program,
        &inputs.snapshot(),
        UiCpuViewport {
            logical_bounds: UiBounds {
                x: 0.0,
                y: 0.0,
                width: 1280.0,
                height: 800.0,
            },
            revision: Revision(1),
        },
        &UiLocalPresentationState::default(),
    );
    let visibility = frame
        .nodes
        .into_iter()
        .map(|node| (node.node_key, node.visible))
        .collect();
    let mut root = document.ir.root.clone();
    apply_evaluated_visibility(&mut root, &visibility);
    root
}

fn declare_preview_fallbacks(node: &UiNode, resources: &mut Vec<UiProgramResource>) {
    let kind = match node.kind {
        UiNodeKind::Image => Some(UiProgramResourceKind::Image),
        UiNodeKind::RenderSurface => Some(UiProgramResourceKind::RenderSurface),
        _ => None,
    };
    if let Some(kind) = kind {
        if !resources.iter().any(|resource| resource.key == node.node_id.0) {
            resources.push(UiProgramResource {
                key: node.node_id.0.clone(),
                kind,
                has_fallback: true,
            });
        }
    }
    for child in &node.children {
        declare_preview_fallbacks(child, resources);
    }
}

fn apply_evaluated_visibility(
    node: &mut UiNode,
    visibility: &std::collections::BTreeMap<String, bool>,
) {
    node.visible &= visibility.get(&node.node_id.0).copied().unwrap_or(false);
    for child in &mut node.children {
        apply_evaluated_visibility(child, visibility);
    }
}

fn demo_program_revision(surface_id: &str) -> UiProgramRevision {
    UiProgramRevision {
        program_id: format!("{surface_id}.demo"),
        revision: Revision(1),
        schema_version: UI_PROGRAM_SCHEMA_VERSION,
        capabilities: [
            UI_PROGRAM_CAPABILITY_NAME,
            UI_PROGRAM_TEXT_REGISTRY_CAPABILITY_NAME,
            UI_PROGRAM_BOUNDED_STRUCTURE_CAPABILITY_NAME,
            UI_PROGRAM_SEMANTIC_EVENT_CAPABILITY_NAME,
        ]
        .into_iter()
        .map(|name| UiProgramCapability {
            name: name.into(),
            version: 1,
            owner: UiProgramCapabilityOwner::SharedContract,
            status: UiProgramCapabilityStatus::Supported,
        })
        .collect(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn initial_visibility_hides_inactive_kanban_status_branches() {
        let document = parse_nui_flow(KANBAN_REPARENT_SOURCE).unwrap();
        let root = initial_visible_root(&document);
        let mut visible = std::collections::BTreeMap::new();
        fn collect(node: &UiNode, visible: &mut std::collections::BTreeMap<String, bool>) {
            visible.insert(node.node_id.0.clone(), node.visible);
            for child in &node.children {
                collect(child, visible);
            }
        }
        collect(&root, &mut visible);
        assert_eq!(visible["reparent-pending"], false);
        assert_eq!(visible["reparent-accepted"], false);
        assert_eq!(visible["reparent-rejected"], false);
    }
}

//! Public protocol client helpers. This crate must not create windows or GPU objects.

use std::net::SocketAddr;

use neon_ipc::{RpcClient, TransportError};
use neon_protocol::{
    ClientIdentity, ClientKind, ProtocolVersion, RequestId, Revision, RpcRequest, RpcResponse,
    RpcStatus, ServiceName,
};
use neon_ui_schema::{
    UiBounds, UiCommand, UiEffect, UiFragment, UiFragmentId, UiFragmentRevision, UiFragmentSubmission, UiIntent, UiNode, UiNodeId, UiNodeKind, UiPointerMetadata, UiSemanticEvent, UiSemanticEventType, UiStyle, TextRef,
};
use serde_json::{Value, json};

pub const SCENARIO_ID: &str = "ui.static-fragment.submit.v1";
pub const DETAIL_TOGGLE_SCENARIO_ID: &str = "ui.detail-toggle.v1";

pub fn run_headless_scenario(endpoint: SocketAddr) -> Result<Value, TransportError> {
    let mut steps = Vec::new();
    let health = call(endpoint, "health-1", "service.health", json!({}), None)?;
    record_step(&mut steps, "service.health", &health);
    if health.status != RpcStatus::Accepted
        || health.result.as_ref().and_then(|value| value.get("status")) != Some(&json!("healthy"))
    {
        return Ok(failed(steps, &health));
    }

    let describe = call(endpoint, "describe-1", "service.describe", json!({}), None)?;
    record_step(&mut steps, "service.describe", &describe);
    if describe.status != RpcStatus::Accepted {
        return Ok(failed(steps, &describe));
    }

    let snapshot = call(endpoint, "snapshot-1", "debug.snapshot.get", json!({}), None)?;
    record_step(&mut steps, "debug.snapshot.get", &snapshot);
    if snapshot.status != RpcStatus::Accepted {
        return Ok(failed(steps, &snapshot));
    }

    let command = UiCommand::SubmitFragment {
        submission: UiFragmentSubmission::new(static_fragment(Revision(1))),
    };
    let submit = call(
        endpoint,
        "submit-1",
        "wgpu.ui.submit_fragment",
        json!(command),
        Some("submit-key-1"),
    )?;
    record_step(&mut steps, "wgpu.ui.submit_fragment", &submit);
    if submit.status != RpcStatus::Accepted {
        return Ok(failed(steps, &submit));
    }

    let duplicate = call(
        endpoint,
        "submit-duplicate-1",
        "wgpu.ui.submit_fragment",
        json!(UiCommand::SubmitFragment {
            submission: UiFragmentSubmission::new(static_fragment(Revision(2)))
        }),
        Some("submit-key-1"),
    )?;
    record_step(&mut steps, "wgpu.ui.submit_fragment.retry", &duplicate);
    if duplicate.status != RpcStatus::Accepted {
        return Ok(failed(steps, &duplicate));
    }

    let fragment_snapshot = call(
        endpoint,
        "fragment-snapshot-1",
        "wgpu.ui.fragment.snapshot",
        json!({"fragment_id": "cli-static-fragment"}),
        None,
    )?;
    record_step(&mut steps, "wgpu.ui.fragment.snapshot", &fragment_snapshot);
    if fragment_snapshot.status != RpcStatus::Accepted {
        return Ok(failed(steps, &fragment_snapshot));
    }

    let graph = call(endpoint, "graph-1", "wgpu.render.graph.snapshot", json!({}), None)?;
    record_step(&mut steps, "wgpu.render.graph.snapshot", &graph);
    if graph.status != RpcStatus::Accepted {
        return Ok(failed(steps, &graph));
    }

    let diagnostics = call(
        endpoint,
        "diagnostics-1",
        "wgpu.render.diagnostics",
        json!({}),
        None,
    )?;
    record_step(&mut steps, "wgpu.render.diagnostics", &diagnostics);
    if diagnostics.status != RpcStatus::Accepted
        || diagnostics
            .result
            .as_ref()
            .and_then(|value| value.get("fragment_count"))
            != Some(&json!(1))
    {
        return Ok(failed(steps, &diagnostics));
    }

    let receipt = call(
        endpoint,
        "receipt-1",
        "debug.command.get",
        json!({"request_id": "submit-1"}),
        None,
    )?;
    record_step(&mut steps, "debug.command.get", &receipt);
    if receipt.status != RpcStatus::Accepted {
        return Ok(failed(steps, &receipt));
