use std::net::SocketAddr;

use neon_ipc::{RpcServer, TransportError};
use neon_protocol::{Revision, RpcError, RpcRequest, RpcResponse, RpcStatus};
use neon_ui_schema::{
    TextRef, UiDropPlacement, UiEffect, UiFragment, UiNode, UiNodeId, UiSemanticEvent,
    UiSemanticEventType,
};
use serde_json::{json, Value};

pub struct DemoDragDropDomain {
    revision: Option<Revision>,
}

impl DemoDragDropDomain {
    pub fn new() -> Self {
        Self { revision: None }
    }

    pub fn serve(endpoint: SocketAddr) -> Result<(), TransportError> {
        let server = RpcServer::bind(endpoint)?;
        let mut domain = Self::new();
        server.serve_until(|request| {
            let shutdown = request.method == "service.shutdown";
            (domain.handle(request), !shutdown)
        })
    }

    pub fn handle(&mut self, request: RpcRequest) -> RpcResponse {
        if request.method == "service.shutdown" {
            return accepted(request, self.revision, json!({"state": "accepted"}));
        }
        if request.method != "ui.drag_drop.apply" {
            return rejected(
                request,
                self.revision,
                "unsupported_method",
                "method is not supported",
            );
        }
        let Some(event_value) = request.params.get("event") else {
            return rejected(
                request,
                self.revision,
                "invalid_request",
                "drag/drop event is required",
            );
        };
        let Some(fragment_value) = request.params.get("fragment") else {
            return rejected(
                request,
                self.revision,
                "invalid_request",
                "current fragment is required",
            );
        };
        let event: UiSemanticEvent =
            match serde_json::from_value::<UiSemanticEvent>(event_value.clone()) {
                Ok(event) if event.event == UiSemanticEventType::DragDrop => event,
                _ => {
                    return rejected(
                        request,
                        self.revision,
                        "invalid_drag_drop",
                        "a drag/drop semantic event is required",
                    );
                }
            };
        let mut fragment: UiFragment = match serde_json::from_value(fragment_value.clone()) {
            Ok(fragment) => fragment,
            Err(_) => {
                return rejected(
                    request,
                    self.revision,
                    "invalid_request",
                    "current fragment is invalid",
                );
            }
        };
        if request.expected_revision != Some(fragment.revision)
            || self
                .revision
                .is_some_and(|revision| revision != fragment.revision)
        {
            return rejected(
                request,
                self.revision,
                "revision_conflict",
                "drag/drop fragment revision is stale",
            );
        }
        let Some(drop) = event.drag_drop else {
            return rejected(
                request,
                self.revision,
                "invalid_drag_drop",
                "drag/drop payload is required",
            );
        };
        let Some(template_key) = drop.presentation_template_key else {
            return rejected(
                request,
                self.revision,
                "presentation_template_required",
                "accepted drops require a target-owned template",
            );
        };
        let source_drag_key = fragment.effects.iter().find_map(|effect| match effect {
            UiEffect::DragBinding { binding } if binding.source_node_id.0 == drop.source_key => {
                Some(binding.key.clone())
            }
            _ => None,
        });
        let declared = fragment.effects.iter().any(|effect| matches!(effect,
            UiEffect::DropBinding { binding }
                if binding.intent == event.intent
                    && binding.target_node_id.0 == drop.target_key
                    && source_drag_key.as_deref() == Some(binding.accepts_drag_key.as_str())
                    && binding.placement == drop.placement
                    && binding.presentation_template_key.as_deref() == Some(template_key.as_str())
        ));
        if !declared {
            return rejected(
                request,
                self.revision,
                "drag_drop_not_declared",
                "source, target, placement, or template is not declared",
            );
        }
        let Some(source) = find_node(&fragment.root, &drop.source_key).cloned() else {
            return rejected(
                request,
                self.revision,
                "source_not_found",
                "drag source is not present",
            );
        };
        let Some(target) = find_node(&fragment.root, &drop.target_key) else {
            return rejected(
                request,
                self.revision,
                "target_not_found",
                "drop target is not present",
            );
        };
        let Some(template) = target
            .children
            .iter()
            .find(|node| node.node_id.0 == template_key)
            .cloned()
        else {
            return rejected(
                request,
                self.revision,
                "template_not_owned",
                "presentation template is not owned by the drop target",
            );
        };
        if drop.placement != UiDropPlacement::Into
            && find_parent(&fragment.root, &drop.target_key).is_none()
        {
            return rejected(
                request,
                self.revision,
                "relative_target_has_no_parent",
                "before and after targets must have a parent",
            );
        }
        let label = first_literal(&source).unwrap_or_else(|| source.node_id.0.clone());
        let next_revision = Revision(fragment.revision.0 + 1);
        let mut representation = template;
        namespace_node(
            &mut representation,
            &format!("{}-{}-r{}", template_key, drop.source_key, next_revision.0),
        );
        set_first_literal(&mut representation, &label);
        remove_node(&mut fragment.root, &drop.source_key);
        fragment.effects.retain(|effect| match effect {
            UiEffect::DragBinding { binding } => binding.source_node_id.0 != drop.source_key,
            UiEffect::DropBinding { binding } => {
                source_drag_key.as_deref() != Some(binding.accepts_drag_key.as_str())
            }
            _ => true,
        });
        match drop.placement {
            UiDropPlacement::Into => find_node_mut(&mut fragment.root, &drop.target_key)
                .expect("validated target remains present")
                .children
                .push(representation),
            UiDropPlacement::Before | UiDropPlacement::After => {
                let parent = find_parent_mut(&mut fragment.root, &drop.target_key)
                    .expect("validated relative target retains its parent");
                let target_index = parent
                    .children
                    .iter()
                    .position(|child| child.node_id.0 == drop.target_key)
                    .expect("validated relative target remains present");
                let insertion_index = if drop.placement == UiDropPlacement::Before {
                    target_index
                } else {
                    target_index + 1
                };
                parent.children.insert(insertion_index, representation);
            }
        }
        fragment.revision = next_revision;
        if fragment.validate().is_err() {
            return rejected(
                request,
                self.revision,
                "invalid_fragment",
                "accepted domain revision is invalid",
            );
        }
        self.revision = Some(next_revision);
        accepted(
            request,
            self.revision,
            json!({"fragment": fragment, "state": "accepted"}),
        )
    }
}

fn find_node<'a>(node: &'a UiNode, key: &str) -> Option<&'a UiNode> {
    (node.node_id.0 == key)
        .then_some(node)
        .or_else(|| node.children.iter().find_map(|child| find_node(child, key)))
}

fn find_node_mut<'a>(node: &'a mut UiNode, key: &str) -> Option<&'a mut UiNode> {
    if node.node_id.0 == key {
        return Some(node);
    }
    node.children
        .iter_mut()
        .find_map(|child| find_node_mut(child, key))
}

fn find_parent<'a>(node: &'a UiNode, child_key: &str) -> Option<&'a UiNode> {
    node.children
        .iter()
        .any(|child| child.node_id.0 == child_key)
        .then_some(node)
        .or_else(|| {
            node.children
                .iter()
                .find_map(|child| find_parent(child, child_key))
        })
}

fn find_parent_mut<'a>(node: &'a mut UiNode, child_key: &str) -> Option<&'a mut UiNode> {
    if node
        .children
        .iter()
        .any(|child| child.node_id.0 == child_key)
    {
        return Some(node);
    }
    node.children
        .iter_mut()
        .find_map(|child| find_parent_mut(child, child_key))
}

fn remove_node(node: &mut UiNode, key: &str) -> bool {
    if let Some(index) = node
        .children
        .iter()
        .position(|child| child.node_id.0 == key)
    {
        node.children.remove(index);
        return true;
    }
    node.children
        .iter_mut()
        .any(|child| remove_node(child, key))
}

fn first_literal(node: &UiNode) -> Option<String> {
    match &node.text {
        Some(TextRef::Literal { value }) => Some(value.clone()),
        _ => node.children.iter().find_map(first_literal),
    }
}

fn set_first_literal(node: &mut UiNode, value: &str) -> bool {
    if matches!(node.text, Some(TextRef::Literal { .. })) {
        node.text = Some(TextRef::Literal {
            value: value.into(),
        });
        return true;
    }
    node.children
        .iter_mut()
        .any(|child| set_first_literal(child, value))
}

fn namespace_node(node: &mut UiNode, prefix: &str) {
    node.node_id = UiNodeId(format!("{prefix}-{}", node.node_id.0));
    for child in &mut node.children {
        namespace_node(child, prefix);
    }
}

fn accepted(request: RpcRequest, revision: Option<Revision>, result: Value) -> RpcResponse {
    RpcResponse {
        request_id: request.request_id,
        status: RpcStatus::Accepted,
        revision,
        result: Some(result),
        snapshot: None,
        error: None,
    }
}

fn rejected(
    request: RpcRequest,
    revision: Option<Revision>,
    code: &str,
    message: &str,
) -> RpcResponse {
    RpcResponse {
        request_id: request.request_id,
        status: RpcStatus::Rejected,
        revision,
        result: None,
        snapshot: None,
        error: Some(RpcError {
            code: code.into(),
            message: message.into(),
            current_revision: revision,
            object_id: None,
        }),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{lower_nui_flow_effects, parse_nui_flow};
    use neon_protocol::{ClientIdentity, ClientKind, ProtocolVersion, RequestId, ServiceName};
    use neon_ui_schema::UiFragmentId;

    fn fragment() -> UiFragment {
        let document = parse_nui_flow(include_str!(
            "../../../tests/fixtures/ui/kanban-reparent-workbench.nui"
        ))
        .unwrap();
        let effects = lower_nui_flow_effects(&document);
        UiFragment {
            fragment_id: UiFragmentId("demo".into()),
            revision: Revision(1),
            root: document.ir.root,
            effects,
        }
    }
    fn request(
        fragment: UiFragment,
        drop_key: &str,
        source_key: &str,
        target_key: &str,
        placement: UiDropPlacement,
        template_key: &str,
    ) -> RpcRequest {
        let intent = fragment
            .effects
            .iter()
            .find_map(|effect| match effect {
                UiEffect::DropBinding { binding } if binding.key == drop_key => {
                    Some(binding.intent.clone())
                }
                _ => None,
            })
            .unwrap();
        let event = UiSemanticEvent {
            event: UiSemanticEventType::DragDrop,
            event_id: "drop-1".into(),
            renderer_epoch: 1,
            composition_revision: Revision(1),
            fragment: neon_ui_schema::UiFragmentRevision {
                id: fragment.fragment_id.clone(),
                revision: fragment.revision,
            },
            intent,
            pointer: None,
            focus: None,
            text: None,
            drag_drop: Some(neon_ui_schema::UiDragDropPayload {
                source_key: source_key.into(),
                target_key: target_key.into(),
                placement,
                presentation_template_key: Some(template_key.into()),
            }),
        };
        RpcRequest {
            protocol: "neon3.rpc".into(),
            version: ProtocolVersion { major: 1, minor: 0 },
            request_id: RequestId("drop-1".into()),
            client: ClientIdentity {
                kind: ClientKind::UiRuntime,
                instance_id: "test".into(),
                pid: 1,
                origin: "test".into(),
            },
            target: ServiceName("demo-domain".into()),
            method: "ui.drag_drop.apply".into(),
            params: json!({"event": event, "fragment": fragment}),
            expected_revision: Some(Revision(1)),
            idempotency_key: Some("drop-1".into()),
        }
    }
    #[test]
    fn accepted_drop_returns_a_revisioned_target_template_representation() {
        let mut domain = DemoDragDropDomain { revision: None };
        let response = domain.handle(request(
            fragment(),
            "progress-drop",
            "backlog-card-01",
            "in-progress-panel",
            UiDropPlacement::Into,
            "progress-template",
        ));
        assert_eq!(response.status, RpcStatus::Accepted, "{:?}", response.error);
        let updated: UiFragment =
            serde_json::from_value(response.result.unwrap()["fragment"].clone()).unwrap();
        assert_eq!(updated.revision, Revision(2));
        assert!(find_node(&updated.root, "backlog-card-01").is_none());
        assert!(find_node(
            &updated.root,
            "progress-template-backlog-card-01-r2-progress-template"
        )
        .is_some());
    }

    #[test]
    fn accepted_relative_drops_insert_target_template_representations_as_siblings() {
        let mut domain = DemoDragDropDomain::new();
        let before = domain.handle(request(
            fragment(),
            "progress-audit-drop",
            "backlog-card-02",
            "in-progress-panel",
            UiDropPlacement::Before,
            "progress-template",
        ));
        assert_eq!(before.status, RpcStatus::Accepted, "{:?}", before.error);
        let before_fragment: UiFragment =
            serde_json::from_value(before.result.unwrap()["fragment"].clone()).unwrap();
        let board_columns = find_node(&before_fragment.root, "board-columns").unwrap();
        let progress_index = board_columns
            .children
            .iter()
            .position(|node| node.node_id.0 == "in-progress-panel")
            .unwrap();
        assert_eq!(
            board_columns.children[progress_index - 1].node_id.0,
            "progress-template-backlog-card-02-r2-progress-template"
        );

        let after = DemoDragDropDomain::new().handle(request(
            fragment(),
            "done-bindings-drop",
            "backlog-card-03",
            "done-panel",
            UiDropPlacement::After,
            "accepted-template",
        ));
        assert_eq!(after.status, RpcStatus::Accepted, "{:?}", after.error);
        let after_fragment: UiFragment =
            serde_json::from_value(after.result.unwrap()["fragment"].clone()).unwrap();
        let board_columns = find_node(&after_fragment.root, "board-columns").unwrap();
        let done_index = board_columns
            .children
            .iter()
            .position(|node| node.node_id.0 == "done-panel")
            .unwrap();
        assert_eq!(
            board_columns.children[done_index + 1].node_id.0,
            "accepted-template-backlog-card-03-r2-accepted-template"
        );
    }
}
//! Headless authoring inspection, dry-run, and deterministic replay support.
//! It is intentionally built on the CPU program backend and never serializes
//! renderer handles, physical coordinates, or unapproved text contents.

use std::collections::BTreeMap;

use neon_protocol::Revision;
use neon_ui_schema::{
    UiCpuFrameOutput, UiCpuViewport, UiDebugBundle, UiDiagnostic, UiDiagnosticSeverity,
    UiInputFrame, UiInputSchema, UiIrDocument, UiIrOutlineEntry, UiIrOutlinePage, UiIrPatch,
    UiLayoutDiagnosticSnapshot, UiNodeInspection, UiPatchDryRun, UiProgram, UiProgramDescription,
    UiProgramRevision, UiResolvedInputs, UiTextHandle, UiTextHandleDiagnostic,
    UiTextHandleStatus, UiTextRegistryDebugSnapshot, UiProgramSemanticEvent,
};

use crate::{apply_nui_ir_patch, compile_ui_program, evaluate_ui_program, UiInputStore, UiInputWriter,
    UiLocalPresentationState, UiProgramSemanticEventRouter, UiRepeatStore, UiTextRegistry};

#[derive(Clone, Debug, PartialEq)]
pub struct UiReplayResult {
    pub frames: Vec<UiCpuFrameOutput>,
    pub diagnostics: Vec<UiDiagnostic>,
    pub matched_expected_frames: bool,
}

/// Runtime-owned state for the public debug methods. The domain is still
/// responsible for supplying frames; this facade only validates and explains.
pub struct UiDebugSession {
    document: UiIrDocument,
    program: UiProgram,
    inputs: UiInputStore,
    initial_inputs: UiResolvedInputs,
    text: UiTextRegistry,
    repeats: UiRepeatStore,
    events: UiProgramSemanticEventRouter,
    input_timeline: Vec<UiInputFrame>,
    repeat_timeline: Vec<neon_ui_schema::UiRepeatFrame>,
    event_timeline: Vec<UiProgramSemanticEvent>,
    viewport: UiCpuViewport,
    source_hash: String,
}

impl UiDebugSession {
    pub fn activate(document: UiIrDocument, revision: UiProgramRevision, schema: UiInputSchema,
        text: UiTextRegistry, viewport: UiCpuViewport, flow_source: &str, renderer_epoch: u64,
    ) -> Result<Self, String> {
        let program = compile_ui_program(&document, revision.clone(), &schema).map_err(|error| error.message)?;
        let inputs = UiInputStore::activate(revision, schema).map_err(|error| error.message.to_owned())?;
        let events = UiProgramSemanticEventRouter::new(program.clone(), inputs.snapshot(), renderer_epoch);
        let initial_inputs = inputs.snapshot();
        Ok(Self { document, program, inputs, initial_inputs, text, repeats: UiRepeatStore::default(), events,
            input_timeline: Vec::new(), repeat_timeline: Vec::new(), event_timeline: Vec::new(), viewport, source_hash: hash(flow_source) })
    }

    pub fn outline(&self, offset: u32, limit: u32) -> UiIrOutlinePage {
        let limit = limit.clamp(1, 256); let frame = self.frame();
        let entries = self.program.nodes.iter().skip(offset as usize).take(limit as usize).map(|node| {
            let template = self.program.node_templates.iter().find(|value| value.node_id.0 == node.key).expect("compiled template");
            let bindings = self.program.binding_records.iter().filter(|binding| binding.node_key == node.key)
                .map(|binding| format!("{}:{:?}", binding.input_key, binding.property)).collect();
            let branch_key = self.program.branch_records.iter().find(|branch| branch.node_range.contains(&node.key)).map(|branch| branch.branch_key.clone());
            let template_key = self.program.template_records.iter().find(|record| record.node_range.contains(&node.key)).map(|record| record.template_key.clone());
            UiIrOutlineEntry { node_key: node.key.clone(), parent_key: node.parent_key.clone(), kind: node.kind.clone(),
                static_properties: BTreeMap::from([("visible".into(), serde_json::json!(template.visible)), ("enabled".into(), serde_json::json!(template.enabled))]),
                binding_summary: bindings, branch_key, template_key, source_span: node.source_span.clone(), diagnostic_count: frame.diagnostics.iter().filter(|diagnostic| diagnostic.node_key.as_deref() == Some(&node.key)).count() as u32 }
        }).collect();
        let total = self.program.nodes.len() as u32; let next = offset.saturating_add(limit);
        UiIrOutlinePage { entries, offset, limit, total, next_offset: (next < total).then_some(next) }
    }

    pub fn node(&self, key: &str) -> Option<UiNodeInspection> {
        let node = self.program.nodes.iter().find(|node| node.key == key)?.clone(); let frame = self.frame();
        let state = frame.nodes.iter().find(|state| state.node_key == key)?;
        let template = self.program.node_templates.iter().find(|node| node.node_id.0 == key)?;
        let mut provenance = BTreeMap::new();
        for binding in self.program.binding_records.iter().filter(|binding| binding.node_key == key) { provenance.insert(format!("{:?}", binding.property), format!("input:{}", binding.input_key)); }
        let hidden = !state.visible;
        Some(UiNodeInspection { node: node.clone(), declared_properties: serde_json::json!(template), effective_properties: serde_json::json!(state), provenance,
            layout: frame.logical_layout.iter().find(|layout| layout.node_key == key).cloned(), clip: frame.clips.get(key).copied(),
            visibility_reason: if hidden { "branch predicate or visible binding resolved false".into() } else { "visible".into() },
            resources: self.program_resource_refs(key), events: self.program.event_records.iter().filter(|event| event.node_key == key).cloned().collect(), source_span: node.source_span,
            diagnostics: frame.diagnostics.into_iter().filter(|diagnostic| diagnostic.node_key.as_deref() == Some(key)).collect() })
    }

    pub fn validate_flow(&self, flow: &str) -> Vec<UiDiagnostic> {
        match crate::parse_nui_flow(flow) { Ok(_) => Vec::new(), Err(error) => error.diagnostics.into_iter().map(|item| diagnostic(&item.code, &item.message, None, self.program.revision.revision)).collect() }
    }
    pub fn dry_run_patch(&self, patch: &UiIrPatch) -> UiPatchDryRun {
        match apply_nui_ir_patch(&self.document, patch) {
            Ok(document) => match compile_ui_program(&document, next_revision(&self.program.revision), self.inputs.schema()) {
                Ok(program) => UiPatchDryRun { accepted: true, base_revision: self.document.revision, resulting_revision: document.revision,
                    diff: serde_json::json!({"node_count": {"before": self.program.nodes.len(), "after": program.nodes.len()}}), impacted_nodes: program.nodes.iter().map(|node| node.key.clone()).collect(), required_input_schema_changes: Vec::new(), budget: program.resource_budget, diagnostics: Vec::new() },
                Err(error) => rejected_patch(self.document.revision, self.program.resource_budget.clone(), error.code, error.message),
            },
            Err(error) => rejected_patch(self.document.revision, self.program.resource_budget.clone(), "ui_ir_patch_rejected", error.diagnostics.into_iter().map(|item| item.message).collect::<Vec<_>>().join("; ")),
        }
    }
    pub fn layout_diagnostics(&self) -> UiLayoutDiagnosticSnapshot {
        let frame = self.frame(); let visibility_reasons = frame.nodes.iter().map(|node| (node.node_key.clone(), if node.visible { "visible".into() } else { "branch predicate or visible binding resolved false".into() })).collect();
        UiLayoutDiagnosticSnapshot { program_revision: self.program.revision.clone(), input_revision: frame.input_revision, logical_layout: frame.logical_layout, clips: frame.clips, visibility_reasons, diagnostics: frame.diagnostics, gpu_differential_mismatches: Vec::new() }
    }
    pub fn input_schema(&self) -> &UiInputSchema { self.inputs.schema() }
    pub fn input_snapshot(&self) -> UiResolvedInputs { self.inputs.snapshot() }
    pub fn text_handle(&self, handle: UiTextHandle, include_text: bool) -> (UiTextHandleDiagnostic, Option<String>) {
        let status = self.text.handle_diagnostic(handle); let content = if include_text { self.text.snapshot(true).records.into_iter().find(|record| record.handle == handle).map(|record| record.text) } else { None }; (status, content)
    }
    pub fn event_trace(&self) -> &[neon_ui_schema::UiEventTraceRecord] { self.events.trace() }
    pub fn description(&self) -> UiProgramDescription { UiProgramDescription { revision: self.program.revision.clone(), layout_hash: self.program.layout_hash.clone(), active_capabilities: self.program.revision.capabilities.clone(), resource_budget: self.program.resource_budget.clone(), runtime_high_water_marks: BTreeMap::from([("nodes".into(), self.program.nodes.len() as u32), ("input_slots".into(), self.inputs.schema().slots.len() as u32)]), overflow_counters: BTreeMap::new() } }
    pub fn bundle(&self) -> UiDebugBundle { UiDebugBundle { version: 1, flow_source_hash: self.source_hash.clone(), ir_hash: hash(&serde_json::to_string(&self.document).expect("IR serializes")), program: self.program.clone(), schema: self.inputs.schema().clone(), initial_inputs: self.initial_inputs.clone(), input_timeline: self.input_timeline.clone(), repeat_timeline: self.repeat_timeline.clone(), text_registry: self.text.debug_snapshot(), event_timeline: self.event_timeline.clone(), viewport: self.viewport, expected_frames: vec![self.frame()], diagnostics: Vec::new(), gpu_readbacks: None } }
