            first.result.as_ref().unwrap()["value"]["diagnostics"],
            "expanded"
        );
        assert_eq!(first.revision, Some(Revision(1)));
        let retry = runtime.handle_service_request(action(
            "toggle-retry",
            0,
            "toggle-key",
            event(json!({"type": "DIAGNOSTICS_TOGGLE"})),
        ));
